/* DAWAH X — ahmad, অধ্যায় 18 · খণ্ড 18 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][18]=[[3401,3401,"","ঈশ্বর তার কাছে প্রার্থনা করেছিলেন এবং তিনি সেই বিষয়ের ওপর দিয়ে দিয়েছিলেন । -a-a-a--a------------------------------aa----aa-------------aaaaaa------------aaaaaaaa----------------aaaaaaaaaaaaa---------------------aaaaaaaaaaaaaaaaa-----------------------------------aaa------------------------------a-a-------------------------------- A-a-a-a-a-a-a--a--a--Aa---a-a-A-a-a","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي الْكَنُودِ ‏ ‏أَصَبْتُ خَاتَمًا يَوْمًا فَذَكَرَهُ فَرَآهُ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏فِي يَدِهِ فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ حَلَقَةِ الذَّهَبِ ‏","","",""],[3402,3402,"","আমরা বাবার দুই বছর কথা বলেছি তার জীবনের সর্বোত্তম কামনার জন্য, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তাকে দু'টি অ্যাপার্টমেন্টে আত্মসমর্পণ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي مَعْمَرٍ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏انْشَقَّ ‏ ‏الْقَمَرُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شِقَّتَيْنِ ‏ ‏حَتَّى نَظَرُوا إِلَيْهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اشْهَدُوا ‏","","",""],[3403,3403,"","আমরা বাবার দুই বছর কথা বলেছি বাবার বাবার সর্বজনের জন্য বাবার মন খারাপ করার জন্য, ঈশ্বর তাকে উদ্ধার করতে হবে এবং পাথরের খেলা এবং মৃত্যুর দিকে ঠেলে দিতে হবে। এর ফলে, আমি আমার জীবনকে পরিবর্তন করতে পেরেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي مَعْمَرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏دَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَحَوْلَ ‏ ‏الْكَعْبَةِ ‏ ‏سِتُّونَ وَثَلَاثُ مِائَةِ ‏ ‏نُصُبٍ ‏ ‏فَجَعَلَ يَطْعُنُهَا بِعُودٍ كَانَ بِيَدِهِ وَيَقُولُ ‏ { ‏جَاءَ الْحَقُّ وَمَا ‏ ‏يُبْدِئُ ‏ ‏الْبَاطِلُ وَمَا يُعِيدُ ‏} { ‏جَاءَ الْحَقُّ ‏ ‏وَزَهَقَ ‏ ‏الْبَاطِلُ إِنَّ الْبَاطِلَ كَانَ ‏ ‏زَهُوقًا ‏ }","","",""],[3404,3404,"","আমরা দুই বছর আগে তাকে না, যে হয়তো তার কথা শুনেছিল.","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏وَلَيْسَ مِنْهَا مَنْ يَقْدُمُهَا وَقُرِئَ عَلَى ‏ ‏سُفْيَانَ ‏ ‏سَمِعْتُ ‏ ‏يَحْيَى الْجَابِرَ ‏ ‏عَنْ ‏ ‏أَبِي مَاجِدٍ الْحَنَفِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ ‏ ‏يَقُولُ ‏ ‏سَأَلْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ السَّيْرِ بِالْجِنَازَةِ فَقَالَ ‏ ‏مَتْبُوعَةٌ وَلَيْسَتْ بِتَابِعَةٍ ‏","","",""],[3405,3405,"","ঈশ্বর তাকে প্রার্থনা করেছিলেন এবং তিনি বলেছিলেন যে, ঈশ্বর তাঁর কাজ ও কাজের মাধ্যমে আমাদেরকে হত্যা করেছেন । ভুলে গেছি, আমরা এটা চালিয়ে যাচ্ছি, আমরা হেরে গেছি।","‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِنًى ‏ ‏قَالَ ‏ ‏فَخَرَجَتْ عَلَيْنَا حَيَّةٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْتُلُوهَا ‏ ‏فَابْتَدَرْنَاهَا ‏ ‏فَسَبَقَتْنَا ‏","","",""],[3406,3406,"","আমরা ঈশ্বরের দোহাই দিয়ে বলছি এটা ভাল হতে পারে, আমি বলছি, আমাকে যেতে দাও না। আমরা আমাদের ঘৃণা দিনের মধ্যেই জন্ম নিয়েছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدِ اللَّهِ بْنِ إِدْرِيسَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْأَعْمَشَ ‏ ‏يَرْوِي عَنْ ‏ ‏شَقِيقٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يَخْرُجُ إِلَيْنَا فَيَقُولُ إِنَّنِي لَأُخْبَرُ بِمَكَانِكُمْ وَمَا يَمْنَعُنِي أَنْ أَخْرُجَ إِلَيْكُمْ إِلَّا كَرَاهِيَةُ أَنْ أُمِلَّكُمْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتَخَوَّلُنَا ‏ ‏بِالْمَوْعِظَةِ فِي الْأَيَّامِ كَرَاهِيَةَ ‏ ‏السَّآمَةِ ‏ ‏عَلَيْنَا ‏","","",""],[3407,3407,"","আমরা বাবা মার সাথে ঈশ্বরের প্রেমের জন্য লড়াই করার কথা বলেছিলাম। আমি মনে করি, আমি তার মন ভেঙ্গে ফেলব এবং আমি এগিয়ে যাব এবং তাকে খুঁজে বের করব। ঈশ্বর তাকে উদ্ধার করেছেন এবং তারপর তিনি তা প্রয়োগ করেছেন। আমি মনে করি, আমি আমার সিদ্ধান্তের মধ্যে আছি। আমি আমার সিদ্ধান্তের মধ্যে আছি, আমি আমার মনের মধ্যে যে বিষয়টি নিয়ে আলোচনা করব, তা হল, আমি আমার মনের মধ্যে প্রবেশের জন্য। আমি আমার মনের মধ্যে প্রবেশের জন্য লড়াই করব। এবং আমি আমার সিদ্ধান্তের সময় আমি আমার কাছে ফিরে আসব। এবং আমি আমার সিদ্ধান্ত নিয়েছি, আমি আমার সিদ্ধান্তের জন্য যা করছি, তা নিয়ে আমি কি করব? আমি কি করব? আমি কি করব? আমি জানি না, আমি জানি, আমি কি করব? আমি জানি না, আমি জানি না, আমি কি করব? তার ভাগ্য.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏وَعَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏إِذَا رَكَعَ أَحَدُكُمْ فَلْيُفْرِشْ ذِرَاعَيْهِ فَخِذَيْهِ ‏ ‏وَلْيَجْنَأْ ‏ ‏ثُمَّ طَبَّقَ بَيْنَ كَفَّيْهِ فَكَأَنِّي أَنْظُرُ إِلَى ‏ ‏اخْتِلَافِ ‏ ‏أَصَابِعِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ثُمَّ طَبَّقَ كَفَّيْهِ فَأَرَاهُمْ ‏","","",""],[3408,3408,"","আমরা বাবার সঙ্গে সেখান থেকে যাওয়ার চেষ্টা করেছিলাম । প্রভু, আমাদের সেরাটা হবে আমাদের, তুমি যা বলতে চাও তা শুনতে না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏الَّذِينَ آمَنُوا وَلَمْ ‏ ‏يَلْبِسُوا ‏ ‏إِيمَانَهُمْ بِظُلْمٍ ‏} ‏شَقَّ ‏ ‏ذَلِكَ عَلَى النَّاسِ وَقَالُوا يَا رَسُولَ اللَّهِ فَأَيُّنَا لَا يَظْلِمُ نَفْسَهُ قَالَ إِنَّهُ لَيْسَ الَّذِي تَعْنُونَ أَلَمْ تَسْمَعُوا مَا قَالَ الْعَبْدُ الصَّالِحُ ‏ { ‏يَا بُنَيَّ لَا تُشْرِكْ بِاللَّهِ إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ ‏} ‏إِنَّمَا هُوَ الشِّرْكُ ‏","","",""],[3409,3409,"","বাবা সঙ্গে সঙ্গে যেতে চেষ্টা করে আমরা বাবার কথা বলেছিলাম । পাথরের উপর লেখা আছে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏أَبَلَغَكَ أَنَّ اللَّهَ عَزَّ وَجَلَّ يَحْمِلُ الْخَلَائِقَ عَلَى أُصْبُعٍ وَالسَّمَوَاتِ عَلَى أُصْبُعٍ وَالْأَرَضِينَ عَلَى أُصْبُعٍ وَالشَّجَرَ عَلَى أُصْبُعٍ ‏ ‏وَالثَّرَى ‏ ‏عَلَى أُصْبُعٍ فَضَحِكَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى بَدَتْ ‏ ‏نَوَاجِذُهُ ‏ ‏فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ ‏} ‏الْآيَةَ ‏","","",""],[3410,3410,"","আমরা তাকে ঈশ্বরের কাজ করতে বলেছিলাম। তিনি বলেছিলেন যে ঈশ্বর তাকে তাই করতে বলেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّهُ قَرَأَ سُورَةَ ‏ ‏يُوسُفَ ‏ ‏بِحِمْصَ ‏ ‏فَقَالَ رَجُلٌ مَا هَكَذَا أُنْزِلَتْ فَدَنَا مِنْهُ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَوَجَدَ مِنْهُ رِيحَ الْخَمْرِ فَقَالَ أَتُكَذِّبُ بِالْحَقِّ وَتَشْرَبُ ‏ ‏الرِّجْسَ ‏ ‏لَا أَدَعُكَ حَتَّى أَجْلِدَكَ حَدًّا قَالَ فَضَرَبَهُ ‏ ‏الْحَدَّ ‏ ‏وَقَالَ ‏ ‏وَاللَّهِ لَهَكَذَا أَقْرَأَنِيهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[3411,3411,"","বাবা কীভাবে তার সঙ্গে বাস করতাম, সেই বিষয়ে কথা বলার চেষ্টা আমরা তার সঙ্গে কথা বলেছিলাম । ঈশ্বর অথবা আপনি যদি বলেছিলেন যে, আমরা হয়তো বলতে পারি যে, আপনাকে জীবিত থাকতে ব্যবহার করতে পারে, তাহলে সেই যুবকটি আপনাকে অবাক করে দিতে পারে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ أَمْشِي مَعَ ‏ ‏عَبْدِ اللَّهِ ‏ ‏بِمِنًى ‏ ‏فَلَقِيَهُ ‏ ‏عُثْمَانُ ‏ ‏فَقَامَ مَعَهُ يُحَدِّثُهُ فَقَالَ لَهُ ‏ ‏عُثْمَانُ ‏ ‏يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏أَلَا نُزَوِّجُكَ جَارِيَةً شَابَّةً لَعَلَّهَا أَنْ تُذَكِّرَكَ مَا مَضَى مِنْ زَمَانِكَ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَمَا لَئِنْ قُلْتَ ذَاكَ لَقَدْ قَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏مَعْشَرَ ‏ ‏الشَّبَابِ ‏ ‏مَنْ اسْتَطَاعَ مِنْكُمْ ‏ ‏الْبَاءَةَ ‏ ‏فَلْيَتَزَوَّجْ فَإِنَّهُ ‏ ‏أَغَضُّ ‏ ‏لِلْبَصَرِ ‏ ‏وَأَحْصَنُ ‏ ‏لِلْفَرْجِ وَمَنْ لَمْ يَسْتَطِعْ فَعَلَيْهِ بِالصَّوْمِ فَإِنَّهُ لَهُ ‏ ‏وِجَاءٌ ‏","","",""],[3412,3412,"","আমরা একটি ভালো ছেলের প্রতি করুণা দেখানোর কথা বলেছিলাম। আল্লাহ হয়ত ঈশ্বরের কাছে প্রার্থনা করেছেন। ঈশ্বরের কাছে প্রার্থনা করেছেন, ঈশ্বর আপনাকে তাঁর কাছে প্রার্থনা করেছেন এবং আত্মসমর্পণ করেছেন। আপনি ফিরে এসে শুনেছেন। দুই বার।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏قَالَ صَلَّى ‏ ‏عُثْمَانُ ‏ ‏بِمِنًى ‏ ‏أَرْبَعًا فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْعُودٍ ‏ ‏صَلَّيْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِنًى ‏ ‏رَكْعَتَيْنِ وَمَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏رَكْعَتَيْنِ وَمَعَ ‏ ‏عُمَرَ ‏ ‏رَكْعَتَيْنِ ‏","","",""],[3413,3413,"","আমরা বাবার সাথে কথা বলেছি, ঈশ্বর তাকে চিনেন আর সে আমার বন্ধুদের ছেড়ে দিবে যারা তাদের দোষ দিবে, তুমি তাদের সাক্ষী রাখবে, তারা সবাই ঈশ্বরের অনুগ্রহের কথা বলবে। ঠিক এবং তারা তাদের সাক্ষীদের ভয় পায় না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبِيدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ النَّاسِ قَرْنِي ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ يَأْتِي بَعْدَ ذَلِكَ قَوْمٌ تَسْبِقُ شَهَادَاتُهُمْ أَيْمَانَهُمْ وَأَيْمَانُهُمْ شَهَادَاتِهِمْ ‏","","",""],[3414,3414,"","আমরা বাবার সাথে কথা বলেছি যে ঈশ্বরের অনুগ্রহ নিয়ে কথা বলতে চেষ্টা করছে, ঈশ্বর বলে দিয়েছেন যে আমি শেষ সুযোগ যে মানুষ ছেড়ে চলে গেছে তার গুলি করা হয়েছে, সে সবাইকে বলবে আমি হয়ত এটা নিতে পারি তুমি যেই সময়ে বিজয়ী ছিলে, সে বলেছিল যে সে এটা নিশ্চিত করতে পারবে... ...এটা বিশ্বাস করার জন্য যে তুমিই হবে তুমি সেই লোক যাকে তুমি বলবে সে বলবে আমি তোমাকে নিয়ে গর্বিত আর আমি তোমার জন্য প্রার্থনা করতে পারি.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبِيدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّنِي لَأَعْرِفُ آخِرَ أَهْلِ النَّارِ خُرُوجًا مِنْ النَّارِ رَجُلٌ يَخْرُجُ مِنْهَا زَحْفًا فَيُقَالُ لَهُ ‏ ‏انْطَلِقْ فَادْخُلْ الْجَنَّةَ قَالَ فَيَذْهَبُ يَدْخُلُ فَيَجِدُ النَّاسَ قَدْ أَخَذُوا الْمَنَازِلَ ‏ ‏قَالَ فَيَرْجِعُ فَيَقُولُ يَا رَبِّ قَدْ أَخَذَ النَّاسُ الْمَنَازِلَ قَالَ فَيُقَالُ لَهُ أَتَذْكُرُ الزَّمَانَ الَّذِي كُنْتَ فِيهِ قَالَ فَيَقُولُ نَعَمْ فَيُقَالُ لَهُ ‏ ‏تَمَنَّهْ ‏ ‏فَيَتَمَنَّى فَيُقَالُ إِنَّ لَكَ الَّذِي تَمَنَّيْتَ وَعَشَرَةَ أَضْعَافِ الدُّنْيَا قَالَ فَيَقُولُ أَتَسْخَرُ بِي وَأَنْتَ الْمَلِكُ قَالَ فَلَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَحِكَ حَتَّى بَدَتْ ‏ ‏نَوَاجِذُهُ ‏","","",""],[3415,3415,"","আমি যখন ঘরে যাই, তখন আমি আমার মনের কথা খুলে বলি এবং সেখানে কাজ করি । ওয়ার্ড আর তারপর তুমি আমাকে শেষ একজনকে নিয়ে যেতে বলেছিলে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ إِذَا أَحْسَنْتُ فِي الْإِسْلَامِ أُؤَاخَذُ بِمَا عَمِلْتُ فِي الْجَاهِلِيَّةِ فَقَالَ ‏ ‏إِذَا أَحْسَنْتَ فِي الْإِسْلَامِ لَمْ تُؤَاخَذْ بِمَا عَمِلْتَ فِي الْجَاهِلِيَّةِ وَإِذَا أَسَأْتَ فِي الْإِسْلَامِ ‏ ‏أُخِذْتَ ‏ ‏بِالْأَوَّلِ وَالْآخِرِ ‏","","",""],[3416,3416,"","আমরা বাবার সাথে ঈশ্বরের দয়া নিয়ে যুদ্ধ করেছি। শান্তি যে জয় করেছে এবং তা করতে ব্যর্থ হয়েছে, সে ছিল ঈশ্বর এবং একজন ঈশ্বরের লোক, যিনি হঠাৎ করে আমার দাস ছিলেন। ঈশ্বর এই পুরস্কার লাভ করেছেন এবং যারা তা পাবে তাদের কাছ থেকে নিশ্চয়ই তা পেয়ে নিশ্চয়ই তা কেনা উচিত । ঈশ্বর আশীর্বাদ করেছেন... ...এবং তারপর ঈশ্বরের দ্বারা.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَلَفَ عَلَى يَمِينٍ هُوَ فِيهَا فَاجِرٌ لِيَقْتَطِعَ بِهَا مَالَ امْرِئٍ مُسْلِمٍ لَقِيَ اللَّهَ عَزَّ وَجَلَّ وَهُوَ عَلَيْهِ غَضْبَانُ فَقَالَ ‏ ‏الْأَشْعَثُ ‏ ‏فِيَّ وَاللَّهِ كَانَ ذَلِكَ كَانَ بَيْنِي وَبَيْنَ رَجُلٍ مِنْ ‏ ‏الْيَهُودِ ‏ ‏أَرْضٌ ‏ ‏فَجَحَدَنِي ‏ ‏فَقَدَّمْتُهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَكَ بَيِّنَةٌ قُلْتُ لَا فَقَالَ لِلْيَهُودِيِّ احْلِفْ فَقُلْتُ يَا رَسُولَ اللَّهِ إِذَنْ يَحْلِفَ فَيَذْهَبَ مَالِي فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ وَأَيْمَانِهِمْ ثَمَنًا قَلِيلًا ‏} ‏إِلَى آخِرِ الْآيَةِ ‏","","",""],[3417,3417,"","আমরা একজন বয়স্ক ছেলের কথা বলেছিলাম যে আমার সাথে একজন অতিথির ছেলের কথা বলছিল যে ফিরে যেতে যাচ্ছিল আর গান গাইতে শুরু করলো। বাবা খুব রাগী কথা, সে একটা কাঠবিড়ালী দিয়ে একটা কাঠবিড়ালী কেটে ফেলেনি। তারপর সে বলেছিল, সে গল্প কেটে ফেলতে, আর সে বলেছে, ঈশ্বর তোমার মঙ্গল করুক। আমাদের সময়ের মাস্টার, আমরা কথা বলেছি, কিন্তু আমরা এমন একটা ছেলেকে রক্ষা করার চেষ্টা করেছি যে হবে সেই হবে সেই ব্যক্তি, যে হবে সে হবেই সে-ই হবে যে , যে ব ্ যক ্ তি হবে , যে ব ্ যক ্ তি তার জন ্ যে উত ্ তম হবে । রাজা হতে আমি গর্বিত, যে অনেক ড্রিংক করতে আদেশ করেছে আর তারপর আমি চলে এসেছি। কোরআন বলেছিল তুমি একটা চলচ্চিত্র থেকে শিখলে আমি এটা শিখতে পারব যে আমি রাজা এটা গোপন ভাবে দুই সপ্তাহ ধরে চলছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنِي ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏أَرْعَى غَنَمًا ‏ ‏لِعُقْبَةَ بْنِ أَبِي مُعَيْطٍ ‏ ‏فَمَرَّ بِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏فَقَالَ يَا غُلَامُ هَلْ مِنْ لَبَنٍ قَالَ قُلْتُ نَعَمْ وَلَكِنِّي مُؤْتَمَنٌ قَالَ فَهَلْ مِنْ شَاةٍ لَمْ ‏ ‏يَنْزُ ‏ ‏عَلَيْهَا ‏ ‏الْفَحْلُ ‏ ‏فَأَتَيْتُهُ بِشَاةٍ فَمَسَحَ ضَرْعَهَا فَنَزَلَ لَبَنٌ فَحَلَبَهُ فِي إِنَاءٍ فَشَرِبَ وَسَقَى ‏ ‏أَبَا بَكْرٍ ‏ ‏ثُمَّ قَالَ لِلضَّرْعِ ‏ ‏اقْلِصْ ‏ ‏فَقَلَصَ ‏ ‏قَالَ ثُمَّ أَتَيْتُهُ بَعْدَ هَذَا فَقُلْتُ يَا رَسُولَ اللَّهِ عَلِّمْنِي مِنْ هَذَا الْقَوْلِ قَالَ فَمَسَحَ رَأْسِي وَقَالَ يَرْحَمُكَ اللَّهُ فَإِنَّكَ ‏ ‏غُلَيِّمٌ مُعَلَّمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏بِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏فَأَتَاهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏بِصَخْرَةٍ مَنْقُورَةٍ فَاحْتَلَبَ فِيهَا فَشَرِبَ وَشَرِبَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَشَرِبْتُ قَالَ ثُمَّ أَتَيْتُهُ بَعْدَ ذَلِكَ قُلْتُ عَلِّمْنِي مِنْ هَذَا الْقُرْآنِ قَالَ إِنَّكَ غُلَامٌ مُعَلَّمٌ قَالَ فَأَخَذْتُ مِنْ ‏ ‏فِيهِ سَبْعِينَ سُورَةً ‏","","",""],[3418,3418,"","তিনি বলেছিলেন যে, একজন ভাল মিথ্যাবাদী হয়ে তাদেরকে ছেড়ে দেওয়ার জন্য তিনি একজন উত্তম মিথ্যাবাদী । সে ভালো মানুষ হয়েছে, আর তাকে আরও খারাপের দিকে যেতে দেখা যাচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ نَظَرَ فِي قُلُوبِ الْعِبَادِ فَوَجَدَ قَلْبَ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرَ قُلُوبِ الْعِبَادِ فَاصْطَفَاهُ لِنَفْسِهِ فَابْتَعَثَهُ بِرِسَالَتِهِ ثُمَّ نَظَرَ فِي قُلُوبِ الْعِبَادِ بَعْدَ قَلْبِ ‏ ‏مُحَمَّدٍ ‏ ‏فَوَجَدَ قُلُوبَ أَصْحَابِهِ خَيْرَ قُلُوبِ الْعِبَادِ فَجَعَلَهُمْ وُزَرَاءَ نَبِيِّهِ يُقَاتِلُونَ عَلَى دِينِهِ فَمَا رَأَى الْمُسْلِمُونَ حَسَنًا فَهُوَ عِنْدَ اللَّهِ حَسَنٌ وَمَا رَأَوْا سَيِّئًا فَهُوَ عِنْدَ اللَّهِ سَيِّئٌ ‏","","",""],[3419,3419,"","আমরা বাবা সম্পর্কে কথা বলেছিলাম ঈশ্বর কখন এসেছেন তা নিয়ে। যদি আপনি পরেরবার যদি আপনি আবার জানতে চান, তাহলে আপনি কি করবেন? তাদের সাথে সাঁতার কাটতে পেরে তারা ধ্বংস করে ফেলবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَلَّكُمْ سَتُدْرِكُونَ أَقْوَامًا يُصَلُّونَ صَلَاةً لِغَيْرِ وَقْتِهَا فَإِذَا أَدْرَكْتُمُوهُمْ فَصَلُّوا فِي بُيُوتِكُمْ فِي الْوَقْتِ الَّذِي تَعْرِفُونَ ثُمَّ صَلُّوا مَعَهُمْ وَاجْعَلُوهَا ‏ ‏سُبْحَةً ‏","","",""],[3420,3420,"","আমরা ঈশ্বরের দর্শন নিয়ে কথা বলেছিলাম, সে প্রার্থনা করবে যদি আমি জানি না তার প্রভুর সাথে কিছু করার আছে। আর তারপর সে বলল, ঈশ্বর যেন এটা পার পেয়ে যান, তার লোক আমার প্রভুকে খুঁজে পাবে, যেমনটা সে বলেছিল, সে বলেছিল, সে কতটা খারাপ, তা আমি ভুলে যাব। যদি প্রার্থনা করা হয়, তাহলে তুমি দুইজনকে খুঁজে পাবে না।","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةً فَلَا أَدْرِي زَادَ أَمْ نَقَصَ فَلَمَّا سَلَّمَ قِيلَ لَهُ يَا رَسُولَ اللَّهِ هَلْ حَدَثَ فِي الصَّلَاةِ شَيْءٌ قَالَ لَا وَمَا ذَاكَ قَالُوا صَلَّيْتَ كَذَا وَكَذَا قَالَ فَثَنَى رِجْلَيْهِ فَسَجَدَ سَجْدَتَيْ السَّهْوِ فَلَمَّا سَلَّمَ قَالَ ‏ ‏إِنَّمَا أَنَا بَشَرٌ أَنْسَى كَمَا تَنْسَوْنَ وَإِذَا شَكَّ أَحَدُكُمْ فِي الصَّلَاةِ ‏ ‏فَلْيَتَحَرَّ ‏ ‏الصَّلَاةَ فَإِذَا سَلَّمَ فَلْيَسْجُدْ سَجْدَتَيْنِ ‏","","",""],[3421,3421,"","আমরা একটা মানুষের জন্য একটা মূল্য নিয়ে কথা বলেছিলাম যে খোদা বলতে পারতেন তাকে আত্মসমর্পণ করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏خَيْثَمَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ قَوْمِهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏سَمَرَ ‏ ‏بَعْدَ الصَّلَاةِ ‏ ‏يَعْنِي الْعِشَاءَ الْآخِرَةَ ‏ ‏إِلَّا لِأَحَدِ رَجُلَيْنِ مُصَلٍّ أَوْ مُسَافِرٍ ‏","","",""],[3422,3422,"","আমরা আমার বাবার স্বপ্নের কথা বলেছি যখন ঈশ্বর মানুষকে বললেন, খোদা ইচ্ছুক, অজানারা বললো তুমি শপথ নেয়ার থেকে বেশি ভাল।","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ نَاسٌ يَا رَسُولَ اللَّهِ أَنُؤَاخَذُ بِأَعْمَالِنَا فِي الْجَاهِلِيَّةِ فَقَالَ ‏ ‏مَنْ أَحْسَنَ مِنْكُمْ فِي الْإِسْلَامِ فَلَا يُؤَاخَذُ بِهِ وَمَنْ أَسَاءَ فَيُؤْخَذُ بِعَمَلِهِ الْأَوَّلِ وَالْآخِرِ ‏","","",""],[3423,3423,"","আমরা দুই স্তম্ভ নিয়ে তার ভালবাসার পর বেনের প্রতি করুণা প্রদর্শনের চেয়ে ভালো কিছুর কথা বলেছি। আমি বলতে চাচ্ছি যে, এই সমস্যাকে টেনে আনার সন্দেহকে পরিবর্তন করছে । বিয়ের জন্য ধন্যবাদ।","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏الرُّكَيْنِ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ حَسَّانَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ حَرْمَلَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَكْرَهُ عَشْرَ ‏ ‏خِلَالٍ ‏ ‏تَخَتُّمَ الذَّهَبِ وَجَرَّ ‏ ‏الْإِزَارِ ‏ ‏وَالصُّفْرَةَ ‏ ‏يَعْنِي ‏ ‏الْخَلُوقَ ‏ ‏وَتَغْيِيرَ الشَّيْبِ ‏ ‏قَالَ ‏ ‏جَرِيرٌ ‏ ‏إِنَّمَا ‏ ‏يَعْنِي بِذَلِكَ نَتْفَهُ ‏ ‏وَعَزْلَ ‏ ‏الْمَاءِ ‏ ‏عَنْ ‏ ‏مَحِلِّهِ ‏ ‏وَالرُّقَى إِلَّا ‏ ‏بِالْمُعَوِّذَاتِ ‏ ‏وَفَسَادَ الصَّبِيِّ غَيْرَ مُحَرِّمِهِ وَعَقْدَ ‏ ‏التَّمَائِمِ ‏ ‏وَالتَّبَرُّجَ بِالزِّينَةِ لِغَيْرِ مَحِلِّهَا وَالضَّرْبَ بِالْكِعَابِ ‏","","",""],[3424,3424,"","আমরা দুটো জাহাজের কথা বলেছি যারা আমাকে বলতে চেয়েছিল যে কিছু লোক একবার বলেছিল আমার বাবা আমার বাবার দুর্দশা নিয়ে কথা বলেছেন যে তিনি বলেছেন যে তিনি ঈশ্বর যে কথা বলেছেন তার জন্য। আমি আমার মন পড়তে পারবো... ...আমি তোমাকে পড়তে পারবো... ...আর আমি এটা করব.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏وَبَعْضُ الْحَدِيثِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْرَأْ عَلَيَّ قَالَ قُلْتُ أَقْرَأُ عَلَيْكَ وَعَلَيْكَ أُنْزِلَ قَالَ ‏ ‏إِنَّنِي أُحِبُّ أَنْ أَسْمَعَهُ مِنْ غَيْرِي فَقَرَأْتُ حَتَّى إِذَا بَلَغْتُ ‏ { ‏فَكَيْفَ إِذَا جِئْنَا مِنْ كُلِّ أُمَّةٍ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَى هَؤُلَاءِ شَهِيدًا ‏} ‏قَالَ رَأَيْتُ عَيْنَيْهِ ‏ ‏تَذْرِفَانِ ‏ ‏دُمُوعًا ‏","","",""],[3425,3425,"","বাবা যে কাজটা করেছে তার ব্যাপারে আমরা বাবার কথা বলেছিলাম। সে বলে যে তোমার শেষ দুই বছর, বাবা, ক্ষমার পর তুমি এটা পড়, কি ভাবে তুমি এটা পড় বা খুঁজে পাও। সব গরু শপথ করে বলেছে যে ঈশ্বরের কসম, আমি এটা অনুভব করি যে আমি ভালো প্রার্থনা করি এবং মানুষ ভাল আছে মানুষ এবং মানুষ যারা আছে তারা দেখতে পাবে তারাই তারাই তারা যারা এই দলগুলি যারা এই ব্যক্তি তারা যারা যারা যারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা, কিন্তু তিনি হৃদয়ের মধ্যে এটা পড়েছেন তিনি জানেন তিনি আদর্শ। তারা তাদের আদর্শ সম্পর্কে জানেন। তারা তাদের আদর্শতা সম্পর্কে জানতে পারে। তারা তাদের কাছে এটি একটি আদর্শ। তারা হল, তারা হল, তারা হল, তারা হল তারা যারা আদর্শ, তারা হল সেই ব্যক্তি, যারা তারা যারা তারা তারা যারা তারা তারা যারা তারা যারা তারা যারা আছে। তারা তারা তারা তারা তারা তারা তারা তারা তারা যারা তারা যারা তারা যারা তারা যারা আছে। তারা তারা তারা তারা তারা তারা তারা তারা যারা তারা তারা তারা তারা তারা তারা তারা তারা যারা আছে। তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা যারা। তারা তারা তারা তারা তারা তারা তারা যারা তারা তারা তারা যারা তারা যারা তারা তারা তারা যারা। তারা তারা তারা তারা তারা তারা তারা যারা তারা যারা ভাবে তারা তারা তারা যারা তারা তারা তারা তারা তারা তারা তারা তারা তারা তারা যারা তারা যারা তারা যারা তারা তারা তারা তারা তারা যারা তারা তারা তারা তারা তারা যারা তারা তারা তারা তারা তারা তারা তারা যারা তারা তারা তারা তারা তারা। তারা তারা তারা তারা তারা যারা। তারা তারা তারা তারা তারা যারা তারা তারা তারা তারা তিনি হলে দুটো গোপন বিষয় পড়েন, তারপর তিনি দেখতে পান যে, তিনি তার মাথা রেখে গেছেন কি না । লর্ড দিবসে অসহায়।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقِ بْنِ سَلَمَةَ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى ‏ ‏عَبْدِ اللَّهِ ‏ ‏مِنْ ‏ ‏بَنِي بَجِيلَةَ ‏ ‏يُقَالُ لَهُ ‏ ‏نَهِيكُ بْنُ سِنَانٍ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏كَيْفَ تَقْرَأُ هَذِهِ الْآيَةَ أَيَاءً تَجِدُهَا أَوْ أَلِفًا ‏ { ‏مِنْ مَاءٍ غَيْرِ ‏ ‏آسِنٍ ‏ } ‏أَوْ ‏ { ‏غَيْرِ ‏ ‏يَاسِنٍ ‏ } ‏فَقَالَ لَهُ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَوَكُلَّ الْقُرْآنِ أَحْصَيْتَ غَيْرَ هَذِهِ الْآيَةِ قَالَ إِنَّنِي لَأَقْرَأُ ‏ ‏الْمُفَصَّلَ ‏ ‏فِي رَكْعَةٍ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏هَذًّا كَهَذِّ الشِّعْرِ إِنَّ مِنْ أَحْسَنِ الصَّلَاةِ الرُّكُوعَ وَالسُّجُودَ وَلَيَقْرَأَنَّ الْقُرْآنَ أَقْوَامٌ لَا يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ وَلَكِنَّهُ إِذَا قَرَأَهُ ‏ ‏فَرَسَخَ ‏ ‏فِي الْقَلْبِ نَفَعَ إِنِّي لَأَعْرِفُ النَّظَائِرَ الَّتِي كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ سُورَتَيْنِ فِي رَكْعَةٍ قَالَ ثُمَّ قَامَ فَدَخَلَ فَجَاءَ ‏ ‏عَلْقَمَةُ ‏ ‏فَدَخَلَ عَلَيْهِ قَالَ فَقُلْنَا لَهُ سَلْهُ لَنَا عَنْ النَّظَائِرِ الَّتِي كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ سُورَتَيْنِ فِي رَكْعَةٍ قَالَ فَدَخَلَ فَسَأَلَهُ ثُمَّ خَرَجَ إِلَيْنَا فَقَالَ ‏ ‏عِشْرُونَ سُورَةً مِنْ أَوَّلِ ‏ ‏الْمُفَصَّلِ ‏ ‏فِي تَأْلِيفِ ‏ ‏عَبْدِ اللَّهِ ‏","","",""],[3426,3426,"","আমরা বাবার দোহাই লাগে বাবার সাথে ঝগড়ার কথা বলেছিলাম, সে একটা শপথ করে বলেছিল যে সে যা চেয়েছিল আর ঈশ্বর তাই করেছে, আমি আল্লাহ তার কাছে প্রার্থনা করে সে যা ছেড়ে দেবে। তুমি আমাকে বলেছিলে সে তার কাছে পৌঁছাতে পারবে। সে বলেছিল, \"ঈশ্বরের করুণা আছে, আমি এর চেয়ে বেশি আঘাত পাব।\"","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَسَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ قَسْمًا قَالَ فَقَالَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏إِنَّ هَذِهِ لَقِسْمَةٌ مَا أُرِيدَ بِهَا وَجْهُ اللَّهِ عَزَّ وَجَلَّ قَالَ فَقُلْتُ يَا عَدُوَّ اللَّهِ أَمَا لَأُخْبِرَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَا قُلْتَ قَالَ فَذَكَرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاحْمَرَّ وَجْهُهُ قَالَ ثُمَّ قَالَ ‏ ‏رَحْمَةُ اللَّهِ عَلَى ‏ ‏مُوسَى ‏ ‏لَقَدْ أُوذِيَ بِأَكْثَرَ مِنْ هَذَا فَصَبَرَ ‏","","",""],[3427,3427,"","আমরা বাবার দোহাই লাগে, তুমি একটা মেয়েকে দেখতে শুরু করবে না যতক্ষণ না সে তার স্বামীর সাথে দেখা করে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُبَاشِرْ الْمَرْأَةُ الْمَرْأَةَ حَتَّى تَصِفَهَا لِزَوْجِهَا كَأَنَّمَا يَنْظُرُ إِلَيْهَا ‏","","",""],[3428,3428,"","আমরা ঈশ্বরের সঙ্গে বাবার যুদ্ধ সম্বন্ধে কথা বলেছিলাম, তিনি বলেছিলেন যে আমরা ঈশ্বরের সঙ্গে গমনাগমন করছি । মই, ছাড়, তুমি ওকে মারতে পারবে না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا نَمْشِي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَرَّ ‏ ‏بِابْنِ صَيَّادٍ ‏ ‏فَقَالَ إِنِّي قَدْ ‏ ‏خَبَأْتُ ‏ ‏لَكَ ‏ ‏خَبْئًا ‏ ‏قَالَ ‏ ‏ابْنُ صَيَّادٍ ‏ ‏دُخٌّ ‏ ‏قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اخْسَأْ ‏ ‏فَلَنْ تَعْدُوَ ‏ ‏قَدْرَكَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ دَعْنِي أَضْرِبْ عُنُقَهُ قَالَ ‏ ‏لَا إِنْ يَكُنْ الَّذِي نَخَافُ فَلَنْ تَسْتَطِيعَ قَتْلَهُ ‏","","",""],[3429,3429,"","আমরা বাবার সাথে কথা বলেছিলাম তার ব্যাপারে জানার চেষ্টা করে সে তার ক্ষমতা মেরে ফেলবে আর বলেছে সে তার রক্ত ক্ষমা করতে পারবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَكَأَنِّي أَنْظُرُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَحْكِي ‏ ‏نَبِيًّا ضَرَبَهُ قَوْمُهُ فَهُوَ يَمْسَحُ عَنْ وَجْهِهِ الدَّمَ وَيَقُولُ رَبِّ اغْفِرْ لِقَوْمِي فَإِنَّهُمْ لَا يَعْلَمُونَ ‏","","",""],[3430,3430,"","আমরা বাবার সাথে ঝগড়ার কথা বলেছিলাম, ঈশ্বরকে বলার জন্য। আমি এটা করতে যাচ্ছি এবং তোমার প্রতিবেশীকে বিয়ে করতে যাচ্ছি। সে বলল, ঈশ্বর চলে যাওয়ার পর আল্লাহ আমাকে বিয়ে করবে। ( যোহন ১৭: ৩) কিন্তু, ঈশ্বরের বাক্য বলে যে, তারা “সত্যে থাকে, ” অর্থাৎ যারা ঈশ্বরকে নিষিদ্ধ করে, তাদের হত্যা করে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الذَّنْبِ أَكْبَرُ قَالَ ‏ ‏أَنْ تَجْعَلَ لِلَّهِ ‏ ‏نِدًّا ‏ ‏وَهُوَ خَلَقَكَ قَالَ ثُمَّ أَيٌّ قَالَ أَنْ تَقْتُلَ وَلَدَكَ أَنْ ‏ ‏يَطْعَمَ ‏ ‏مَعَكَ قَالَ ثُمَّ أَيٌّ قَالَ أَنْ تُزَانِيَ ‏ ‏حَلِيلَةَ ‏ ‏جَارِكَ قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَأَنْزَلَ اللَّهُ تَصْدِيقَ ذَلِكَ ‏ { ‏وَالَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ ‏ ‏أَثَامًا ‏ }","","",""],[3431,3431,"","একজন মানুষের গৌরবে গরুটি এই বিশ্বাসঘাতক বিষয়ে কথা বলে গর্বিত । তিনি জানেন যে, ঈশ্বর আমি জানি যে, মানুষ কখনো আমাকে না জানিয়েই জানে যে, কেন তিনি কী করছেন । ভাববাদী তার কাছে প্রার্থনা করেছিলেন এবং ঈশ্বরের কাছে প্রতিজ্ঞা করেছেন যে, আমি তা করতে রাজি হব । তুমি আশা করছ যে মানুষ নরকে যাবে, ঈশ্বর হতে যাচ্ছে না, আমি দ্বিতীয়বার ধরাছি। তারা অবতরণে ফিরে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى ‏ ‏عَبْدِ اللَّهِ ‏ ‏فَقَالَ إِنِّي تَرَكْتُ فِي الْمَسْجِدِ رَجُلًا يُفَسِّرُ الْقُرْآنَ بِرَأْيِهِ يَقُولُ فِي هَذِهِ الْآيَةِ ‏ { ‏يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ ‏} ‏إِلَى آخِرِهَا ‏ ‏يَغْشَاهُمْ يَوْمَ الْقِيَامَةِ دُخَانٌ يَأْخُذُ بِأَنْفَاسِهِمْ حَتَّى يُصِيبَهُمْ مِنْهُ كَهَيْئَةِ الزُّكَامِ قَالَ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏مَنْ عَلِمَ عِلْمًا فَلْيَقُلْ بِهِ وَمَنْ لَمْ يَعْلَمْ فَلْيَقُلْ اللَّهُ أَعْلَمُ فَإِنَّ مِنْ فِقْهِ الرَّجُلِ أَنْ يَقُولَ لِمَا لَا يَعْلَمُ اللَّهُ أَعْلَمُ إِنَّمَا كَانَ هَذَا لِأَنَّ ‏ ‏قُرَيْشًا ‏ ‏لَمَّا اسْتَعْصَتْ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعَا عَلَيْهِمْ بِسِنِينَ ‏ ‏كَسِنِي ‏ ‏يُوسُفَ ‏ ‏فَأَصَابَهُمْ ‏ ‏قَحْطٌ ‏ ‏وَجَهِدُوا حَتَّى أَكَلُوا الْعِظَامَ وَجَعَلَ الرَّجُلُ يَنْظُرُ إِلَى السَّمَاءِ فَيَنْظُرُ مَا بَيْنَهُ وَبَيْنَ السَّمَاءِ كَهَيْئَةِ الدُّخَانِ مِنْ ‏ ‏الْجَهْدِ ‏ ‏فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ ‏ ‏يَغْشَى ‏ ‏النَّاسَ هَذَا عَذَابٌ أَلِيمٌ ‏} ‏فَأَتَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقِيلَ يَا رَسُولَ اللَّهِ اسْتَسْقِ اللَّهَ ‏ ‏لِمُضَرَ ‏ ‏فَإِنَّهُمْ قَدْ هَلَكُوا قَالَ فَدَعَا لَهُمْ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏إِنَّا كَاشِفُو الْعَذَابِ ‏} ‏فَلَمَّا أَصَابَهُمْ الْمَرَّةَ الثَّانِيَةَ عَادُوا فَنَزَلَتْ ‏ { ‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى إِنَّا مُنْتَقِمُونَ ‏} ‏يَوْمَ ‏ ‏بَدْرٍ ‏","","",""],[3432,3432,"","আমরা বাবা-মা'র কথা বলেছিলাম, ৩ মাস পর খেলার রহস্যটা... ...তা হলো বর্বর আর দুই তলোয়ারী... তাদের হৃদয় আমাকে এগিয়ে যেতে বলেছে এবং বলতে বলেছে যে আমি যা শুনেছি তা নয়। আমরা প্রার্থনা করি, আর যদি না উঠি, তাহলে সে আমাদের কথা শুনবে না। আল্লাহ তোমাকে ছেড়ে দিবেন না। তুমি কি মনে করো তুমি নিজেকে সেই ভাবে হারিয়ে যেতে চাও?","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنْتُ مُسْتَتِرًا بِسِتَارِ ‏ ‏الْكَعْبَةِ ‏ ‏فَجَاءَ ثَلَاثَةُ نَفَرٍ ‏ ‏قُرَشِيٌّ ‏ ‏وَخَتَنَاهُ ‏ ‏ثَقَفِيَّانِ ‏ ‏أَوْ ‏ ‏ثَقَفِيٌّ ‏ ‏وَخَتَنَاهُ ‏ ‏قُرَشِيَّانِ ‏ ‏كَثِيرٌ شَحْمُ بُطُونِهِمْ قَلِيلٌ فِقْهُ قُلُوبِهِمْ فَتَكَلَّمُوا بِكَلَامٍ لَمْ أَسْمَعْهُ فَقَالَ أَحَدُهُمْ أَتَرَوْنَ اللَّهَ يَسْمَعُ كَلَامَنَا هَذَا فَقَالَ الْآخَرُ ‏ ‏أُرَانَا إِذَا رَفَعْنَا أَصْوَاتَنَا سَمِعَهُ وَإِذَا لَمْ نَرْفَعْهَا لَمْ يَسْمَعْ فَقَالَ الْآخَرُ إِنْ سَمِعَ مِنْهُ شَيْئًا سَمِعَهُ كُلَّهُ قَالَ فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏وَمَا كُنْتُمْ تَسْتَتِرُونَ أَنْ يَشْهَدَ عَلَيْكُمْ سَمْعُكُمْ وَلَا أَبْصَارُكُمْ وَلَا جُلُودُكُمْ ‏ ‏إِلَى قَوْلِهِ ‏ ‏ذَلِكُمْ ظَنُّكُمْ الَّذِي ظَنَنْتُمْ بِرَبِّكُمْ أَرْدَاكُمْ فَأَصْبَحْتُمْ مِنْ الْخَاسِرِينَ ‏}","","",""],[3433,3433,"","আমরা বাবার সঙ্গে একবার বিয়ে করার চেষ্টা করেছিলাম । আমি শুনেছি যে, ঈশ্বর আমার কথা শোনেন । তোমার সঙ্গী বলেছিল কেন আমাকে বলবে যে তুমি আমাকে এটা বলবে... ...আর আমি হয়ত এটা খুলেছি... তিনি যদি তা করতেন, তাহলে তিনি তাকে তার হাতে সমর্পণ করতেন । সেরে উঠতে চাই, অন্ধকার হতে যাচ্ছে না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الْجَزَّارِ ‏ ‏عَنْ ‏ ‏ابْنِ أَخِي زَيْنَبَ ‏ ‏عَنْ ‏ ‏زَيْنَبَ امْرَأَةِ عَبْدِ اللَّهِ ‏ ‏قَالَتْ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏إِذَا جَاءَ مِنْ حَاجَةٍ فَانْتَهَى إِلَى الْبَابِ تَنَحْنَحَ وَبَزَقَ كَرَاهِيَةَ أَنْ يَهْجُمَ مِنَّا عَلَى شَيْءٍ يَكْرَهُهُ قَالَتْ وَإِنَّهُ جَاءَ ذَاتَ يَوْمٍ فَتَنَحْنَحَ قَالَتْ وَعِنْدِي عَجُوزٌ ‏ ‏تَرْقِينِي ‏ ‏مِنْ ‏ ‏الْحُمْرَةِ ‏ ‏فَأَدْخَلْتُهَا تَحْتَ السَّرِيرِ فَدَخَلَ فَجَلَسَ إِلَى جَنْبِي فَرَأَى فِي عُنُقِي خَيْطًا قَالَ مَا هَذَا الْخَيْطُ قَالَتْ قُلْتُ خَيْطٌ ‏ ‏أُرْقِيَ ‏ ‏لِي فِيهِ قَالَتْ فَأَخَذَهُ فَقَطَعَهُ ثُمَّ قَالَ إِنَّ آلَ ‏ ‏عَبْدِ اللَّهِ ‏ ‏لَأَغْنِيَاءُ عَنْ الشِّرْكِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏الرُّقَى ‏ ‏وَالتَّمَائِمَ ‏ ‏وَالتِّوَلَةَ ‏ ‏شِرْكٌ قَالَتْ فَقُلْتُ لَهُ لِمَ تَقُولُ هَذَا وَقَدْ كَانَتْ عَيْنِي ‏ ‏تَقْذِفُ ‏ ‏فَكُنْتُ ‏ ‏أَخْتَلِفُ ‏ ‏إِلَى فُلَانٍ الْيَهُودِيِّ ‏ ‏يَرْقِيهَا ‏ ‏وَكَانَ إِذَا ‏ ‏رَقَاهَا ‏ ‏سَكَنَتْ قَالَ إِنَّمَا ذَلِكَ عَمَلُ الشَّيْطَانِ كَانَ ‏ ‏يَنْخُسُهَا ‏ ‏بِيَدِهِ فَإِذَا ‏ ‏رَقَيْتِهَا ‏ ‏كَفَّ عَنْهَا إِنَّمَا كَانَ يَكْفِيكِ أَنْ تَقُولِي كَمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَذْهِبْ ‏ ‏الْبَاسَ ‏ ‏رَبَّ النَّاسِ اشْفِ أَنْتَ الشَّافِي لَا شِفَاءَ إِلَّا شِفَاؤُكَ شِفَاءً لَا يُغَادِرُ ‏ ‏سَقَمًا ‏","","",""],[3434,3434,"","আমরা বাবার সাথে ঈশ্বরের দয়া নিয়ে ঝগড়ার কথা বলেছিলাম, আমি ঈশ্বরের প্রতি ঈর্ষা করি না, আর তোমার ভালবাসার জন্য, আমি তোমার সামনে না, হ্যাঁ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا أَحَدَ أَغْيَرُ مِنْ اللَّهِ عَزَّ وَجَلَّ فَلِذَلِكَ حَرَّمَ ‏ ‏الْفَوَاحِشَ ‏ ‏مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَلَا أَحَدَ أَحَبُّ إِلَيْهِ الْمَدْحُ مِنْ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[3435,3435,"","বাবা আমাদের সাথে দেখা করার চেষ্টা করার সময় বাবার সাথে কথা বলেছিলাম, আমার বাবার সাথে লড়াই করার চেষ্টা করার কথা, আমি ঈশ্বরের নামে শপথ নিয়ে বলছি, সে এটা ভবিষ্যদ্বাণী করে করেছে এবং সে একটা জিনিস বানিয়েছে। কৌশল।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَأَنْ أَحْلِفَ بِاللَّهِ تِسْعًا إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُتِلَ قَتْلًا أَحَبُّ إِلَيَّ مِنْ أَنْ أَحْلِفَ وَاحِدَةً وَذَلِك بِأَنَّ اللَّهَ عَزَّ وَجَلَّ اتَّخَذَهُ نَبِيًّا وَجَعَلَهُ شَهِيدًا ‏","","",""],[3436,3436,"","আমি ভাববাদীকে ঈশ্বরের কাছে প্রার্থনা করতে দিয়েছি, তিনি আপনার আত্মা হারাবার প্রতিজ্ঞা করবেন । শ্বাস নিতে যদি সে অসুস্থ হয়, সে কখনো তার পরিকল্পনা করার কথা চিন্তা করতে পারবে না কারণ সে চুরি করেছে এবং চুরি করেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏الْحَارِثِ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُوعَكُ ‏ ‏فَمَسِسْتُهُ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّكَ ‏ ‏لَتُوعَكُ ‏ ‏وَعْكًا ‏ ‏شَدِيدًا قَالَ أَجَلْ إِنِّي ‏ ‏أُوعَكُ ‏ ‏كَمَا ‏ ‏يُوعَكُ ‏ ‏رَجُلَانِ مِنْكُمْ قُلْتُ إِنَّ لَكَ أَجْرَيْنِ قَالَ نَعَمْ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏مَا عَلَى الْأَرْضِ مُسْلِمٌ يُصِيبُهُ ‏ ‏أَذًى ‏ ‏مِنْ مَرَضٍ فَمَا سِوَاهُ إِلَّا حَطَّ اللَّهُ عَنْهُ بِهِ خَطَايَاهُ كَمَا تَحُطُّ الشَّجَرُ وَرَقَهَا ‏ ‏حَدَّثَنَاه ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏مِثْلَهُ ‏","","",""],[3437,3437,"","আমরা বাবার সাথে ঝগড়ার কথা বলেছিলাম যে এই আবেগটা ঈশ্বরের নিকট থেকে পাওয়া মানুষের বিজয় হয়েছে। এটা আমার ভুল ছিল.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏تَعَاهَدُوا ‏ ‏هَذِهِ ‏ ‏الْمَصَاحِفَ ‏ ‏وَرُبَّمَا قَالَ الْقُرْآنَ ‏ ‏فَلَهُوَ أَشَدُّ ‏ ‏تَفَصِّيًا ‏ ‏مِنْ صُدُورِ الرِّجَالِ مِنْ النَّعَمِ مِنْ عُقُلِهِ قَالَ وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقُلْ أَحَدُكُمْ إِنِّي نَسِيتُ آيَةَ كَيْتَ وَكَيْتَ بَلْ هُوَ نُسِّيَ ‏","","",""],[3438,3438,"","বাবা সঙ্গে সঙ্গে যেতে চেষ্টা করার বিষয়ে আমরা তার কাছে কথা বলেছিলাম । পোশাক, শ্বাস, ঝুঁকি দেখার সুযোগ রয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ إِلَّا بِإِحْدَى ثَلَاثٍ ‏ ‏الثَّيِّبُ ‏ ‏الزَّانِي وَالنَّفْسُ بِالنَّفْسِ وَالتَّارِكُ لِدِينِهِ الْمُفَارِقُ لِلْجَمَاعَةِ ‏","","",""],[3439,3439,"","আমরা বাবার সঙ্গে থাকার বিষয়ে ঝগড়ার বিষয়ে কথা বলেছিলাম । প্রার্থনা করলে তার জন্য শুভেচ্ছা জানানো হবে এবং সেই ছেলে ও দেবতাদের মঙ্গল হবে । সে বলল সে সবকিছুতেই ছিল... ...কিন্তু স্বর্গে কখনোই আর সন্তুষ্ট নয়, তার নির্দেশনা আছে আর তারপর সে কিছু একটা বলার পরে পালিয়ে যাচ্ছে.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا إِذَا جَلَسْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الصَّلَاةِ قُلْنَا السَّلَامُ عَلَى اللَّهِ قَبْلَ عِبَادِهِ السَّلَامُ عَلَى ‏ ‏جِبْرِيلَ ‏ ‏السَّلَامُ عَلَى ‏ ‏مِيكَائِيلَ ‏ ‏السَّلَامُ عَلَى فُلَانٍ السَّلَامُ عَلَى فُلَانٍ فَسَمِعَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ اللَّهَ هُوَ السَّلَامُ فَإِذَا جَلَسَ أَحَدُكُمْ فِي الصَّلَاةِ فَلْيَقُلْ التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ فَإِذَا قَالَهَا أَصَابَتْ كُلَّ عَبْدٍ صَالِحٍ فِي السَّمَاءِ وَالْأَرْضِ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ ثُمَّ يَتَخَيَّرُ بَعْدُ مِنْ الدُّعَاءِ مَا شَاءَ ‏","","",""],[3440,3440,"","আমরা আমার বাবার সাথে কথা বলেছিলাম, হয়তো আমি আমার ভাইকে ভালোবাসি, প্রভু ও লর্ডের উপর আশীর্বাদ করুন, লর্ড লর্ড লর্ডের স্বপ্নের রাজা হওয়ার জন্য। ঈশ্বর তোমার সন্তানদের পরাজিত করতে দিবেন না, আর এর জন্য সব কিছু করতে পারেন না। কারণ তুমি তার গৃহে এক বছর থেকে আরেক বছর ছেড়ে চলে যাবে যাতে তুমি লড়াই করতে পারো। মানুষটি মানুষ কে হুমকি দিয়েছে তার সামনে আসার আগ পর্যন্ত... ...আর প্রভু এসে বললেন যে মানুষ আলো থেকে আসে... আমরা যদি এই সীমা অতিক্রম করতে পারতাম এবং লোকেরা তাদের চেতনা হারিয়ে ফেলত, তাহলে আমরা হয়তো সেই পথে যেতে পারতাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُسْلِمٍ الْهَجَرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏مَنْ سَرَّهُ أَنْ يَلْقَى اللَّهَ عَزَّ وَجَلَّ غَدًا مُسْلِمًا فَلْيُحَافِظْ عَلَى هَؤُلَاءِ الصَّلَوَاتِ ‏ ‏الْمَكْتُوبَاتِ ‏ ‏حَيْثُ ‏ ‏يُنَادَى بِهِنَّ فَإِنَّهُنَّ مِنْ سُنَنِ الْهُدَى وَإِنَّ اللَّهَ عَزَّ وَجَلَّ شَرَعَ لِنَبِيِّكُمْ سُنَنَ الْهُدَى وَمَا مِنْكُمْ إِلَّا وَلَهُ مَسْجِدٌ فِي بَيْتِهِ وَلَوْ صَلَّيْتُمْ فِي بُيُوتِكُمْ كَمَا ‏ ‏يُصَلِّي هَذَا الْمُتَخَلِّفُ فِي بَيْتِهِ لَتَرَكْتُمْ سُنَّةَ نَبِيِّكُمْ وَلَوْ تَرَكْتُمْ سُنَّةَ نَبِيِّكُمْ لَضَلَلْتُمْ وَلَقَدْ رَأَيْتُنِي وَمَا يَتَخَلَّفُ عَنْهَا إِلَّا مُنَافِقٌ مَعْلُومٌ نِفَاقُهُ وَلَقَدْ رَأَيْتُ الرَّجُلَ ‏ ‏يُهَادَى ‏ ‏بَيْنَ الرَّجُلَيْنِ حَتَّى يُقَامَ فِي الصَّفِّ وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ رَجُلٍ يَتَوَضَّأُ فَيُحْسِنُ الْوُضُوءَ ثُمَّ يَأْتِي مَسْجِدًا مِنْ الْمَسَاجِدِ ‏ ‏فَيَخْطُو خُطْوَةً إِلَّا رُفِعَ بِهَا دَرَجَةً أَوْ حُطَّ عَنْهُ بِهَا خَطِيئَةٌ أَوْ كُتِبَتْ لَهُ بِهَا حَسَنَةٌ ‏ ‏حَتَّى إِنْ كُنَّا لَنُقَارِبُ بَيْنَ الْخُطَى ‏ ‏وَإِنَّ فَضْلَ صَلَاةِ الرَّجُلِ فِي جَمَاعَةٍ عَلَى صَلَاتِهِ وَحْدَهُ بِخَمْسٍ وَعِشْرِينَ دَرَجَةً ‏","","",""],[3441,3441,"","আমরা বাবা আমাদের কথা বলেছিলাম যে আমরা একটি ছেলের সাথে কাজ করতে চেষ্টা করছি যে কিনা আলেয়া থেকে দূরে চলে যায়। আর তার বন্ধু বিশ্বাস করে যে তুমি তার মায়ের কথায় তার সীল মেরে ফেলবে। তোমার মত উজ্জ্বল হও, আর সব কিছু করতে হবে না। খুশি যে আমাকে জেলে যেতে হবে যদি না সে আগুন পেতে পারে এবং সে সেখানে যাবে। তার আগুন লাগে, তার লেখক আছে, যারা ভ্রূণের কাজ শুরু করতে চায়।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ الصَّادِقُ الْمُصَدَّقُ ‏ ‏إِنَّ أَحَدَكُمْ يُجْمَعُ خَلْقُهُ فِي بَطْنِ أُمِّهِ فِي أَرْبَعِينَ يَوْمًا ثُمَّ يَكُونُ عَلَقَةً مِثْلَ ذَلِكَ ثُمَّ يَكُونُ ‏ ‏مُضْغَةً ‏ ‏مِثْلَ ذَلِكَ ثُمَّ يُرْسَلُ إِلَيْهِ الْمَلَكُ فَيَنْفُخُ فِيهِ الرُّوحَ وَيُؤْمَرُ بِأَرْبَعِ كَلِمَاتٍ رِزْقِهِ وَأَجَلِهِ وَعَمَلِهِ وَشَقِيٌّ أَمْ سَعِيدٌ فَوَالَّذِي لَا إِلَهَ غَيْرُهُ إِنَّ أَحَدَكُمْ لَيَعْمَلُ بِعَمَلِ أَهْلِ الْجَنَّةِ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَهَا إِلَّا ذِرَاعٌ فَيَسْبِقُ عَلَيْهِ الْكِتَابُ فَيُخْتَمُ لَهُ بِعَمَلِ أَهْلِ النَّارِ فَيَدْخُلُهَا وَإِنَّ الرَّجُلَ لَيَعْمَلُ بِعَمَلِ أَهْلِ النَّارِ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَهَا إِلَّا ذِرَاعٌ فَيَسْبِقُ عَلَيْهِ الْكِتَابُ فَيُخْتَمُ لَهُ بِعَمَلِ أَهْلِ الْجَنَّةِ فَيَدْخُلُهَا ‏","","",""],[3442,3442,"","আমরা বাবার দোহাইের ব্যাপারে কথা বলেছি, আমি বলেছি ঈশ্বরকে বলতে যে আমাকে তার কাছে আত্মসমর্পণ করতে হবে আর তাকে আত্মসমর্পণ করতে হবে যাদের কাছে সম্মানিত করা হবে। আগুনের ভেতর ঢুকে পড়ো?","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَلِمَةً وَقُلْتُ أُخْرَى قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ مَاتَ لَا يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ الْجَنَّةَ ‏ ‏قَالَ ‏ ‏وَقُلْتُ ‏ ‏أَنَا ‏ ‏مَنْ مَاتَ يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ النَّارَ ‏","","",""],[3443,3443,"","আমি মনে করেছিলাম যে, তিনি উত্তরাধিকারসূত্রে পাওয়া টাকা দিয়ে উত্তরাধিকারসূত্রে প্রাপ্ত অর্থ দিয়ে উত্তরাধিকারসূত্রে পেয়েছিলেন । একটা কাজ করতে হবে, তুমি তোমার টাকা নিয়ে এসেছ আর উত্তর দাও যা তুমি করেছ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏الْحَارِثِ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّكُمْ مَالُ وَارِثِهِ أَحَبُّ إِلَيْهِ مِنْ مَالِهِ قَالَ قَالُوا يَا رَسُولَ اللَّهِ مَا مِنَّا أَحَدٌ إِلَّا مَالُهُ أَحَبُّ إِلَيْهِ مِنْ مَالِ وَارِثِهِ قَالَ ‏ ‏اعْلَمُوا أَنَّهُ لَيْسَ مِنْكُمْ أَحَدٌ إِلَّا مَالُ وَارِثِهِ أَحَبُّ إِلَيْهِ مِنْ مَالِهِ مَا لَكَ مِنْ مَالِكَ إِلَّا مَا قَدَّمْتَ وَمَالُ وَارِثِكِ مَا أَخَّرْتَ ‏","","",""],[3444,3444,"","সে ঈশ্বরের কাছে প্রার্থনা করলো, আর তার কাছে প্রার্থনা করলো, যখন ছেলেটা বলেছিল আমরা গুলি করিনি। কিন্তু গন্ধটা হচ্ছে শ্বাস নিতে সাহস","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا تَعُدُّونَ فِيكُمْ ‏ ‏الصُّرَعَةَ ‏ ‏قَالَ قُلْنَا الَّذِي لَا يَصْرَعُهُ الرِّجَالُ قَالَ قَالَ لَا وَلَكِنْ ‏ ‏الصُّرَعَةُ ‏ ‏الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ ‏","","",""],[3445,3445,"","সে ঈশ্বরের কাছে প্রার্থনা করলো, আর তুমি যা করবে, সে সেটা দেবে।","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا تَعُدُّونَ فِيكُمْ ‏ ‏الرَّقُوبَ ‏ ‏قَالَ قُلْنَا الَّذِي لَا وَلَدَ لَهُ ‏ ‏قَالَ لَا وَلَكِنْ ‏ ‏الرَّقُوبُ ‏ ‏الَّذِي لَمْ يُقَدِّمْ مِنْ وَلَدِهِ شَيْئًا ‏","","",""],[3446,3446,"","আমরা বাবা কথা বলেছিলাম একবার কথা বলার চেষ্টা করছি। তাদের একজন শ্বাস নিতে যাচ্ছে আর অন্য একজন তাকে আদেশ করছে। সে এখন পাহাড়ের মাঝখানে আছে। তাকে পতনের ভয় পায় এবং চলে যেতে হয়।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏الْحَارِثِ بْنِ سُوَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَدِيثَيْنِ أَحَدَهُمَا عَنْ نَفْسِهِ وَالْآخَرَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏إِنَّ الْمُؤْمِنَ يَرَى ذُنُوبَهُ كَأَنَّهُ فِي أَصْلِ جَبَلٍ يَخَافُ أَنْ يَقَعَ عَلَيْهِ وَإِنَّ الْفَاجِرَ يَرَى ذُنُوبَهُ كَذُبَابٍ وَقَعَ عَلَى أَنْفِهِ فَقَالَ لَهُ هَكَذَا فَطَارَ ‏","","",""],[3447,3447,"","সে ঈশ্বরের কাছে প্রার্থনা করলো, আর তাকে সারাজীবন আনন্দ দেবে। আমি তার আর তার সাথে গিয়ে তার সাথে যাই, আর তার হিংসার জন্য যা আমি তাকে দিয়েছি, আর আমি তার জন্য যা করেছি, তা তার হাতের পুতুলে চলে গেল। আমি তার সাথে আছি। আমি এখন তাকে খুঁজেছি। আমি তোমার জন্য প্রার্থনা করছি। যখন সে এটা করলো, তার লড়াই আর তার হিংসার কথা বলছি, তার মতো।","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَلَّهُ أَفْرَحُ بِتَوْبَةِ أَحَدِكُمْ مِنْ رَجُلٍ خَرَجَ بِأَرْضٍ ‏ ‏دَوِّيَّةٍ ‏ ‏مَهْلَكَةٍ مَعَهُ ‏ ‏رَاحِلَتُهُ ‏ ‏عَلَيْهَا طَعَامُهُ وَشَرَابُهُ وَزَادُهُ وَمَا يُصْلِحُهُ فَأَضَلَّهَا فَخَرَجَ فِي طَلَبِهَا حَتَّى إِذَا أَدْرَكَهُ الْمَوْتُ فَلَمْ يَجِدْهَا قَالَ أَرْجِعُ إِلَى مَكَانِي الَّذِي أَضْلَلْتُهَا فِيهِ فَأَمُوتُ فِيهِ قَالَ فَأَتَى مَكَانَهُ فَغَلَبَتْهُ عَيْنُهُ فَاسْتَيْقَظَ فَإِذَا ‏ ‏رَاحِلَتُهُ ‏ ‏عِنْدَ رَأْسِهِ عَلَيْهَا طَعَامُهُ وَشَرَابُهُ وَزَادُهُ وَمَا يُصْلِحُهُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏مِثْلَهُ ‏","","",""],[3448,3448,"","কালোরা বলেছিল যে, ঈশ্বর হয়তো তার নিয়তির ভয়ে তার পাপ দেখতে পান । তাই।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏الْحَارِثِ بْنِ سُوَيْدٍ ‏ ‏وَالْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏قَالَا قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏إِنَّ الْمُؤْمِنَ يَرَى ذُنُوبَهُ كَأَنَّهُ فِي أَصْلِ جَبَلٍ يَخَافُ أَنْ يَقَعَ عَلَيْهِ وَإِنَّ الْفَاجِرَ يَرَى ذُنُوبَهُ كَذُبَابٍ وَقَعَ عَلَى أَنْفِهِ فَقَالَ بِهِ هَكَذَا فَطَارَ ‏","","",""],[3449,3449,"","তিনি ঈশ্বরের কাছে তার জন্য প্রার্থনা করেছিলেন এবং তিনি তার জীবন ছেড়ে এবং তারপর আমি আপনার একজন অন্য জনের কাছে ব্যাখ্যা করব. আমি দুঃখিত যে তার নিজের একজন আছে, সে চলে গেছে আর সে তার দোরগোড়ায় চলে গেছে, আমি তাকে মেরে ফেলবো, তার ধারণা আর পানীয়র জন্য প্রার্থনা করার সময়।","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَلَّهُ أَفْرَحُ بِتَوْبَةِ أَحَدِكُمْ مِنْ رَجُلٍ خَرَجَ بِأَرْضٍ ‏ ‏دَوِّيَّةٍ ‏ ‏ثُمَّ ‏ ‏قَالَ ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَدِيثَيْنِ أَحَدَهُمَا عَنْ نَفْسِهِ وَالْآخَرَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَهْلَكَةٍ مَعَهُ ‏ ‏رَاحِلَتُهُ ‏ ‏عَلَيْهَا ‏ ‏زَادُهُ ‏ ‏وَطَعَامُهُ وَشَرَابُهُ وَمَا يُصْلِحُهُ فَأَضَلَّهَا فَخَرَجَ فِي طَلَبِهَا حَتَّى إِذَا أَدْرَكَهُ الْمَوْتُ قَالَ أَرْجِعُ إِلَى مَكَانِي الَّذِي أَضْلَلْتُهَا فِيهِ فَأَمُوتُ فِيهِ قَالَ فَرَجَعَ فَغَلَبَتْهُ عَيْنُهُ فَاسْتَيْقَظَ فَإِذَا ‏ ‏رَاحِلَتُهُ ‏ ‏عِنْدَ رَأْسِهِ عَلَيْهَا ‏ ‏زَادُهُ ‏ ‏وَطَعَامُهُ وَشَرَابُهُ وَمَا يُصْلِحُهُ ‏","","",""],[3450,3450,"","বাবা আমাদের কথা বলেছিলাম, সে তার বাবার ছায়াকে মেরে ফেলবে না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُقْتَلُ نَفْسٌ ظُلْمًا إِلَّا كَانَ عَلَى ابْنِ ‏ ‏آدَمَ ‏ ‏الْأَوَّلِ ‏ ‏كِفْلٌ ‏ ‏مِنْ دَمِهَا لِأَنَّهُ كَانَ أَوَّلَ مَنْ ‏ ‏سَنَّ ‏ ‏الْقَتْلَ ‏","","",""],[3451,3451,"","আমরা বাবা আর তার ছেলের সাথে জীবিত আর মরলে মারা যাবো। মানে, যদি তুমি বেঁচে থাকতে চাও, তাহলে ঈশ্বর তোমাকে কখনোই ভালো কিছু দেবে না। ভাগ্য এবং তার ভাগ্য.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏وَيَحْيَى ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏حَدَّثَنِي ‏ ‏عُمَارَةُ ‏ ‏حَدَّثَنِي ‏ ‏الْأَسْوَدُ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏لَا يَجْعَلُ أَحَدُكُمْ لِلشَّيْطَانِ مِنْ نَفْسِهِ جُزْءًا لَا يَرَى إِلَّا أَنَّ حَقًا عَلَيْهِ أَنْ لَا يَنْصَرِفَ إِلَّا عَنْ يَمِينِهِ لَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنَّ أَكْثَرَ انْصِرَافِهِ لَعَلَى يَسَارِهِ ‏","","",""],[3452,3452,"","আমরা আমার বাবার সাথে কথা বলেছিলাম একবার তাকে ভালবাসতে চাইলে সে বলবে তুমি প্রভুর দয়ায় যা বলবে, তোমার শক্তি তাদের রক্ষা করবে এবং বলবে, কিন্তু ঈশ্বর তা করবেন। হয়তো তারা তাদের আলিঙ্গন করবে এবং বলবে আল্লাহ হয়ত তাকে আগুন হিসেবে দেখে যাবে। তারা কখনো বলেনি যে ঈশ্বর শান্তি এবং শান্তি নিয়ে এসেছেন। আমি ঈশ্বরের কাছে প্রার্থনা করেছি যেন তিনি তাকে বলেন যে, তিনি এমন এক লোককে হত্যা করবেন, যে মানুষকে হত্যা করবে। তুমি আমার আর আমার ছড়ির মধ্যে থেকে যার মানে তুমি এত দু:খজনক হয়ে ওদের ক্ষমা কর, তোমার শত্রু তোমাদের দু'জন বৃদ্ধের মত। যে কুত্তিরা তাদের ছেড়ে দিবে না, আমি তাকে বলে দেব, সে আমাকে মার খাওয়ার শপথ নিয়ে বলল। ঐ দিন সে বলেছিল, ছেলে হবে না বরং বাবা ঈশ্বরের দ্বারা পরাজিত. তারা ঋণ দিতে চায়, আর ঈশ্বর চান যে শেষটা ঈশ্বর শাসন করুক, যখন তুমি মহান অত্যাচার করবে, আমরা এটা নিয়ে কথা বলেছি. আমার বাবা বলেছিল. আমার বাবা বলেছেন যে তিনি কোন কাজেরই না। আল্লাহ তাদের রক্ষা করুন। তোমার ভালো ছেলে, আমি আবার বেঁচে গেছি। আর বলছি, সে বলেছে সে হয়তো চলে গেছে। তুমি অনেক বেশি খুন করেছ, আর তুমি তাকে আঘাত করেছ আর বলে দাও।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ يَوْمُ ‏ ‏بَدْرٍ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا تَقُولُونَ فِي هَؤُلَاءِ الْأَسْرَى قَالَ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَا رَسُولَ اللَّهِ قَوْمُكَ وَأَهْلُكَ اسْتَبْقِهِمْ ‏ ‏وَاسْتَأْنِ ‏ ‏بِهِمْ لَعَلَّ اللَّهَ أَنْ يَتُوبَ عَلَيْهِمْ قَالَ وَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ أَخْرَجُوكَ وَكَذَّبُوكَ قَرِّبْهُمْ فَاضْرِبْ أَعْنَاقَهُمْ قَالَ وَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ رَوَاحَةَ ‏ ‏يَا رَسُولَ اللَّهِ انْظُرْ وَادِيًا كَثِيرَ الْحَطَبِ فَأَدْخِلْهُمْ فِيهِ ثُمَّ ‏ ‏أَضْرِمْ ‏ ‏عَلَيْهِمْ نَارًا قَالَ فَقَالَ ‏ ‏الْعَبَّاسُ ‏ ‏قَطَعْتَ رَحِمَكَ قَالَ فَدَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَمْ يَرُدَّ عَلَيْهِمْ شَيْئًا قَالَ فَقَالَ نَاسٌ يَأْخُذُ بِقَوْلِ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَقَالَ نَاسٌ يَأْخُذُ بِقَوْلِ ‏ ‏عُمَرَ ‏ ‏وَقَالَ نَاسٌ يَأْخُذُ بِقَوْلِ ‏ ‏عَبْدِ اللَّهِ بْنِ رَوَاحَةَ ‏ ‏قَالَ فَخَرَجَ عَلَيْهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ اللَّهَ لَيُلِينُ قُلُوبَ رِجَالٍ فِيهِ حَتَّى تَكُونَ أَلْيَنَ مِنْ اللَّبَنِ وَإِنَّ اللَّهَ لَيَشُدُّ قُلُوبَ رِجَالٍ فِيهِ حَتَّى تَكُونَ أَشَدَّ مِنْ الْحِجَارَةِ وَإِنَّ مَثَلَكَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏كَمَثَلِ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَالَ ‏ { ‏مَنْ تَبِعَنِي فَإِنَّهُ مِنِّي وَمَنْ عَصَانِي فَإِنَّكَ غَفُورٌ رَحِيمٌ ‏} ‏وَمَثَلَكَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏كَمَثَلِ ‏ ‏عِيسَى ‏ ‏قَالَ ‏ { ‏إِنْ تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ وَإِنْ تَغْفِرْ لَهُمْ فَإِنَّكَ أَنْتَ الْعَزِيزُ الْحَكِيمُ ‏} ‏وَإِنَّ مَثَلَكَ يَا ‏ ‏عُمَرُ ‏ ‏كَمَثَلِ ‏ ‏نُوحٍ ‏ ‏قَالَ ‏ { ‏رَبِّ لَا تَذَرْ عَلَى الْأَرْضِ مِنْ الْكَافِرِينَ دَيَّارًا ‏} ‏وَإِنَّ مِثْلَكَ يَا ‏ ‏عُمَرُ ‏ ‏كَمَثَلِ ‏ ‏مُوسَى ‏ ‏قَالَ رَبِّ ‏ { ‏اشْدُدْ عَلَى قُلُوبِهِمْ فَلَا يُؤْمِنُوا حَتَّى يَرَوْا الْعَذَابَ الْأَلِيمَ ‏} ‏أَنْتُمْ ‏ ‏عَالَةٌ ‏ ‏فَلَا ‏ ‏يَنْفَلِتَنَّ ‏ ‏مِنْهُمْ أَحَدٌ إِلَّا بِفِدَاءٍ أَوْ ضَرْبَةِ عُنُقٍ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَقُلْتُ ‏ ‏يَا رَسُولَ اللَّهِ إِلَّا ‏ ‏سُهَيْلُ ابْنُ بَيْضَاءَ ‏ ‏فَإِنِّي قَدْ سَمِعْتُهُ يَذْكُرُ الْإِسْلَامَ قَالَ فَسَكَتَ قَالَ فَمَا رَأَيْتُنِي فِي يَوْمٍ أَخْوَفَ أَنْ تَقَعَ عَلَيَّ حِجَارَةٌ مِنْ السَّمَاءِ فِي ذَلِكَ الْيَوْمِ حَتَّى قَالَ إِلَّا ‏ ‏سُهَيْلُ ابْنُ بَيْضَاءَ ‏ ‏قَالَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏مَا كَانَ لِنَبِيٍّ أَنْ يَكُونَ لَهُ أَسْرَى حَتَّى ‏ ‏يُثْخِنَ ‏ ‏فِي الْأَرْضِ تُرِيدُونَ ‏ ‏عَرَضَ ‏ ‏الدُّنْيَا وَاللَّهُ يُرِيدُ الْآخِرَةَ وَاللَّهُ عَزِيزٌ حَكِيمٌ ‏ ‏إِلَى قَوْلِهِ ‏ ‏لَوْلَا كِتَابٌ مِنْ اللَّهِ سَبَقَ لَمَسَّكُمْ فِيمَا أَخَذْتُمْ عَذَابٌ عَظِيمٌ ‏} ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي ابْنَ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏فَذَكَرَ نَحْوَهُ إِلَّا أَنَّهُ قَالَ إِلَّا ‏ ‏سُهَيْلُ ابْنُ بَيْضَاءَ ‏ ‏وَقَالَ فِي قَوْلِ ‏ ‏أَبِي بَكْرٍ ‏ ‏قَالَ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏عِتْرَتُكَ ‏ ‏وَأَصْلُكَ وَقَوْمُكَ ‏ ‏تَجَاوَزْ ‏ ‏عَنْهُمْ يَسْتَنْقِذْهُمْ اللَّهُ بِكَ مِنْ النَّارِ قَالَ وَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ رَوَاحَةَ ‏ ‏يَا رَسُولَ اللَّهِ أَنْتَ بِوَادٍ كَثِيرِ الْحَطَبِ ‏ ‏فَأَضْرِمْهُ ‏ ‏نَارًا ثُمَّ أَلْقِهِمْ فِيهِ فَقَالَ ‏ ‏الْعَبَّاسُ ‏ ‏قَطَعَ اللَّهُ رَحِمَكَ ‏ ‏حَدَّثَنَاه ‏ ‏حُسَيْنٌ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ يَعْنِي ابْنَ حَازِمٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏فَذَكَرَ نَحْوَهُ إِلَّا أَنَّهُ قَالَ فَقَامَ ‏ ‏عَبْدُ اللَّهِ بْنُ جَحْشٍ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَعْدَاءُ اللَّهِ كَذَّبُوكَ وَآذَوْكَ وَأَخْرَجُوكَ وَقَاتَلُوكَ وَأَنْتَ بِوَادٍ كَثِيرِ الْحَطَبِ فَاجْمَعْ لَهُمْ حَطَبًا كَثِيرًا ثُمَّ ‏ ‏أَضْرِمْهُ ‏ ‏عَلَيْهِمْ وَقَالَ ‏ ‏سَهْلُ ابْنُ بَيْضَاءَ ‏","","",""],[3453,3453,"","বাবা তার চেয়ে ভাল একটা ছেলেকে খোঁজার চেষ্টা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏خِشْفِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَعَلَ ‏ ‏الدِّيَةَ ‏ ‏فِي الْخَطَإِ أَخْمَاسًا ‏","","",""],[3454,3454,"","ঈশ্বর তাকে সবচেয়ে মিষ্টি ও রোমাঞ্চকর ব্যক্তি হতে শিক্ষা দিয়েছেন । মানুষকে কিছু জিজ্ঞেস করবে না এবং বিশ্বাস করবে না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُسْلِمٍ الْهَجَرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ الْمِسْكِينُ بِالطَّوَّافِ وَلَا بِالَّذِي تَرُدُّهُ التَّمْرَةُ وَلَا التَّمْرَتَانِ وَلَا اللُّقْمَةُ وَلَا اللُّقْمَتَانِ وَلَكِنْ الْمِسْكِينُ ‏ ‏الْمُتَعَفِّفُ ‏ ‏الَّذِي لَا يَسْأَلُ النَّاسَ شَيْئًا وَلَا يُفْطَنُ لَهُ فَيُتَصَدَّقَ عَلَيْهِ ‏","","",""],[3455,3455,"","বাবা বলেছিলেন, তার চেয়ে ভালো হওয়ার চেষ্টা করাটা, আল্লাহ তার জন্য প্রার্থনা করেছেন এবং তার দুর্দশার উজ্জ্বল আলো দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى صَلَاةً إِلَّا لِمِيقَاتِهَا إِلَّا صَلَاتَيْنِ صَلَاةَ الْمَغْرِبِ وَالْعِشَاءِ ‏ ‏بِجَمْعٍ ‏ ‏وَصَلَاةَ الْفَجْرِ يَوْمَئِذٍ قَبْلَ مِيقَاتِهَا ‏","","",""],[3456,3456,"","আমরা বাবার সাথে ঈশ্বরের দয়া নিয়ে যুদ্ধ করেছি, বিশ্বাস করা উচিৎ যে, বিশ্বাস তোমাকে ভয় দেখাচ্ছে আর ভালোর জন্য খারাপ ভাবে ঈশ্বরকে ঘৃণা করার হুমকি দেবে। মিথ্যা এবং মুক্তা এমনকি লেখেন যে ঈশ্বর জয়ী হয়েছেন এবং পাপ করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْكُمْ بِالصِّدْقِ فَإِنَّ الصِّدْقَ يَهْدِي إِلَى ‏ ‏الْبِرِّ ‏ ‏وَإِنَّ ‏ ‏الْبِرَّ ‏ ‏يَهْدِي إِلَى الْجَنَّةِ وَمَا يَزَالُ الرَّجُلُ يَصْدُقُ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ عَزَّ وَجَلَّ صِدِّيقًا وَإِيَّاكُمْ وَالْكَذِبَ فَإِنَّ الْكَذِبَ يَهْدِي إِلَى ‏ ‏الْفُجُورِ ‏ ‏وَإِنَّ ‏ ‏الْفُجُورَ ‏ ‏يَهْدِي إِلَى النَّارِ وَمَا يَزَالُ الرَّجُلُ يَكْذِبُ ‏ ‏وَيَتَحَرَّى ‏ ‏الْكَذِبَ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ عَزَّ وَجَلَّ كَذَّابًا ‏","","",""],[3457,3457,"","আমরা বাবার দোহাই দিয়ে বলছি, আমি শুধু তাদের পাশে দাঁড়িয়ে আছি, তোমার পরে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا ‏ ‏فَرَطُكُمْ ‏ ‏عَلَى الْحَوْضِ وَلَأُنَازَعَنَّ أَقْوَامًا ثُمَّ لَأُغْلَبَنَّ عَلَيْهِمْ فَأَقُولُ يَا رَبِّ أَصْحَابِي فَيَقُولُ إِنَّكَ لَا تَدْرِي مَا ‏ ‏أَحْدَثُوا ‏ ‏بَعْدَكَ ‏","","",""],[3458,3458,"","আমরা বাবার সাথে কথা বলেছিলাম একটা ছেলের বিয়ের চেষ্টা করে... ...যে হয়তো বলেছিল সে এটা করতে পারে, তাকে দেয়ালের ভিতর দিয়ে যেতে হবে, দেয়াল দিয়ে যেতে হবে। ঈশ্বরের ইচ্ছা","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ سَيَكُونُ عَلَيْكُمْ أُمَرَاءُ وَتَرَوْنَ ‏ ‏أَثَرَةً ‏ ‏قَالَ قَالُوا يَا رَسُولَ اللَّهِ فَمَا يَصْنَعُ مَنْ أَدْرَكَ ذَاكَ مِنَّا قَالَ ‏ ‏أَدُّوا الْحَقَّ الَّذِي عَلَيْكُمْ وَسَلُوا اللَّهَ الَّذِي لَكُمْ ‏","","",""],[3459,3459,"","শুনলাম সালমানের কথা শুনলাম, আমি শুনেছি যে তিনি শুনেছেন, তিনি শুনেছেন, ঈশ্বর আপনাকে আত্মসমর্পণ করবেন, আর আমি তাকে কখনোই অস্বীকার করব না।","‏ ‏سَمِعْت ‏ ‏يَحْيَى ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْدَ بْنَ وَهْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكُمْ سَتَرَوْنَ بَعْدِي ‏ ‏أَثَرَةً ‏ ‏وَأُمُورًا تُنْكِرُونَهَا قَالَ قُلْنَا مَا تَأْمُرُنَا قَالَ أَدُّوا إِلَيْهِمْ حَقَّهُمْ وَسَلُوا اللَّهَ حَقَّكُمْ ‏","","",""],[3460,3460,"","আমরা বাবার সঙ্গে তার দুর্দশার সঙ্গে লড়াই করার চেষ্টা করার বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏حَارِثَةَ بْنِ مُضَرِّبٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏لِابْنِ النَّوَّاحَةِ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَوْلَا أَنَّكَ رَسُولٌ لَقَتَلْتُكَ فَأَمَّا الْيَوْمَ فَلَسْتَ بِرَسُولٍ يَا ‏ ‏خَرَشَةُ ‏ ‏قُمْ فَاضْرِبْ عُنُقَهُ قَالَ فَقَامَ إِلَيْهِ فَضَرَبَ عُنُقَهُ ‏","","",""],[3461,3461,"","আমরা আমার বাবার কথা বলেছিলাম ঘোড়ার কথা বলা । তিনি সেই ঘটনাগুলো উল্লেখ করেছিলেন, যেগুলো তাদের মনে মনে হয়তো সিগারেটের পরীক্ষা করা হতো আর সেগুলো কখনোই শেষ হতো না । তাদের হাতে এক সপ্তাহ আছে, বলতে গেলে ঈশ্বর আছে, আর আমি তাকে তার নাম শিখাবো... ...এই কল্পনায়... দিনের ছায়া.","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏يُسَيْرِ بْنِ جَابِرٍ ‏ ‏قَالَ ‏ ‏هَاجَتْ رِيحٌ حَمْرَاءُ ‏ ‏بِالْكُوفَةِ ‏ ‏فَجَاءَ رَجُلٌ لَيْسَ لَهُ ‏ ‏هِجِّيرَى ‏ ‏إِلَّا يَا ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏جَاءَتْ السَّاعَةُ قَالَ ‏ ‏وَكَانَ مُتَّكِئًا فَجَلَسَ فَقَالَ إِنَّ السَّاعَةَ لَا تَقُومُ حَتَّى لَا يُقْسَمَ مِيرَاثٌ وَلَا يُفْرَحَ بِغَنِيمَةٍ قَالَ عَدُوًّا يَجْمَعُونَ لِأَهْلِ الْإِسْلَامِ وَيَجْمَعُ لَهُمْ أَهْلُ الْإِسْلَامِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ جَاءَهُمْ ‏ ‏الصَّرِيخُ ‏ ‏أَنَّ ‏ ‏الدَّجَّالَ ‏ ‏قَدْ خَلَفَ فِي ‏ ‏ذَرَارِيِّهِمْ ‏ ‏فَيَرْفُضُونَ مَا فِي أَيْدِيهِمْ وَيُقْبِلُونَ فَيَبْعَثُونَ عَشَرَةَ فَوَارِسَ ‏ ‏طَلِيعَةً ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَأَعْرِفُ أَسْمَاءَهُمْ وَأَسْمَاءَ آبَائِهِمْ وَأَلْوَانَ خُيُولِهِمْ هُمْ خَيْرُ فَوَارِسَ عَلَى ظَهَرِ الْأَرْضِ يَوْمَئِذٍ ‏ ‏أَوْ قَالَ هُمْ مِنْ خَيْرِ فَوَارِسَ عَلَى ظَهَرِ الْأَرْضِ يَوْمَئِذٍ ‏","","",""],[3462,3462,"","আমরা একটা ছেলের কথা বলেছি যে বেনের কাছে সাহায্য করার জন্য চলে গেছে কিন্তু ঈশ্বরের লর্ডকে রক্ষা করতে, আমি বেঁচে থাকতে চাই আর এটা নিয়ে এত কিছু ভুলে যেতে চাই না। আমি ভয় পাচ্ছি যে, এটাই শেষ চেষ্টা করার জন্য। সে মাটিতে গিয়েছিল অথবা বলেছিল যে, তার লোকেদের সেলাই করার অধিকার ছিল ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏كُنْتُ لَا أُحْجَبُ عَنْ ‏ ‏النَّجْوَى ‏ ‏وَلَا عَنْ كَذَا وَلَا عَنْ كَذَا ‏ ‏قَالَ ‏ ‏ابْنُ عَوْنٍ ‏ ‏فَنَسِيَ وَاحِدَةً وَنَسِيتُ أَنَا وَاحِدَةً قَالَ فَأَتَيْتُهُ وَعِنْدَهُ ‏ ‏مَالِكُ بْنُ مُرَارَةَ الرَّهَاوِيُّ ‏ ‏فَأَدْرَكْتُ مِنْ آخِرِ حَدِيثِهِ وَهُوَ يَقُولُ ‏ ‏يَا رَسُولَ اللَّهِ قَدْ قُسِمَ لِي مِنْ الْجِمَالِ مَا ‏ ‏تَرَى فَمَا أُحِبُّ أَنَّ أَحَدًا مِنْ النَّاسِ فَضَلَنِي ‏ ‏بِشِرَاكَيْنِ ‏ ‏فَمَا فَوْقَهَا أَفَلَيْسَ ذَلِكَ هُوَ ‏ ‏الْبَغْيُ ‏ ‏قَالَ ‏ ‏لَا لَيْسَ ذَلِكَ ‏ ‏بِالْبَغْيِ ‏ ‏وَلَكِنَّ ‏ ‏الْبَغْيَ ‏ ‏مَنْ ‏ ‏بَطِرَ ‏ ‏قَالَ ‏ ‏أَوْ قَالَ ‏ ‏سَفِهَ ‏ ‏الْحَقَّ ‏ ‏وَغَمَطَ ‏ ‏النَّاسَ ‏","","",""],[3463,3463,"","আমরা একটি সুখী ছেলে কথা বলেছি যে তার মৃত্যুর সময় ঈশ্বরের কাছে কথা বলেছে। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তিনি যখন মনে করেছিলেন যে ঈশ্বর তাকে প্রার্থনা করেছেন এবং তাকে প্রার্থনা করেছেন, তখন তিনি আত্মসমর্পণ করবেন। তাকে তার দেবতা হিসেবে মনোনীত করা এবং তার ঈশ্বর হওয়া.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَوْنٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏إِذَا حُدِّثْتُمْ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدِيثًا فَظُنُّوا بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَهْيَاهُ ‏ ‏وَأَهْدَاهُ وَأَتْقَاهُ ‏","","",""],[3464,3464,"","আমরা আমার বাবা আর তার পরিবারের কথা বলেছি, ঈশ্বর এটা করেছেন আর একটা রাতের জন্য আত্মসমর্পণ করেছেন যেটা ব্যর্থ হয়েছে যদি এটা খারাপ জায়গাও হয়।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ فَلَمْ يَزَلْ قَائِمًا حَتَّى هَمَمْتُ بِأَمْرٍ سُوءٍ قُلْنَا وَمَا هَمَمْتَ بِهِ قَالَ هَمَمْتُ أَنْ أَجْلِسَ وَأَدَعَهُ ‏","","",""],[3465,3465,"","সে একটা গানের বিষ প্রয়োগ করে তাকে মেরে ফেলে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏زُبَيْدٌ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سِبَابُ الْمُسْلِمِ فُسُوقٌ وَقِتَالُهُ كُفْرٌ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِأَبِي وَائِلٍ ‏ ‏أَنْتَ سَمِعْتَ مِنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ نَعَمْ ‏","","",""],[3466,3466,"","ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং আপনার কাছ থেকে তিনি যে - সাহায্য গ্রহণ করেছেন, তা গ্রহণ করেছেন । তার ভাগ্যের দ্বারা খাওয়া, আর ঈশ্বরকে জিজ্ঞেস না করে, সে বলল, কিন্তু ঈশ্বর আমাকে কষ্ট দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْكُمْ مِنْ أَحَدٍ إِلَّا وَقَدْ وُكِّلَ بِهِ قَرِينُهُ مِنْ الْجِنِّ وَقَرِينُهُ مِنْ الْمَلَائِكَةِ قَالُوا وَإِيَّاكَ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏وَإِيَّايَ وَلَكِنَّ اللَّهَ أَعَانَنِي عَلَيْهِ فَلَا يَأْمُرُنِي إِلَّا بِحَقٍّ ‏","","",""],[3467,3467,"","আমরা একটা পিপপি পুত্র সম্বন্ধে বলেছিলাম, যিনি আমাকে বলেছিলেন যে তিনি আমাকে বলতে চাচ্ছেন যে তিনি আমাকে বলতে চাচ্ছেন যে তিনি একজন ভালো মানুষ । ঈশ্বর তাকে আদেশ দিয়েছেন এবং মারা যাবেন, বলেছিলেন যে আমরা ভিতরে ভিতরে আছি, পাথরের খোঁজে । ঈশ্বরের কৃপায় তিনি তাকে ঈশ্বরের অনুগ্রহের জন্য সমর্পণ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏مُجَاهِدًا ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَبَا عُبَيْدَةَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا فِي ‏ ‏مَسْجِدِ الْخَيْفِ ‏ ‏لَيْلَةَ ‏ ‏عَرَفَةَ ‏ ‏قَبْلَ يَوْمِ ‏ ‏عَرَفَةَ ‏ ‏إِذْ سَمِعْنَا ‏ ‏حِسَّ ‏ ‏الْحَيَّةِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْتُلُوا قَالَ فَقُمْنَا قَالَ فَدَخَلَتْ شَقَّ جُحْرٍ فَأُتِيَ بِسَعَفَةٍ ‏ ‏فَأُضْرِمَ ‏ ‏فِيهَا نَارًا وَأَخَذْنَا عُودًا فَقَلَعْنَا عَنْهَا بَعْضَ الْجُحْرِ فَلَمْ نَجِدْهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعُوهَا وَقَاهَا اللَّهُ شَرَّكُمْ كَمَا وَقَاكُمْ شَرَّهَا ‏","","",""],[3468,3468,"","আমরা আমার বাবার একজন ভালো সন্তান হওয়ার কথা বলেছিলাম যে আমাকে সাহায্য করতে চেয়েছিল, ঈশ্বর তার কাছে প্রার্থনা করেছেন আর তিনি আমাদের ক্ষতি করার জন্য আমাদের কাছে আত্মসমর্পণ করবেন না, প্রভু, ঈশ্বরের দোহাই, তোমার প্রতি উৎসর্গকৃত হওয়া।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ هُوَ ابْنُ أَبِي خَالِدٍ ‏ ‏حَدَّثَنِي ‏ ‏قَيْسٌ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نَغْزُو مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ لَنَا نِسَاءٌ فَقُلْنَا يَا رَسُولَ اللَّهِ أَلَا ‏ ‏نَسْتَخْصِي فَنَهَانَا عَنْ ذَلِكَ ‏","","",""],[3469,3469,"","আমরা একটা ছেলের কথা বলেছিলাম যে আমি ঈশ্বরকে জিজ্ঞেস করেছি, সে বলছে যে, সে দু'জন মানুষের উপর হিসাব করে না, আর মানুষ তাকে শিখাচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنِي ‏ ‏قَيْسٌ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا حَسَدَ إِلَّا فِي اثْنَيْنِ رَجُلٌ آتَاهُ اللَّهُ مَالًا فَسَلَّطَهُ عَلَى هَلَكَتِهِ فِي الْحَقِّ وَرَجُلٌ آتَاهُ اللَّهُ حِكْمَةً فَهُوَ يَقْضِي بِهَا وَيُعَلِّمُهَا النَّاسَ ‏","","",""],[3470,3470,"","সেই সময়, আমি আমার বাবার সঙ্গে বাইবেল অধ্যয়ন করতে শুরু করেছিলাম । ভয় থেকে আলাদা লাইন, আদর্শ হচ্ছে আমার যাওয়ার পরিকল্পনা করা সমস্যার মধ্য দিয়ে যেতে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي يَعْلَى ‏ ‏عَنْ ‏ ‏رَبِيْعِ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ خَطَّ خَطًّا مُرَبَّعًا وَخَطَّ خَطًّا وَسَطَ الْخَطِّ الْمُرَبَّعِ وَخُطُوطًا إِلَى جَنْبِ الْخَطِّ الَّذِي وَسَطَ الْخَطِّ الْمُرَبَّعِ وَخَطٌّ خَارِجٌ مِنْ الْخَطِّ الْمُرَبَّعِ قَالَ هَلْ تَدْرُونَ مَا هَذَا قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ ‏ ‏هَذَا الْإِنْسَانُ الْخَطُّ الْأَوْسَطُ وَهَذِهِ الْخُطُوطُ الَّتِي إِلَى جَنْبِهِ الْأَعْرَاضُ تَنْهَشُهُ مِنْ كُلِّ مَكَانٍ إِنْ أَخْطَأَهُ هَذَا أَصَابَهُ هَذَا وَالْخَطُّ الْمُرَبَّعُ الْأَجَلُ الْمُحِيطُ بِهِ وَالْخَطُّ الْخَارِجُ الْأَمَلُ ‏","","",""],[3471,3471,"","ঈশ্বর তাকে তার প্রভুর কাছে প্রার্থনা করতে বলেন এবং আমাকে ভালবাসার বিষয় করতে বলেন । খারাপ লোকেরা অনেক দিন যেতে পারে, প্রভু, এটাই বলা হয়.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏أَصَابَ مِنْ امْرَأَةٍ قُبْلَةً فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْأَلُهُ عَنْ كَفَّارَتِهَا فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏أَقِمْ الصَّلَاةَ طَرَفَيْ النَّهَارِ ‏ ‏وَزُلَفًا ‏ ‏مِنْ اللَّيْلِ إِنَّ الْحَسَنَاتِ يُذْهِبْنَ السَّيِّئَاتِ ‏} ‏فَقَالَ يَا رَسُولَ اللَّهِ أَلِي هَذِهِ فَقَالَ لِمَنْ عَمِلَ كَذَا مِنْ أُمَّتِي ‏","","",""],[3472,3472,"","আমি আমার বাবার সাথে চিতাবাঘের কথা বলেছি যে কিনা ঈশ্বরের শান্তিয় ফিরে যাবে। আমি তোমাকে তার কাছে অনুরোধ করতে নিষেধ করছি। সে তার সাথে যোগ দিয়েছে এবং সে তাকে বড় করেছে। সে হয়তো এটা বলতে পারে, লর্ডের সাথে আমি এটা একটা থেকে শুনেছি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَمْنَعَنَّ أَحَدَكُمْ أَذَانُ ‏ ‏بِلَالٍ ‏ ‏عَنْ سَحُورِهِ فَإِنَّهُ يُؤَذِّنُ ‏ ‏أَوْ قَالَ يُنَادِي ‏ ‏لِيَرْجِعَ قَائِمُكُمْ وَيَنْتَبِهَ نَائِمُكُمْ لَيْسَ أَنْ يَقُولَ هَكَذَا وَضَمَّ يَدَهُ وَرَفَعَهَا وَلَكِنْ حَتَّى يَقُولَ هَكَذَا وَفَرَّقَ ‏ ‏يَحْيَى ‏ ‏بَيْنَ ‏ ‏السَّبَّابَتَيْنِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏هَذَا الْحَدِيثُ لَمْ أَسْمَعْهُ مِنْ أَحَدٍ ‏","","",""],[3473,3473,"","আমরা একটি সুখী ছেলের কথা বলেছি যে আমার সাথে আমার প্রেমে কথা বলেছে, ঈশ্বর তার শান্তির জন্য খুশি হতে পারেন আর এই তিনটি ঘটনায় আত্মসমর্পণ করতে পারেন।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏سُلَيْمَانُ بْنُ عَتِيقٍ ‏ ‏عَنْ ‏ ‏طَلْقِ بْنِ حَبِيبٍ ‏ ‏عَنِ ‏ ‏الْأَحْنَفِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَلَا هَلَكَ ‏ ‏الْمُتَنَطِّعُونَ ‏ ‏ثَلَاثَ مِرَارٍ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏فِي حَدِيثٍ طَوِيلٍ ‏","","",""],[3474,3474,"","আমরা আনন্দের সাথে বলছি যে, কিভাবে তিনি আমার বাবাকে ভালবাসতে সাহায্য করার চেষ্টা করেছেন। ঈশ্বর দাবি করেছেন, সে হাঁটু গেড়ে বসে আছে, যদি তাকে বলতে হয় যে, সে এটা মেনে নিতে চায়। যে তিনি মারা গেছেন.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي الرَّكْعَتَيْنِ كَأَنَّهُ عَلَى ‏ ‏الرَّضْفِ ‏ ‏قُلْتُ حَتَّى يَقُومَ قَالَ حَتَّى يَقُومَ ‏","","",""],[3475,3475,"","আমরা খেলার ব্যাপারে খুশি হয়েছি... ...আমার ছেলের ইচ্ছার থেকে কঠিন সময় নিয়ে। আমি আনন্দিত যে আমি ভাববাদীকে চুমু দেই আর আত্মসমর্পণ করি রাতের কাজের জন্য ইউনিটগুলো, আমরা জিতবো। আমরা বলবো, যদি আমরা ঘুমিয়ে থাকতাম, সে সূর্য জয় করতে পারতো, আর সে এটা করবে, তারা ভাববাদীকে জাগিয়ে তুলবে ওর কাছে আর তারা তোমাকে মেরে ফেলবে, ঘুম থেকে ঘুমোবে অথবা ভুলে যাবে","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏جَامِعُ بْنُ شَدَّادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي عَلْقَمَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏يَقُولُ ‏ ‏أَقْبَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏لَيْلًا فَنَزَلْنَا ‏ ‏دَهَاسًا ‏ ‏مِنْ الْأَرْضِ فَقَالَ مَنْ ‏ ‏يَكْلَؤُنَا ‏ ‏فَقَالَ ‏ ‏بِلَالٌ ‏ ‏أَنَا قَالَ إِذًا تَنَامَ قَالَ لَا فَنَامَ حَتَّى طَلَعَتْ الشَّمْسُ فَاسْتَيْقَظَ فُلَانٌ وَفُلَانٌ فِيهِمْ ‏ ‏عُمَرُ ‏ ‏فَقَالَ ‏ ‏اهْضِبُوا ‏ ‏فَاسْتَيْقَظَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏افْعَلُوا مَا كُنْتُمْ تَفْعَلُونَ فَلَمَّا فَعَلُوا قَالَ هَكَذَا فَافْعَلُوا لِمَنْ نَامَ مِنْكُمْ أَوْ نَسِيَ ‏","","",""],[3476,3476,"","আমরা গত দুই গ্রীষ্মের কথা বলেছি যা আমার ভালবাসার ভালো বন্ধু হিসেবে আমার সাথে ঘটেছে। আল্লাহ আছে এবং আমরা বলবো আমরা গালটি আঘাত করিনি এবং ইহুদিদের যেতে বলি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنِي ‏ ‏زُبَيْدٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ مِنَّا مَنْ ضَرَبَ الْخُدُودَ وَشَقَّ ‏ ‏الْجُيُوبَ ‏ ‏وَدَعَا ‏ ‏بِدَعْوَى ‏ ‏الْجَاهِلِيَّةِ ‏","","",""],[3477,3477,"","আমি কথা বলার চেষ্টা করেছি, যখন আমি ঈশ্বরকে বলতে চেয়েছিলাম, ঈশ্বর পাঁচ বছরে যা ধনী সে সব কিছুর আলো দিয়েছেন, আমি ঘুমাতে যাচ্ছি না, আর তুমি না। তুমি যা করছ তা হারবে এবং তুমি মৃত্যুর দিকে এগিয়ে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَلَمَةَ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أُوتِيَ نَبِيُّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَفَاتِيحَ كُلِّ شَيْءٍ غَيْرَ خَمْسٍ ‏ { ‏إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ وَيُنَزِّلُ ‏ ‏الْغَيْثَ ‏ ‏وَيَعْلَمُ مَا فِي الْأَرْحَامِ وَمَا تَدْرِي نَفْسٌ مَاذَا تَكْسِبُ غَدًا وَمَا تَدْرِي نَفْسٌ بِأَيِّ أَرْضٍ تَمُوتُ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ ‏}","","",""],[3478,3478,"","আমরা একজন পর্যটকের কথা বলেছিলাম যিনি আমার সঙ্গে আমার সঙ্গে কথা বলেছিলেন । তার গাল বা গাল দেখা পর্যন্ত তাকে গোপন রাখা উচিৎ... ...আর যতক্ষণ না সে তার গাল আর বাবাকে বড় দেখে আর সে তার কাজ করে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏زُهَيْرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏وَعَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَنَا ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكَبِّرُ فِي كُلِّ ‏ ‏خَفْضٍ ‏ ‏وَرَفْعٍ وَقِيَامٍ وَقُعُودٍ وَيُسَلِّمُ عَنْ يَمِينِهِ وَعَنْ يَسَارِهِ حَتَّى يُرَى بَيَاضُ خَدَّيْهِ ‏ ‏أَوْ خَدِّهِ ‏ ‏وَرَأَيْتُ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏يَفْعَلَانِ ذَلِكَ ‏","","",""],[3479,3479,"","আমি যে - ক্ষমতার অধীনে সন্তুষ্ট হতে চেয়েছিলাম, সেটার জন্য ঈশ্বরকে সমর্পণ করতে হতো । বলো, আমার কথা ভুলে যাওয়া উচিত? তাকে ভিতরে আসতে দাও, আমরা মই শ্বাস নিতে পারবো না, অথবা সূর্যের আলো পর্যন্তও তোমার কাছে আসবে না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏قُبَّةٍ ‏ ‏نَحْوٌ مِنْ أَرْبَعِينَ فَقَالَ أَتَرْضَوْنَ أَنْ تَكُونُوا رُبُعَ أَهْلِ الْجَنَّةِ قُلْنَا نَعَمْ قَالَ أَتَرْضَوْنَ أَنْ تَكُونُوا ثُلُثَ أَهْلِ الْجَنَّةِ قُلْنَا نَعَمْ قَالَ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏إِنِّي لَأَرْجُو أَنْ تَكُونُوا نِصْفَ أَهْلِ الْجَنَّةِ وَذَاكَ أَنَّ الْجَنَّةَ لَا يَدْخُلُهَا إِلَّا نَفْسٌ مُسْلِمَةٌ وَمَا أَنْتُمْ فِي الشِّرْكِ إِلَّا كَالشَّعْرَةِ الْبَيْضَاءِ فِي جِلْدِ ثَوْرٍ أَسْوَدَ أَوْ السَّوْدَاءِ فِي جِلْدِ ثَوْرٍ أَحْمَرَ ‏","","",""],[3480,3480,"","আমরা আমার বাবার সাথে কথা বলেছি যে জয়ের চেষ্টা করে। ঈশ্বর মুক্তি দিয়েছেন এবং আমি প্রার্থনা করছি যে তুমি তাকে আমার মায়ের ভালবাসা দিবে, আমার বাবা বড় হয়ে উঠছে। আমি গর্বিত নই। আমি তাকে সাহায্য করতে পারবো না কিন্তু তাকে হারতে পারি, আল্লাহ্‌ জানেন আমি তোমাকে ঘুমের জন্য বলতে চাচ্ছি যে, এটা মনে হয় না যে, ছেলেটির হাত উড়িয়ে দিবে না। জঘন্য।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏مَرَّ بِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا أُصَلِّي فَقَالَ ‏ ‏سَلْ ‏ ‏تُعْطَهْ يَا ‏ ‏ابْنَ أُمِّ عَبْدٍ ‏ ‏فَابْتَدَرَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏عُمَرُ ‏ ‏مَا بَادَرَنِي ‏ ‏أَبُو بَكْرٍ ‏ ‏إِلَى شَيْءٍ إِلَّا سَبَقَنِي إِلَيْهِ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَسَأَلَاهُ عَنْ قَوْلِهِ فَقَالَ مِنْ دُعَائِي الَّذِي لَا أَكَادُ أَدَعُ ‏ ‏اللَّهُمَّ إِنِّي أَسْأَلُكَ نَعِيمًا لَا ‏ ‏يَبِيدُ ‏ ‏وَقُرَّةَ عَيْنٍ لَا ‏ ‏تَنْفَدُ ‏ ‏وَمُرَافَقَةَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُحَمَّدٍ ‏ ‏فِي أَعْلَى الْجَنَّةِ جَنَّةِ الْخُلْدِ ‏","","",""],[3481,3481,"","আমার কথা শোন আমি সালমানের কথা শুনেছি আমি তার কথা শুনেছি আর আমি শুনেছি যে সে বলছে তাকে আত্মসমর্পণ করতে হবে, ঈশ্বরের উচিত আমাকে ছেড়ে দেওয়া এবং তাকে অস্বীকার করা। ঈশ্বর তোমাকে রক্ষা করুন.","‏ ‏سَمِعْت ‏ ‏يَحْيَى ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْدَ بْنَ وَهْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكُمْ سَتَرَوْنَ بَعْدِي ‏ ‏أَثَرَةً ‏ ‏وَأُمُورًا تُنْكِرُونَهَا قَالَ قُلْنَا وَمَا تَأْمُرُنَا قَالَ ‏ ‏أَدُّوا إِلَيْهِمْ حَقَّهُمْ وَسَلُوا اللَّهَ حَقَّكُمْ ‏","","",""],[3482,3482,"","আমরা ভালো ছেলের চেয়ে ভালো একজন ছেলের সঙ্গে কথা বলেছিলাম । আল্লাহ্‌ আর ঈশ্বর বিশ্বাস করতে হবে এটা বিশ্বাস করতে। তিনি আপনাকে এমন একজন ব্যক্তি দিয়েছেন যিনি ঈশ্বরের বন্ধু ছিলেন এবং বললেন যে আমি শুনেছি ঈশ্বর এসেছেন। তিনি এই কথাটি জেনেই আছেন।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ فِي الْمَسْجِدِ فَجِئْنَا نَمْشِي مَعَ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏فَلَمَّا رَكَعَ النَّاسُ رَكَعَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَرَكَعْنَا مَعَهُ وَنَحْنُ نَمْشِي فَمَرَّ رَجُلٌ بَيْنَ يَدَيْهِ فَقَالَ السَّلَامُ عَلَيْكَ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَهُوَ رَاكِعٌ صَدَقَ اللَّهُ وَرَسُولُهُ فَلَمَّا انْصَرَفَ سَأَلَهُ بَعْضُ الْقَوْمِ لِمَ قُلْتَ حِينَ سَلَّمَ عَلَيْكَ الرَّجُلُ صَدَقَ اللَّهُ وَرَسُولُهُ قَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ مِنْ أَشْرَاطِ السَّاعَةِ إِذَا كَانَتْ التَّحِيَّةُ عَلَى الْمَعْرِفَةِ ‏","","",""],[3483,3483,"","আমরা তোমাকে কতবার বলেছিলাম, সে লর্ডের দয়াকে ধরতে পারেনি, সে তার ইচ্ছার কাছে আত্মসমর্পণ করবে। আমি কবর দেওয়া প্রাচীরগুলো দিয়াছি, যাহারা প্রভুর সাথে ভাগ করে না, তাহাদিগকে ক্ষমা করিব । তার মায়ের.","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكُ بْنُ مِغْوَلٍ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ بْنِ عَدِيٍّ ‏ ‏عَنْ ‏ ‏طَلْحَةَ ‏ ‏عَنْ ‏ ‏مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا ‏ ‏أُسْرِيَ ‏ ‏بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْتُهِيَ بِهِ إِلَى سِدْرَةِ الْمُنْتَهَى وَهِيَ فِي السَّمَاءِ السَّادِسَةِ إِلَيْهَا يُنْتَهَ مَا ‏ ‏يُعْرَجُ ‏ ‏بِهِ مِنْ الْأَرْضِ فَيُقْبَضُ مِنْهَا وَإِلَيْهَا يُنْتَهَ مَا يُهْبَطُ بِهِ مِنْ فَوْقِهَا فَيُقْبَضُ مِنْهَا قَالَ ‏ { ‏إِذْ ‏ ‏يَغْشَى ‏ ‏السِّدْرَةَ مَا ‏ ‏يَغْشَى ‏ } ‏قَالَ فِرَاشٌ مِنْ ذَهَبٍ قَالَ ‏ ‏فَأُعْطِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثًا وَأُعْطِيَ الصَّلَوَاتِ الْخَمْسَ وَأُعْطِيَ خَوَاتِيمَ سُورَةِ ‏ ‏الْبَقَرَةِ ‏ ‏وَغُفِرَ لِمَنْ لَا يُشْرِكُ بِاللَّهِ مِنْ أُمَّتِهِ شَيْئًا ‏ ‏الْمُقْحِمَاتُ ‏","","",""],[3484,3484,"","আমরা একটা ছেলের কথা বলেছিলাম... ...আমাদের রাতে রাতে ঘুমাতে হতো, ঈশ্বর তাকে আমার মায়ের কাছ থেকে ল্যাডারে নিয়ে যেতে বলেছেন.","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏زَاذَانَ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِلَّهِ مَلَائِكَةً فِي الْأَرْضِ ‏ ‏سَيَّاحِينَ ‏ ‏يُبَلِّغُونِي مِنْ أُمَّتِي السَّلَامَ ‏","","",""],[3485,3485,"","আমরা এমন একজন ভাইয়ের সঙ্গে বাস করার কথা বলেছিলাম, যিনি হয়তো ঈশ্বরের কাছে বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْجَنَّةُ أَقْرَبُ إِلَى أَحَدِكُمْ مِنْ ‏ ‏شِرَاكِ ‏ ‏نَعْلِهِ وَالنَّارُ مِثْلُ ذَلِكَ ‏","","",""],[3486,3486,"","আমরা হয়তো আল্লাহ্‌র সাথে কথা বলেছি, তিনি ঈশ্বরের কাছে এসেছেন।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُبَاشِرْ الْمَرْأَةُ الْمَرْأَةَ ‏ ‏لِتَنْعَتَهَا ‏ ‏لِزَوْجِهَا كَأَنَّهُ يَنْظُرُ إِلَيْهَا ‏","","",""],[3487,3487,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং যারা পাপের সবচেয়ে ভয় পায়, তাদের কাছে আত্মসমর্পণ করবেন । একটা যায় আর সিলভার অপরাধ থেকে বাঁচার প্রয়োজনীয়তাকে উদ্বুদ্ধ করতে পারে না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ قَيْسٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَابِعُوا بَيْنَ الْحَجِّ وَالْعُمْرَةِ فَإِنَّهُمَا يَنْفِيَانِ الْفَقْرَ وَالذُّنُوبَ كَمَا يَنْفِي ‏ ‏الْكِيرُ ‏ ‏خَبَثَ ‏ ‏الْحَدِيدِ وَالذَّهَبِ وَالْفِضَّةِ وَلَيْسَ لِلْحَجَّةِ الْمَبْرُورَةِ ‏ ‏ثَوَابٌ ‏ ‏دُونَ الْجَنَّةِ ‏","","",""],[3488,3488,"","ঈশ্বর হয়তো বলেছিলেন যে, তিনি তার শান্তি বজায় রেখেছিলেন এবং এরপর তাকে ফিরিয়ে দিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ الْحَفَرِيُّ عُمَرُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُهَاجِرٍ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ الْبَطِينِ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ تَغَيَّرَ وَجْهُهُ ثُمَّ قَالَ ‏ ‏نَحْوًا مِنْ ذَا ‏ ‏أَوْ قَرِيبًا مِنْ ذَا ‏","","",""],[3489,3489,"","আমরা একটা দাসের সাথে কথা বলেছি, কিন্তু সকালে জয়ে তিনি ঈশ্বরের কাছে অনুরোধ করেছেন যেন তিনি তা করতে এবং আত্মসমর্পণ করতে পারেন। ঈশ্বর আমাদের প্রার্থনা করেছেন মাথা নত করতে, আর তার প্রশংসা করতে। তিনি চিন্তা করতে বলেছেন কিন্তু তার কাছে থাকার কথা না বলতে। আর মৃত্যু ও রক্ত ফুলকে স্মরণ না করে, ঈশ্বর বেঁচে থাকার জন্য জয়ী হয়েছেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الصَّبَّاحِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏مُرَّةَ الْهَمْدَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ اسْتَحْيُوا مِنْ اللَّهِ عَزَّ وَجَلَّ حَقَّ الْحَيَاءِ قَالَ قُلْنَا يَا رَسُولَ اللَّهِ إِنَّا نَسْتَحِي وَالْحَمْدُ لِلَّهِ قَالَ لَيْسَ ذَلِكَ وَلَكِنْ ‏ ‏مَنْ اسْتَحَى مِنْ اللَّهِ حَقَّ الْحَيَاءِ فَلْيَحْفَظْ الرَّأْسَ وَمَا ‏ ‏حَوَى ‏ ‏وَلْيَحْفَظْ الْبَطْنَ وَمَا ‏ ‏وَعَى ‏ ‏وَلْيَذْكُرْ الْمَوْتَ ‏ ‏وَالْبِلَى ‏ ‏وَمَنْ أَرَادَ الْآخِرَةَ تَرَكَ زِينَةَ الدُّنْيَا فَمَنْ فَعَلَ ذَلِكَ فَقَدْ اسْتَحْيَا مِنْ اللَّهِ عَزَّ وَجَلَّ حَقَّ الْحَيَاءِ ‏","","",""],[3490,3490,"","আমরা একটা দাসের সাথে কথা বলেছি, কিন্তু সকালে জয় করছি। আমি তোমাকে তোমার সেরাটা দেব। ঈশ্বর খুশি হবেন আর তার ঋণ দেন যাকে আমি ভালোবাসি তার কাছে যেতে পারি আর আমি ভালোবাসি তা না করতে। মিথ্যা কথা বলতে, তার ভাগ্য নিশ্চিত না হওয়া পর্যন্ত এটা দেয়া যাবে না, ঈশ্বর তাকে ধোঁকা দিয়েছেন আর আপনার আত্মার হত্যার কারণ হতে দেবেন না। সে শুধু খারাপের দিকে যাচ্ছে, খবর ভয় পেতে চায় না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الصَّبَّاحِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏مُرَّةَ الْهَمْدَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ قَسَمَ بَيْنَكُمْ أَخْلَاقَكُمْ كَمَا قَسَمَ بَيْنَكُمْ أَرْزَاقَكُمْ وَإِنَّ اللَّهَ عَزَّ وَجَلَّ يُعْطِي الدُّنْيَا مَنْ يُحِبُّ وَمَنْ لَا يُحِبُّ وَلَا يُعْطِي الدِّينَ إِلَّا لِمَنْ أَحَبَّ فَمَنْ أَعْطَاهُ اللَّهُ الدِّينَ فَقَدْ أَحَبَّهُ وَالَّذِي نَفْسِي بِيَدِهِ لَا يُسْلِمُ عَبْدٌ حَتَّى يَسْلَمَ قَلْبُهُ وَلِسَانُهُ وَلَا يُؤْمِنُ حَتَّى يَأْمَنَ جَارُهُ ‏ ‏بَوَائِقَهُ ‏ ‏قَالُوا وَمَا ‏ ‏بَوَائِقُهُ ‏ ‏يَا نَبِيَّ اللَّهِ قَالَ ‏ ‏غَشْمُهُ ‏ ‏وَظُلْمُهُ وَلَا يَكْسِبُ عَبْدٌ مَالًا مِنْ حَرَامٍ فَيُنْفِقَ مِنْهُ فَيُبَارَكَ لَهُ فِيهِ وَلَا يَتَصَدَّقُ بِهِ فَيُقْبَلَ مِنْهُ وَلَا يَتْرُكُ خَلْفَ ظَهْرِهِ إِلَّا كَانَ ‏ ‏زَادَهُ ‏ ‏إِلَى النَّارِ إِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يَمْحُو السَّيِّئَ بِالسَّيِّئِ وَلَكِنْ يَمْحُو السَّيِّئَ بِالْحَسَنِ إِنَّ ‏ ‏الْخَبِيثَ ‏ ‏لَا يَمْحُو ‏ ‏الْخَبِيث ‏","","",""],[3491,3491,"","আমরা সেই বধিরদের কথা বলেছিলাম কিন্তু আমার ভালবাসার কথা ছিল। আমি ঈশ্বরের কাছে প্রার্থনা করেছি, তিনি তার জন্য প্রার্থনা করেছেন এবং যদি তিনি তিন রাত থাকেন তাহলে আল্লাহ্‌র কাছে আত্মসমর্পণ করবেন। তুমি দরজা খুলে দিলে আর পরে চলে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ الْهَمْدَانِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ ثُلُثُ اللَّيْلِ الْبَاقِي يَهْبِطُ اللَّهُ عَزَّ وَجَلَّ إِلَى السَّمَاءِ الدُّنْيَا ثُمَّ تُفْتَحُ أَبْوَابُ السَّمَاءِ ثُمَّ يَبْسُطُ يَدَهُ فَيَقُولُ هَلْ مِنْ سَائِلٍ يُعْطَى سُؤْلَهُ فَلَا يَزَالُ كَذَلِكَ حَتَّى يَطْلُعَ الْفَجْرُ ‏","","",""],[3492,3492,"","আমরা এমন একজন দাসের কথা বলেছিলাম যে ঈশ্বরের সাথে কথা বলেছিল সে প্রথম জিনিস বদলে দিবে যেটা মানুষের রক্তে মারা যাবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوَّلُ مَا ‏ ‏يُقْضَى بَيْنَ النَّاسِ يَوْمَ الْقِيَامَةِ فِي الدِّمَاءِ ‏","","",""],[3493,3493,"","ঈশ্বরের ভালোর জন্য আমরা ইতোমধ্যে দু'জন জীবন কাজ করেছি। আল্লাহ তার কাছে প্রার্থনা করেছেন, তাকে উদ্ধার করতে হবে। কে তাকে জিজ্ঞেস করবে সে কি গান গাইতে যাচ্ছে। তার মুখ বলল, \"ঈশ্বর, সে যা গান গেয়ে, \"তারা চলে যাবে.\"","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَأَلَ وَلَهُ مَا يُغْنِيهِ جَاءَتْ يَوْمَ الْقِيَامَةِ خُدُوشًا ‏ ‏أَوْ ‏ ‏كُدُوشًا ‏ ‏فِي وَجْهِهِ قَالُوا يَا رَسُولَ اللَّهِ وَمَا غِنَاهُ قَالَ خَمْسُونَ دِرْهَمًا وَحِسَابُهَا مِنْ الذَّهَبِ ‏","","",""],[3494,3494,"","আমরা বাবার ঘোড়ার চেয়েও বেশি মার খাওয়ার কথা বলেছি... ...একজন সম্মানিত ব্যক্তির হাতে ধরা পড়ার জন্য, ঈশ্বরের ইচ্ছা হল সে পৌঁছে গেছে, আর সে পানিতে তোমার বিষ কিনতে পারবে না। এটা ডুবে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ السَّمَّاكِ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنِ ‏ ‏الْمُسَيَّبِ بْنِ رَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَشْتَرُوا السَّمَكَ فِي الْمَاءِ فَإِنَّهُ ‏ ‏غَرَرٌ ‏","","",""],[3495,3495,"","আমরা একজন ভাইয়ের ছেলের কথা বলেছিলাম, আমার বাবার ভালবাসার ব্যাপারে বিদ্রোহীরা প্রার্থনা করেছে, আর আল্লাহ তাঁর জন্য প্রার্থনা করেছে যে ঈশ্বর জিতে গেছেন আর তিনি আমার হাত থেকে ভালো কিছু পেতে চান। তুমি তোমার ভূট্টা থেকে আগুন নিয়ে এসেছ... ...কীভাবে সে বলেছে তার সব কামনার পেছনে আছে, লর্ড, তুমি কি জানো আমি আসলে কী মানুষ? তাদের একজন শিক্ষক হিসেবে বলা হয়েছে আমার বাবা তার সাথে গেছে","‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ مُحَمَّدٍ ‏ ‏ابْنُ أُخْتِ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يَبْعَثُ يَوْمَ الْقِيَامَةِ مُنَادِيًا يُنَادِي يَا ‏ ‏آدَمُ ‏ ‏إِنَّ اللَّهَ يَأْمُرُكَ أَنْ تَبْعَثَ بَعْثًا مِنْ ذُرِّيَّتِكَ إِلَى النَّارِ فَيَقُولُ ‏ ‏آدَمُ ‏ ‏يَا رَبِّ وَمِنْ كَمْ قَالَ فَيُقَالُ لَهُ مِنْ كُلِّ مِائَةٍ تِسْعَةً وَتِسْعِينَ فَقَالَ رَجُلٌ مِنْ الْقَوْمِ مَنْ هَذَا النَّاجِي مِنَّا بَعْدَ هَذَا يَا رَسُولَ اللَّهِ قَالَ ‏ ‏هَلْ تَدْرُونَ مَا أَنْتُمْ فِي النَّاسِ إِلَّا ‏ ‏كَالشَّامَةِ ‏ ‏فِي صَدْرِ الْبَعِيرِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُسْلِمٍ أَبِي إِسْحَاقَ الْهَجَرِيِّ ‏ ‏فَذَكَرَ مَعْنَاهُ وَقَالَ فَيَقُولُ ‏ ‏آدَمُ ‏ ‏يَا رَبِّ كَمْ أَبْعَثُ ‏","","",""],[3496,3496,"","আমরা ছেলে সম্পর্কে কথা বলেছিলাম যে আমার বাবা কি বলেছে, সে তোমাকে দিয়ে দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيَتَّقِ أَحَدُكُمْ وَجْهَهُ النَّارَ وَلَوْ ‏ ‏بِشِقِّ ‏ ‏تَمْرَةٍ ‏","","",""],[3497,3497,"","আমরা কথা বলেছিলাম, ছেলে জোর করে আমার বাবাকে আক্রমণ করতে বাধ্য হচ্ছে। যদি তোমাদের কেউ তার উদ্দেশ্য নিয়ে আসে, সে তার পরিকল্পনা নিয়ে শুরু করবে।","‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏الْهَجَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَاءَ خَادِمُ أَحَدِكُمْ بِطَعَامِهِ فَلْيَبْدَأْ بِهِ فَلْيُطْعِمْهُ أَوْ لِيُجْلِسْهُ مَعَهُ فَإِنَّهُ ‏ ‏وَلِيَ ‏ ‏حَرَّهُ ‏ ‏وَدُخَانَهُ ‏","","",""],[3498,3498,"","আমরা ইতোমধ্যে বেন আলবাইর রাজধানী সম্পর্কে দুই মাস কথা বলেছি প্রভুর মঙ্গলের জন্য আমি প্রার্থনা করছি না, আমি আদেশ পালন করছি না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ كُلَيْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏أَلَا أُصَلِّي لَكُمْ صَلَاةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَصَلَّى فَلَمْ يَرْفَعْ يَدَيْهِ إِلَّا مَرَّةً ‏","","",""],[3499,3499,"","আমরা অনেক বছর ধরে আমার বাবার অনুসন্ধানের কথা বলেছি, যে কিনা অনেক দূরে চলে গেছে। সে তার মরণশীলদের খুঁজে বের করবে, যারা কখনো পালায় নি। সে বলল, ঈশ্বর পালিয়ে যাওয়ার পর তাকে মেরে ফেলার পর.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَجَدَ ‏ ‏بِالنَّجْمِ ‏ ‏وَسَجَدَ الْمُسْلِمُونَ إِلَّا رَجُلًا مِنْ ‏ ‏قُرَيْشٍ ‏ ‏أَخَذَ كَفًّا مِنْ تُرَابٍ فَرَفَعَهُ إِلَى جَبْهَتِهِ فَسَجَدَ عَلَيْهِ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَرَأَيْتُهُ بَعْدُ قُتِلَ كَافِرًا ‏","","",""],[3500,3500,"","আমরা আমার বাবার গোপন বিষয় নিয়ে কথা বলেছি, ঈশ্বরের কাছে আমার বাবার তদন্ত করার জন্য ঈশ্বর তাকে আত্মসমর্পণ করতে বলেছেন যদি তিনি ঈশ্বরকে গুলি করতে আসেন আর তিনি বলেন যে তিনি এটা পড়তে পারতেন। আর এটা আমার বাবার কাছে গোপন তথ্য ছিল। আমাকে মাফ করে দাও, ৩ বছর বয়সী জমজ ছেলে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا أُنْزِلَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ ‏ ‏كَانَ يُكْثِرُ إِذَا قَرَأَهَا وَرَكَعَ أَنْ يَقُولَ ‏ ‏سُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ اللَّهُمَّ اغْفِرْ لِي إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ ثَلَاثًا ‏","","",""],[3501,3501,"","আমরা অনেক বছর ধরে ঈশ্বরের হাতে কথা বলেছি, যে কিনা তাঁকে উপাসনা করতে পারবে। ঈশ্বর তাকে জবাব দিতে বলেন এবং আত্মসমর্পণ করতে বলেন যদি তুমি ভালবাসা ফিরে আসবে এবং শোনাও। আমি জানি, ঈশ্বরের হাতে অনেক বছর আগে, দুঃখিত।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْنُكَ عَلَيَّ أَنْ تَرْفَعَ الْحِجَابَ وَأَنْ تَسْتَمِعَ ‏ ‏سِوَادِي ‏ ‏حَتَّى ‏ ‏أَنْهَاكَ ‏ ‏سِوَادِي سِرِّي قَالَ أَذِنَ لَهُ أَنْ يَسْمَعَ سِرَّهُ ‏","","",""],[3502,3502,"","আমরা আমার বাবার গোপন বিষয় নিয়ে কথা বলেছি, ঈশ্বর আমার বাবার কাছে আত্মসমর্পণ করেছেন আমাকে হত্যা করার জন্য। তিনি বলেছিলেন, তিনি পাথর মেরে ফেলেছেন। পেছনে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَهَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏خَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِحَاجَتِهِ ‏ ‏فَقَالَ الْتَمِسْ لِي ثَلَاثَةَ أَحْجَارٍ قَالَ فَأَتَيْتُهُ بِحَجَرَيْنِ ‏ ‏وَرَوْثَةٍ ‏ ‏قَالَ ‏ ‏فَأَخَذَ الْحَجَرَيْنِ وَأَلْقَى ‏ ‏الرَّوْثَةَ ‏ ‏وَقَالَ إِنَّهَا ‏ ‏رِكْسٌ ‏","","",""],[3503,3503,"","আমরা তার বাবার সাথে কথা বলেছি বাবা আর খোদাকে দিয়ে। আর সে আমাদের ডিনারের পর পাস করতে পারবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَجْدِبُ ‏ ‏لَنَا ‏ ‏السَّمَرَ ‏ ‏بَعْدَ الْعِشَاءِ ‏","","",""],[3504,3504,"","আমরা গত দুই বছর ধরে আমার জন্য ভালবাসা পাওয়ার জন্য করেছি। তিনি বলেছিলেন, ঈশ্বর তার জন্য প্রার্থনা করবেন এবং আপনার সঙ্গী বা আমাদের কেউ যেন না থাকত।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الطِّيَرَةُ ‏ ‏شِرْكٌ وَمَا مِنَّا إِلَّا وَلَكِنَّ اللَّهَ يُذْهِبُهُ بِالتَّوَكُّلِ ‏","","",""],[3505,3505,"","আমরা কথা বলেছি হয়তো আমাকে থামাতে হবে, ঈশ্বর শহরের পালকের কাছে আত্মসমর্পণ করেছেন এবং প্রভুর কিছু দাবীর কথা বলেছেন। আমি ভেবেছিলাম এটা আমার প্রভুর আদেশ। আর আমি আপনাকে ঈশ্বরের আদেশ থেকে করুণা প্রার্থনা করবো। তাদের মধ্যে কেউ কেউ হয়ত বলবে, কীভাবে তুমি জিজ্ঞেস করতে চাও না। সে.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنْتُ أَمْشِي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏حَرْثٍ ‏ ‏بِالْمَدِينَةِ ‏ ‏وَهُوَ مُتَّكِئٌ عَلَى ‏ ‏عَسِيبٍ ‏ ‏قَالَ فَمَرَّ بِقَوْمٍ مِنْ ‏ ‏الْيَهُودِ ‏ ‏فَقَالَ بَعْضُهُمْ لِبَعْضٍ سَلُوهُ عَنْ الرُّوحِ قَالَ بَعْضُهُمْ لَا تَسْأَلُوهُ فَسَأَلُوهُ عَنْ الرُّوحِ فَقَالُوا يَا ‏ ‏مُحَمَّدُ ‏ ‏مَا الرُّوحُ فَقَامَ فَتَوَكَّأَ عَلَى ‏ ‏الْعَسِيبِ ‏ ‏قَالَ فَظَنَنْتُ أَنَّهُ يُوحَى إِلَيْهِ فَقَالَ ‏ { ‏وَيَسْأَلُونَكَ عَنْ الرُّوحِ قُلْ الرُّوحُ مِنْ أَمْرِ رَبِّي وَمَا أُوتِيتُمْ مِنْ الْعِلْمِ إِلَّا قَلِيلًا ‏} ‏قَالَ فَقَالَ بَعْضُهُمْ قَدْ قُلْنَا لَكُمْ لَا تَسْأَلُوهُ ‏","","",""],[3506,3506,"","আমরা কথা বলেছি কিভাবে আমি ঈশ্বরকে বলতে চেষ্টা করেছি তার জন্য প্রার্থনা করে আর আমি ভুল করে যাব না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا إِنِّي أَبْرَأُ إِلَى كُلِّ ‏ ‏خَلِيلٍ ‏ ‏مِنْ ‏ ‏خُلَّتِهِ ‏ ‏وَلَوْ اتَّخَذْتُ ‏ ‏خَلِيلًا ‏ ‏لَاتَّخَذْتُ ‏ ‏أَبَا بَكْرٍ ‏ ‏خَلِيلًا ‏ ‏إِنَّ صَاحِبَكُمْ ‏ ‏خَلِيلُ ‏ ‏اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[3507,3507,"","আমরা অনেক বছর ধরে প্রভুর বাবার কাছে শপথ নিয়ে কথা বলেছি, ঈশ্বরের ইচ্ছা তার জন্য প্রার্থনা করেছে আর সে আমাকে এটা দেবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُؤْتَى بِالسَّبْيِ ‏ ‏فَيُعْطِي أَهْلَ الْبَيْتِ جَمِيعًا كَرَاهِيَةَ أَنْ يُفَرِّقَ بَيْنهُمْ ‏","","",""],[3508,3508,"","বাবার ভালোবাসা নিয়ে আমার দু'বছরের কথা বলছি, একটা সুন্দর নামে, আমি তাদের কাছে একটা ছেলের মেয়েকে ডেকে বলবো যে কিনা একজন সন্তান নির্বাচিত করেছে। আমরা এক অর্ধবিত্তের মেয়েকে অনুসরণ করব। যখন সে এক সুখী ছেলে, তখন তাকে আমি বলব সে কি বলেছে সে ভালো ছেলে, আমি শুধু তার জন্য প্রার্থনা করব এবং লর্ড প্রভুর অর্ধ-পুরুষের কাছে আত্মসমর্পণ করব। বোন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي قَيْسٍ ‏ ‏عَنِ ‏ ‏الْهُزَيْلِ بْنِ شُرَحْبِيلٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى ‏ ‏أَبِي مُوسَى ‏ ‏وَسُلَيْمَانَ بْنِ رَبِيعَةَ ‏ ‏فَسَأَلَهُمَا عَنْ ابْنَةٍ وَابْنَةِ ابْنٍ وَأُخْتٍ لِأَبٍ فَقَالَا لِلْبِنْتِ النِّصْفُ وَلِلْأُخْتِ النِّصْفُ وَأْتِ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏فَإِنَّهُ سَيُتَابِعُنَا قَالَ فَأَتَى ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏فَسَأَلَهُ وَأَخْبَرَهُ بِمَا قَالَا فَقَالَ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏لَقَدْ ضَلَلْتُ إِذًا وَمَا أَنَا مِنْ الْمُهْتَدِينَ ‏ ‏سَأَقْضِي بِمَا ‏ ‏قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلِابْنَةِ النِّصْفُ وَلِابْنَةِ ‏ ‏الِابْنِ السُّدُسُ تَكْمِلَةَ الثُّلُثَيْنِ وَمَا بَقِيَ فَلِلْأُخْتِ ‏","","",""],[3509,3509,"","আমরা আমার বাবার বাবার ভালবাসার উপর বাবার জয়ের ব্যাপারে কথা বলেছি। থামো আর গান কর।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى ‏ ‏وَالْعِفَّةَ ‏ ‏وَالْغِنَى ‏","","",""],[3510,3510,"","বেনের সাথে দুই মাস পার হওয়ার পর আমি আমার মোটা ছেলের সাথে দুই মাস পার করেছি। সে বাবাকে ক্ষুধার্থ হতে বলে। সে বলল অবশেষে ঈশ্বর যেন তাকে একটা ছেলেকে উদ্ধার করে, যাতে সে জন্ম না হয়। তাদের.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ مُعَاوِيَةَ الدُّهْنِيِّ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ الْأَشْجَعِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنُ سُمَيَّةَ ‏ ‏مَا عُرِضَ عَلَيْهِ أَمْرَانِ قَطُّ إِلَّا اخْتَارَ الْأَرْشَدَ مِنْهُمَا ‏","","",""],[3511,3511,"","আমরা একে অপরের সাহায্য নিয়ে এসেছি। ঈশ্বরের চেয়ে ভালোর জন্য ফিরে আসতে পেরেছি। আমরা প্রার্থনা করেছি, আল্লাহকে উদ্ধার করতে এবং উদ্ধার করতে। আমি হয়ত বলতে পারি, ঈশ্বরই হয়ে গেছেন। আর যারা তোমার মুখ দিয়ে যেতে হবে, সে তার আসন আগুনের হাত থেকে উঠতে শুরু করেছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏جَمَعَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ أَرْبَعُونَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَكُنْتُ مِنْ آخِرِ مَنْ أَتَاهُ فَقَالَ ‏ ‏إِنَّكُمْ مُصِيبُونَ وَمَنْصُورُونَ وَمَفْتُوحٌ لَكُمْ فَمَنْ أَدْرَكَ ذَلِكَ مِنْكُمْ فَلْيَتَّقِ اللَّهَ وَلْيَأْمُرْ بِالْمَعْرُوفِ وَلْيَنْهَ عَنْ الْمُنْكَرِ وَمَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[3512,3512,"","আমরা আমার বাবা আর তার বাবার কথা বলেছি... ...আমি ঈশ্বরের আদর্শের হিরো, আল্লাহ তার কাছে প্রার্থনা করেছেন আর তাকে আত্মসমর্পণ করবেন যে দিনের জন্য তার সাহায্য আসবে অন্ধকার, আমরা বলেছিলাম আমরা মারা যাবো।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا مَعَ ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَأَبِي مُوسَى ‏ ‏فَقَالَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ بَيْنَ يَدَيْ السَّاعَةِ أَيَّامًا يَنْزِلُ فِيهَا الْجَهْلُ وَيُرْفَعُ فِيهَا الْعِلْمُ وَيَكْثُرُ فِيهَا الْهَرْجُ قَالَ قُلْنَا وَمَا الْهَرْجُ قَالَ الْقَتْلُ ‏","","",""],[3513,3513,"","আমরা একে অপরের কথা বলেছি যে বেন বাবার সবচেয়ে ভালো গাড়ি চালানোর জন্য আমার কাছে চেয়েছে। ভুলে যাও, ঈশ্বর দ্রুত চোখ টিপে অথবা লম্বা সময় ধরে চলে আসেন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏بَشِيرُ بْنُ سَلْمَانَ ‏ ‏عَنْ ‏ ‏سَيَّارٍ أَبِي حَمْزَةَ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ نَزَلَ بِهِ حَاجَةٌ فَأَنْزَلَهَا بِالنَّاسِ كَانَ ‏ ‏قَمِنًا ‏ ‏مِنْ أَنْ لَا تَسْهُلَ حَاجَتُهُ وَمَنْ أَنْزَلَهَا بِاللَّهِ آتَاهُ بِرِزْقٍ عَاجِلٍ أَوْ بِمَوْتٍ آجِلٍ ‏","","",""],[3514,3514,"","আমরা ইতিমধ্যে আমার বাবার সাথে দুটো জাহাজ কথা বলেছি... ...যে তোমার টাকা পাওয়ার চেষ্টা করছে... ...সে বলছে যে ঈশ্বর হয়তো এটা পড়ে ফেলেছে, ঈশ্বর তার কাছে প্রার্থনা করেছেন, আর তিনি দুজন গোপন রহস্যের কথা তুলে ধরেন এবং একটা ম্যাচ শিকার করেন। বইয়ের মধ্যে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏خُمَيْرِ بْنِ مَالِكٍ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَرَأْتُ مِنْ ‏ ‏فِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَبْعِينَ سُورَةً ‏ ‏وَزَيْدُ بْنُ ثَابِتٍ ‏ ‏لَهُ ‏ ‏ذُؤَابَةٌ ‏ ‏فِي الْكُتَّابِ ‏","","",""],[3515,3515,"","আমরা একজন অত্যাচারী, বাবা, সুখী মানে হল যে মারা গেছে তার সাথে সময় কাটাতে বলা। দুঃখিত, আমি দুঃখিত, আমি নিশ্চিত আমি এটা ব্যাখ্যা করতে চাই। সে তোমাকে ছেড়ে দিবে আর সে তোমাকে বলবে আমি ঈশ্বরের দোহাই দিয়ে তোমাকে খুন করবো যদি আমরা তোমার ভাগ্য এবং তোমার জন্য লড়াই করতে পারি, আল্লাহ্‌র ইচ্ছা আর গোপন কথা বলে তিনি খুশি হয়েছিলেন যে, পিতা হলেন এক চমৎকার চলচ্চিত্র, যার মাধ্যমে আমি ঈশ্বরের কাছে যাব এবং মুক্তি লাভ করব ।","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ مُحَمَّدٍ أَبُو سَعِيدٍ يَعْنِي الْعَنْقَزِيَّ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏وَأَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏وَحَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏مُخَارِقٍ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏شَهِدْتُ مِنْ ‏ ‏الْمِقْدَادِ ‏ ‏قَالَ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏ابْنِ الْأَسْوَدِ ‏ ‏مَشْهَدًا ‏ ‏لَأَنْ أَكُونَ أَنَا صَاحِبَهُ أَحَبُّ إِلَيَّ مِمَّا ‏ ‏عُدِلَ ‏ ‏بِهِ أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَدْعُو عَلَى الْمُشْرِكِينَ فَقَالَ وَاللَّهِ يَا رَسُولَ اللَّهِ لَا نَقُولُ كَمَا قَالَتْ ‏ ‏بَنُو إِسْرَائِيلَ ‏ ‏لِمُوسَى ‏ { ‏اذْهَبْ أَنْتَ وَرَبُّكَ فَقَاتِلَا إِنَّا هَاهُنَا قَاعِدُونَ ‏} ‏وَلَكِنْ نُقَاتِلُ عَنْ يَمِينِكَ وَعَنْ يَسَارِكَ وَمِنْ بَيْنِ يَدَيْكَ وَمِنْ خَلْفِكَ فَرَأَيْتُ وَجْهَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُشْرِقُ وَسَرَّهُ ذَلِكَ ‏ ‏قَالَ ‏ ‏أَسْوَدُ ‏ ‏فَرَأَيْتُ وَجْهَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُشْرِقُ لِذَلِكَ وَسَرَّهُ ذَلِكَ ‏ ‏قَالَ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشْرَقَ وَجْهُهُ وَسَرَّهُ ذَاكَ ‏","","",""],[3516,3516,"","আমরা অনেক বছর ধরে আমার বাবার অনুসন্ধানের কথা বলেছি... ...যে ঈশ্বরের প্রতি প্রেম আছে, তার অধিকার আছে, তাকে তার জীবন উৎসর্গ করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُسَلِّمُ عَنْ يَمِينِهِ وَعَنْ يَسَارِهِ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ حَتَّى يُرَى بَيَاضُ خَدِّهِ ‏","","",""],[3517,3517,"","আমরা ঈশ্বরের সাহায্যের জন্য কথা বলেছি, ঈশ্বরের সেবায় নিয়োজিত হয়ে... ...আমার মা আমার বাবার মেয়েকে ভালবাসতেন, প্রভু আমার কাছে অর্থ রেখে গেছেন। আমার বাবা, সে বলেছে তার ঈশ্বরের ইচ্ছা ছিল, ভাঙ্গা হৃদয় আর ভাঙ্গা জীবন কোন কিছুর সমাধান করার আগে কখনো খারাপ কিছু হবে না। আমি তোমাকে একটা জিনিস দিব। দ্যা ফক্স বলেছে যে, ঈশ্বর কখনো তাঁর কিছু স্পর্শ করেননি ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ عَبْدِ اللَّهِ الْيَشْكُرِيِّ ‏ ‏عَنْ ‏ ‏الْمَعْرُورِ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَتْ ‏ ‏أُمُّ حَبِيبَةَ ابْنَةُ أَبِي سُفْيَانَ ‏ ‏اللَّهُمَّ أَمْتِعْنِي بِزَوْجِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبِأَبِي ‏ ‏أَبِي سُفْيَانَ ‏ ‏وَبِأَخِي ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكِ سَأَلْتِ اللَّهَ لِآجَالٍ ‏ ‏مَضْرُوبَةٍ ‏ ‏وَأَيَّامٍ مَعْدُودَةٍ وَأَرْزَاقٍ مَقْسُومَةٍ لَنْ يُعَجَّلَ شَيْءٌ قَبْلَ ‏ ‏حِلِّهِ ‏ ‏أَوْ يُؤَخَّرَ شَيْءٌ عَنْ ‏ ‏حِلِّهِ ‏ ‏وَلَوْ كُنْتِ سَأَلْتِ اللَّهَ أَنْ يُعِيذَكِ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ كَانَ أَخْيَرَ ‏ ‏أَوْ أَفْضَلَ ‏ ‏قَالَ وَذُكِرَ عِنْدَهُ الْقِرَدَةُ ‏ ‏قَالَ ‏ ‏مِسْعَرٌ ‏ ‏أُرَاهُ قَالَ وَالْخَنَازِيرُ ‏ ‏إِنَّهُ مِمَّا ‏ ‏مُسِخَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ لَمْ ‏ ‏يَمْسَخْ ‏ ‏شَيْئًا فَيَدَعَ لَهُ نَسْلًا أَوْ ‏ ‏عَاقِبَةً ‏ ‏وَقَدْ كَانَتْ الْقِرَدَةُ ‏ ‏أَوْ الْخَنَازِيرُ ‏ ‏قَبْلَ ذَلِكَ ‏","","",""],[3518,3518,"","আমরা বাবার ব্যাপারে কথা বলেছি, ঈশ্বর তাকে জিজ্ঞেস করেছেন আর তারা তাকে মেরে ফেলবে, আর তাকে একটা উপকার করে দিবে.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ قَوْمًا أَتَوْا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا ‏ ‏صَاحِبٌ لَنَا ‏ ‏يَشْتَكِي ‏ ‏أَنَكْوِيهِ قَالَ فَسَكَتَ ثُمَّ قَالُوا ‏ ‏أَنَكْوِيهِ فَسَكَتَ ثُمَّ قَالَ اكْوُوهُ ‏ ‏وَارْضِفُوهُ ‏ ‏رَضْفًا ‏","","",""],[3519,3519,"","আমরা অনেক বছর ধরে কথা বলেছি আমার বাবার নিষ্ঠুর প্রেম সম্পর্কে জানতে গিয়ে আমি ঈশ্বরের কাছে তার প্রিয় স্বার্থ এবং শান্তি কামনা করতে ভুলে গিয়েছিলাম। তার গাল দেখতে বা দেখতে পাই.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏مَا نَسِيتُ فِيمَا نَسِيتُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُسَلِّمُ عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ حَتَّى يُرَى ‏ ‏أَوْ نَرَى ‏ ‏بَيَاضَ خَدَّيْهِ ‏","","",""],[3520,3520,"","আমরা অনেক বছর আমার বাবা আর প্রভুকে কাজ করার কথা বলেছি... ...তিনি বলেছেন যে তাকে না যেতে বলা উচিৎ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَنْبَغِي لِأَحَدٍ أَنْ يَقُولَ أَنَا خَيْرٌ مِنْ ‏ ‏يُونُسَ بْنِ مَتَّى ‏","","",""],[3521,3521,"","আমরা আমার আস্থার জন্য কথা বলেছি অথবা বাধ্যতা ফিরে আসার সন্দেহের বাইরে। ঈশ্বর হয়তো বলেছিলেন যে, ঈশ্বর তাঁর প্রভুর কাছে প্রার্থনা করেছেন। ঈশ্বরের কাছে নিজেকে উৎসর্গ করার জন্য আমি আপনাকে ছেড়ে দেব না, আমি তার সাহস ছিনিয়ে নেব। আমরা আমার সাথে কথা বলেছি, আমি আল্লাহ্‌র কাছে ক্ষমা প্রার্থনা করছি। আগে কখনো, আমরা খুশি হব... ...আমরা যে সুখী সময় আমরা করেছি, ফিরে যাওয়ার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏الْمَسْعُودِيِّ ‏ ‏عَنْ ‏ ‏عُثْمَانَ الثَقَفِيِّ ‏ ‏أَوْ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏شَكَّ ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنِ ‏ ‏عَبْدَةَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ لَمْ يُحَرِّمْ حُرْمَةً إِلَّا وَقَدْ عَلِمَ أَنَّهُ سَيَطَّلِعُهَا مِنْكُمْ مُطَّلِعٌ أَلَا وَإِنِّي آخِذٌ ‏ ‏بِحُجَزِكُمْ ‏ ‏أَنْ تَهَافَتُوا فِي النَّارِ كَتَهَافُتِ الْفَرَاشِ أَوْ الذُّبَابِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَطَنٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَبْدَةَ النَّهْدِيِّ ‏ ‏فَذَكَرَهُ ‏ ‏وَكَذَا ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏وَأَبَو كَامِلٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏وَقَالَ الْفَرَاشِ أَوْ الذُّبَابِ ‏","","",""],[3522,3522,"","আমরা একজন যাজকের কথা বলেছি যে তার বাবা-মা'র কাছে ফিরে যাবে, আমরা তখন সবাই বৃদ্ধ হয়ে যাবো, আমরা বাচ্চা হয়ে যাবো আর আমরা এটা নিয়ে চিন্তা করতে পারি না।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نَغْزُو مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ شَبَابٌ وَلَيْسَ لَنَا نِسَاءٌ فَقُلْنَا يَا رَسُولَ اللَّهِ أَلَا ‏ ‏نَسْتَخْصِي ‏ ‏فَنَهَانَا عَنْ ذَلِكَ ‏","","",""],[3523,3523,"","আমরা আবার ঘুমাতে যাওয়ার কথা বলেছি, কিন্তু আমি জিতব, ঈশ্বর হয়ত তার জন্য প্রার্থনা করেছেন এবং ঘোষণা দিয়েছেন যে নারী পতাকা সরিয়ে ফেলতে হবে। দুই বার যদি তারা চলে যায় তাহলে চলে যাবে। তুমি কে আর তুমি যদি এক বছরের ঋণ নাও তাহলে সেটা তোমার জন্য খারাপ হবে.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏الْعَوَّامُ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو إِسْحَاقَ الشَّيْبَانِيُّ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَدُورُ ‏ ‏رَحَى ‏ ‏الْإِسْلَامِ عَلَى رَأْسِ خَمْسٍ وَثَلَاثِينَ أَوْ سِتٍّ وَثَلَاثِينَ أَوْ سَبْعٍ وَثَلَاثِينَ فَإِنْ هَلَكُوا فَسَبِيلُ مَنْ هَلَكَ وَإِنْ بَقُوا ‏ ‏يَقُمْ ‏ ‏لَهُمْ دِينُهُمْ سَبْعِينَ سَنَةً ‏","","",""],[3524,3524,"","আমরা আমার বাবার কথা বলেছি যে হয়তোবা ঈশ্বর হয়তো মারা গেছেন... ...তাহলে নবী তাঁর জন্য প্রার্থনা করেছেন। আমি তাঁর জন্য প্রার্থনা করছি এবং আমি সাক্ষ্য দিতে পারি যে, আমি সেই সাক ্ ষী, যে সাক্ষ্য দিতেছি, সে সাক্ষ্য দিতে পারি, যে আমাকে সাক্ষী হতে হবে, আমি সে বিষয়ে আমি ভুলে যাব, যে আমাকে ভুলিয়া যাইতে পারে না সে-ই হবে যে , যে ব ্ যক ্ তি হবে , যে ব ্ যক ্ তি তার জন ্ যে উত ্ তম হবে । সে এমন একজন যে রাজা হবে... ...যে তোমাকে আলিঙ্গন করবে. এখন এটা.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏حَدَّثَنِي ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَيْثُ قُتِلَ ‏ ‏ابْنُ النَّوَّاحَةِ ‏ ‏إِنَّ هَذَا ‏ ‏وَابْنَ أُثَالٍ ‏ ‏كَانَا أَتَيَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَسُولَيْنِ ‏ ‏لمُسَيْلِمَةَ الْكَذَّابِ ‏ ‏فَقَالَ لَهُمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَشْهَدَانِ أَنِّي رَسُولُ اللَّهِ قَالَا نَشْهَدُ أَنَّ ‏ ‏مُسَيْلِمَةَ ‏ ‏رَسُولُ اللَّهِ فَقَالَ لَوْ كُنْتُ قَاتِلًا رَسُولًا لَضَرَبْتُ أَعْنَاقَكُمَا قَالَ فَجَرَتْ سُنَّةً أَنْ لَا يُقْتَلَ الرَّسُولُ فَأَمَّا ‏ ‏ابْنُ أُثَالٍ ‏ ‏فَكَفَانَاهُ ‏ ‏اللَّهُ عَزَّ وَجَلَّ وَأَمَّا هَذَا فَلَمْ يَزَلْ ذَلِكَ فِيهِ حَتَّى أَمْكَنَ اللَّهُ مِنْهُ الْآنَ ‏","","",""],[3525,3525,"","তিনি ঈশ্বরের কাছে প্রার্থনা করতে চান আর এমন একটা ছেলেকে দেবেন, যে তার জিনগত ভাগ্যকে প্রভাবিত করেছে । আমাদের বাবামা আমার মতো এবং একজন বোকা ড্রাগনের মতো ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ النَّخَعِيِّ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏اضْطَجَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى حَصِيرٍ ‏ ‏فَأَثَّرَ ‏ ‏فِي جَنْبِهِ فَلَمَّا اسْتَيْقَظَ جَعَلْتُ أَمْسَحُ جَنْبَهُ فَقُلْتُ يَا رَسُولَ اللَّهِ أَلَا آذَنْتَنَا حَتَّى نَبْسُطَ لَكَ عَلَى الْحَصِيرِ شَيْئًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا لِي وَلِلدُّنْيَا مَا أَنَا وَالدُّنْيَا إِنَّمَا مَثَلِي وَمَثَلُ الدُّنْيَا كَرَاكِبٍ ظَلَّ تَحْتَ شَجَرَةٍ ثُمَّ رَاحَ وَتَرَكَهَا ‏","","",""],[3526,3526,"","আমরা আমার ছেলেকে ভালোবাসার চেয়ে কঠিন সময়ের সাথে একত্রিত হওয়ার চেয়ে ভাল কথা বলেছি। ঈশ্বর আমাদের সাহায্য করেছেন। কেন আমরা লর্ডের কষ্ট থেকে বরখাস্ত হব? আজ রাতে তার কাছে প্রার্থনা করলাম, আমি এমনকি একবার বলেছি আমরা ফিরে যাবো যখন তিনি বলেছিলেন যে আমি কখনও বলিনি যে, যে সকালে আল্লাহ আমাকে বললেন যে, আমি তার কাছে প্রার্থনা করব। তুমি অন্ধকারে ঘুমাবে, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি যখন আলো থেকে উদ্ধার করেছেন এবং তারপর তিনি তার তৈরি করেছেন, ঈশ্বর ঘুমাবে না যদি আপনি ফিরে আসতে চান তাহলে আমরা ফিরে আসবো। ঘুমোও, ঈশ্বরের দয়া তাঁর জন্য প্রার্থনা করছে, আর সে আত্মসমর্পণ করবে এবং যারা তার ভাঁজে বের হয়ে গেছে তাদের আদেশ ভঙ্গ করবে, ঈশ্বর তাকে আত্মসমর্পণ করতে বলেছেন। ঈশ্বর আপনাকে এমন একটা লড়াই করার জন্য তার আনুগত্য খুঁজে পেতে বলেছেন, যা তার রয়েছে । ঈশ্বরের দোহাই খোলা দেয়ালের কাছে তার ইচ্ছার কথা বলেছে আমরা আপনার জন্য অনেক খোলা","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏جَامِعِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي عَلْقَمَةَ الثَّقَفِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏لَمَّا انْصَرَفْنَا مِنْ ‏ ‏غَزْوَةِ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ يَحْرُسُنَا اللَّيْلَةَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَقُلْتُ أَنَا حَتَّى عَادَ مِرَارًا قُلْتُ أَنَا يَا رَسُولَ اللَّهِ قَالَ فَأَنْتَ إِذًا قَالَ فَحَرَسْتُهُمْ حَتَّى إِذَا كَانَ وَجْهُ الصُّبْحِ أَدْرَكَنِي قَوْلُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكَ تَنَامُ فَنِمْتُ فَمَا أَيْقَظَنَا إِلَّا حَرُّ الشَّمْسِ فِي ظُهُورِنَا فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَصَنَعَ كَمَا كَانَ يَصْنَعُ مِنْ الْوُضُوءِ وَرَكْعَتَيْ الْفَجْرِ ثُمَّ صَلَّى بِنَا الصُّبْحَ فَلَمَّا انْصَرَفَ قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَوْ أَرَادَ أَنْ لَا تَنَامُوا لَمْ تَنَامُوا وَلَكِنْ أَرَادَ أَنْ تَكُونُوا لِمَنْ بَعْدَكُمْ فَهَكَذَا لِمَنْ نَامَ أَوْ نَسِيَ قَالَ ثُمَّ إِنَّ نَاقَةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِبِلَ الْقَوْمِ تَفَرَّقَتْ فَخَرَجَ النَّاسُ فِي طَلَبِهَا فَجَاءُوا بِإِبِلِهِمْ إِلَّا نَاقَةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُذْ هَهُنَا فَأَخَذْتُ حَيْثُ قَالَ لِي فَوَجَدْتُ ‏ ‏زِمَامَهَا ‏ ‏قَدْ الْتَوَى عَلَى شَجَرَةٍ مَا كَانَتْ لِتَحُلَّهَا إِلَّا يَدٌ قَالَ فَجِئْتُ بِهَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ وَالَّذِي بَعَثَكَ بِالْحَقِّ نَبِيًّا لَقَدْ وَجَدْتُ ‏ ‏زِمَامَهَا ‏ ‏مُلْتَوِيًا عَلَى شَجَرَةٍ مَا كَانَتْ لِتَحُلَّهَا إِلَّا يَدٌ قَالَ وَنَزَلَتْ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُورَةُ ‏ ‏الْفَتْحِ ‏ { ‏إِنَّا فَتَحْنَا لَكَ فَتْحًا مُبِينًا ‏}","","",""],[3527,3527,"","আমরা আমাদের বাবার প্রান্তরে ফিরে যেতে বলা অনেক বেশি কথা বলেছি। একজন ভাই বলেছেন যে, এই আমার ভাইয়ের ছেলে যে কিনা হয়তো ঈশ্বরের হাতে নিহত হয়েছে। তোমাদের উদ্দেশ্য পরিবর্তন করে ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তাঁর কাছে ফিরে আসবেন। আপনি ঈশ্বরের অনুগ্রহ এবং ঈশ্বরের অনুগ্রহের জন্য ক্ষমা প্রার্থনা করতে চান।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الْحَارِثِ الْجَابِرِ ‏ ‏عَنْ ‏ ‏أَبِي مَاجِدٍ ‏ ‏قَالَ ‏ ‏أَتَى رَجُلٌ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏بِابْنِ أَخٍ لَهُ فَقَالَ إِنَّ هَذَا ابْنُ أَخِي وَقَدْ شَرِبَ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏لَقَدْ عَلِمْتُ أَوَّلَ ‏ ‏حَدٍّ ‏ ‏كَانَ فِي الْإِسْلَامِ امْرَأَةٌ سَرَقَتْ فَقُطِعَتْ يَدُهَا فَتَغَيَّرَ لِذَلِكَ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَغَيُّرًا شَدِيدًا ثُمَّ قَالَ ‏ { ‏وَلْيَعْفُوا وَلْيَصْفَحُوا أَلَا تُحِبُّونَ أَنْ يَغْفِرَ اللَّهُ لَكُمْ وَاللَّهُ غَفُورٌ رَحِيمٌ ‏}","","",""],[3528,3528,"","আমরা লর্ডের কাছে আরো ভাল কিছু বলার চেষ্টা করেছি, ঈশ্বর বলেছেন, ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং আমি যা করেছি তার কাছে তার কাছে আত্মসমর্পণ করেছি। তোমার মায়ের নাম তোমার অতীতের। বিচার, তোমার নিজের বা আমি তোমার বইতে আছি, নয়তো তুমি এটা তোমার বিজ্ঞানের মধ্যে খুঁজে পাবে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏فُضَيْلُ بْنُ مَرْزُوقٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْجُهَنِيُّ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَصَابَ أَحَدًا قَطُّ هَمٌّ وَلَا حَزَنٌ فَقَالَ ‏ ‏اللَّهُمَّ إِنِّي عَبْدُكَ وَابْنُ عَبْدِكَ وَابْنُ أَمَتِكَ ‏ ‏نَاصِيَتِي ‏ ‏بِيَدِكَ مَاضٍ فِيَّ حُكْمُكَ عَدْلٌ فِيَّ قَضَاؤُكَ أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ سَمَّيْتَ بِهِ نَفْسَكَ أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ أَوْ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي وَنُورَ صَدْرِي وَجِلَاءَ حُزْنِي وَذَهَابَ هَمِّي إِلَّا أَذْهَبَ اللَّهُ هَمَّهُ وَحُزْنَهُ وَأَبْدَلَهُ مَكَانَهُ فَرَجًا قَالَ فَقِيلَ يَا رَسُولَ اللَّهِ أَلَا نَتَعَلَّمُهَا فَقَالَ بَلَى يَنْبَغِي لِمَنْ سَمِعَهَا أَنْ يَتَعَلَّمَهَا ‏","","",""],[3529,3529,"","আমরা তোমার ক্রেতার ব্যাপারে কথা বলেছি কিন্তু ঈশ্বরের কাছে আমার বাবার সাথে কথা আছে, আর সে আমার দৃষ্টিতে যা করেছে তার জন্য সে নিজেকে আত্মসমর্পণ করেছে. এমনকি আমরা যদি তাঁর হাতে শ্বাস নিই, তা হলে সেগুলো সত্যের জন্য তাদেরকে ফাঁস করে দেওয়া হবে ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏شَرِيكُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ بَذِيمَةَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا وَقَعَتْ ‏ ‏بَنُو إِسْرَائِيلَ ‏ ‏فِي الْمَعَاصِي نَهَتْهُمْ عُلَمَاؤُهُمْ فَلَمْ يَنْتَهُوا فَجَالَسُوهُمْ فِي مَجَالِسِهِمْ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏أَحْسِبُهُ قَالَ وَأَسْوَاقِهِمْ ‏ ‏وَوَاكَلُوهُمْ وَشَارَبُوهُمْ فَضَرَبَ اللَّهُ قُلُوبَ بَعْضِهِمْ بِبَعْضٍ وَلَعَنَهُمْ عَلَى لِسَانِ ‏ ‏دَاوُدَ ‏ ‏وَعِيسَى ابْنِ مَرْيَمَ ‏ { ‏ذَلِكَ بِمَا عَصَوْا وَكَانُوا يَعْتَدُونَ ‏} ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُتَّكِئًا فَجَلَسَ فَقَالَ لَا وَالَّذِي نَفْسِي بِيَدِهِ حَتَّى ‏ ‏تَأْطُرُوهُمْ ‏ ‏عَلَى الْحَقِّ ‏ ‏أَطْرًا ‏","","",""],[3530,3530,"","আমরা হামাদ বি কে বলেছি তোমার টাকা ভুলে যেতে আমার ছেলের আস্থা খুঁজে পেতে, সৃষ্টিকর্তা তার জন্য প্রার্থনা করেছেন এবং শেষ ব্যক্তি যে প্রবেশ করেছে তার কাছে সমর্পণ করবেন। সকালে থাকে, একবারই যখন তুমি তাকে আগুনে পুড়িয়ে ফেলবে, যদি শিকারীরা তার সাথে লড়াই করবে, বলে তুমি তোমার ছেলে না। আমি তাকে বলব সে আসবে না। ঈশ্বর তাকে জিজ্ঞেস করবেন যে, সে কি করবে। আমি মনে করি এটা তার চেয়ে ভালো হবে, লর্ড। আমি তাকে তার কাছে ঋণী। আমি বলব, আমি তাকে বলবো, সে বলবে, সে বলবে, এটা হবে আমার কাছে তার কাছে ঋণী। আমি এটা করতে চাই। আমি জানি, আমি জানি, আমি এটা করতে চাই, আমি জানি, আমি জানি না, আমি এটা করতে চাই, আমি এটা করতে পারি। আমি জানি, আমি জানি, আমি এটা করতে চাই। আমি যা করব, আমি এটা আমার কাছে একটা ছোট পরিবার। এবং আমি যদি আমার কাছে এটা করতে চাই, আমি এটা করতে চাই, আমি এটা করতে চাই। আমি শুধু একটা ছোট বিষয় নিয়ে কাজ করি। আমি যদি আমার কাছে একটা প্রশ্ন করি, এবং আমি এটা করতে চাই। আমি জানি যে, আমি এটা করতে চাই, আমি জানি যে, আমি এটা করতে চাই, আমি জানি, আমি তাকে বলতে বলছি না, ঈশ্বর, আমি তাকে দেখতে অনুরোধ করছি না, সে একটা গাছ পেয়েছে, সে তার থেকে ভালো আছে, আমি যা বলছি তা হল আমি যা শিখছিলাম তা সে ভাল আমি তাকে জিজ্ঞেস করব, আমি তাকে জিজ্ঞেস করব আমি তার সাথে কি করতে হবে না। সে বলবে আমি প্রতিজ্ঞা করছি আমি আমাকে স্বর্গে যাব কিনা। আপনি হাস্যরসের কৌতুক এবং তার সাথে কথা বলার জন্য তিনি আমার জন্য গর্বিত হবেন। এমনকি যদি সে তার কাছে থাকেও, সে আমাকে জিজ্ঞেস না করে কেন আমাকে তাকে হারিয়ে যেতে বলা হয়েছে। তারপর সে বলল, কেন আমাকে জিজ্ঞেস করা হল যে আমাকে তাকে হারিয়ে যেতে হবে। তারপর আমরা তাকে জিজ্ঞেস করলাম, আমি জিজ্ঞেস করলাম, আমি কি তাকে জিজ্ঞেস করলাম। তারপর আমি জিজ্ঞেস করলাম, আমি কি বলেছিলাম, আমি তাকে জিজ্ঞেস করলাম। এবং আমি কি বলেছিলাম, আমি জানি না যে, আমি তাকে এটা একটা ছোট জিনিস দেব? এবং আমি কি করব? এবং আমি জানি না যে, আমি তাকে জিজ্ঞেস করলাম, আমি কি করব? ঈশ্বর এটা ফিরিয়ে দিতে চান, যদি তুমি আমাকে জিজ্ঞেস কর কেন আমাকে হাসতে বলা হয়েছে, সে বলল আমি মজা করছি আর তুমি সমবেদনার দেবতা.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ البُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ آخِرَ مَنْ يَدْخُلُ الْجَنَّةَ رَجُلٌ يَمْشِي عَلَى الصِّرَاطِ فَيَنْكَبُّ مَرَّةً وَيَمْشِي مَرَّةً ‏ ‏وَتَسْفَعُهُ ‏ ‏النَّارُ مَرَّةً فَإِذَا جَاوَزَ الصِّرَاطَ الْتَفَتَ إِلَيْهَا فَقَالَ تَبَارَكَ الَّذِي نَجَّانِي مِنْكِ لَقَدْ أَعْطَانِي اللَّهُ مَا لَمْ يُعْطِ أَحَدًا مِنْ الْأَوَّلِينَ وَالْآخِرِينَ قَالَ فَتُرْفَعُ لَهُ شَجَرَةٌ فَيَنْظُرُ إِلَيْهَا فَيَقُولُ يَا رَبِّ ‏ ‏أَدْنِنِي ‏ ‏مِنْ هَذِهِ الشَّجَرَةِ فَأَسْتَظِلَّ بِظِلِّهَا وَأَشْرَبَ مِنْ مَائِهَا فَيَقُولُ أَيْ عَبْدِي فَلَعَلِّي إِنْ ‏ ‏أَدْنَيْتُكَ ‏ ‏مِنْهَا سَأَلْتَنِي غَيْرَهَا فَيَقُولُ لَا يَا رَبِّ وَيُعَاهِدُ اللَّهَ أَنْ لَا يَسْأَلَهُ غَيْرَهَا وَالرَّبُّ عَزَّ وَجَلَّ يَعْلَمُ أَنَّهُ سَيَسْأَلُهُ لِأَنَّهُ يَرَى مَا لَا صَبْرَ لَهُ ‏ ‏يَعْنِي عَلَيْهِ ‏ ‏فَيُدْنِيهِ مِنْهَا ثُمَّ تُرْفَعُ لَهُ شَجَرَةٌ وَهِيَ أَحْسَنُ مِنْهَا فَيَقُولُ يَا رَبِّ ‏ ‏أَدْنِنِي ‏ ‏مِنْ هَذِهِ الشَّجَرَةِ فَأَسْتَظِلَّ بِظِلِّهَا وَأَشْرَبَ مِنْ مَائِهَا فَيَقُولُ أَيْ عَبْدِي أَلَمْ تُعَاهِدْنِي ‏ ‏يَعْنِي أَنَّكَ لَا تَسْأَلُنِي غَيْرَهَا ‏ ‏فَيَقُولُ يَا رَبِّ هَذِهِ لَا أَسْأَلُكَ غَيْرَهَا وَيُعَاهِدُهُ وَالرَّبُّ يَعْلَمُ أَنَّهُ سَيَسْأَلُهُ غَيْرَهَا ‏ ‏فَيُدْنِيهِ ‏ ‏مِنْهَا فَتُرْفَعُ لَهُ شَجَرَةٌ عِنْدَ بَابِ الْجَنَّةِ هِيَ أَحْسَنُ مِنْهَا فَيَقُولُ رَبِّ ‏ ‏أَدْنِنِي ‏ ‏مِنْ هَذِهِ الشَّجَرَةِ أَسْتَظِلُّ بِظِلِّهَا وَأَشْرَبُ مِنْ مَائِهَا فَيَقُولُ أَيْ عَبْدِي أَلَمْ تُعَاهِدْنِي أَنْ لَا تَسْأَلَنِي غَيْرَهَا فَيَقُولُ يَا رَبِّ هَذِهِ الشَّجَرَةُ لَا أَسْأَلُكَ غَيْرَهَا وَيُعَاهِدُهُ وَالرَّبُّ يَعْلَمُ أَنَّهُ سَيَسْأَلُهُ غَيْرَهَا لِأَنَّهُ يَرَى مَا لَا صَبْرَ لَهُ عَلَيْهَا ‏ ‏فَيُدْنِيهِ ‏ ‏مِنْهَا فَيَسْمَعُ أَصْوَاتَ أَهْلِ الْجَنَّةِ فَيَقُولُ يَا رَبِّ الْجَنَّةَ الْجَنَّةَ فَيَقُولُ عَبْدِي أَلَمْ تُعَاهِدْنِي أَنَّكَ لَا تَسْأَلُنِي غَيْرَهَا فَيَقُولُ يَا رَبِّ أَدْخِلْنِي الْجَنَّةَ قَالَ فَيَقُولُ عَزَّ وَجَلَّ ‏ ‏مَا ‏ ‏يَصْرِينِي مِنْكَ أَيْ عَبْدِي ‏ ‏أَيُرْضِيكَ أَنْ أُعْطِيَكَ مِنْ الْجَنَّةِ الدُّنْيَا وَمِثْلَهَا مَعَهَا قَالَ فَيَقُولُ أَتَهْزَأُ بِي وَأَنْتَ رَبُّ الْعِزَّةِ قَالَ فَضَحِكَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَتَّى بَدَتْ ‏ ‏نَوَاجِذُهُ ‏ ‏ثُمَّ قَالَ أَلَا تَسْأَلُونِي لِمَ ضَحِكْتُ قَالُوا لَهُ لِمَ ضَحِكْتَ قَالَ لِضَحِكِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا تَسْأَلُونِي لِمَ ضَحِكْتُ قَالُوا لِمَ ضَحِكْتَ يَا رَسُولَ اللَّهِ قَالَ لِضَحِكِ الرَّبِّ حِينَ قَالَ أَتَهْزَأُ بِي وَأَنْتَ رَبُّ الْعِزَّةِ ‏","","",""],[3531,3531,"","আমরা কথা বলেছি, আমার বাবার বাবার বাবার কাছে ফিরে যাওয়ার জন্য আমি কিভাবে খুশি হব। ঈশ্বর আমাদের বলেছেন আমরা ঈশ্বরের কাছে যাবো এবং তাকে উদ্ধার করবো। রিং এর জন্য বা যাও।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنِي ‏ ‏شُعْبَةُ بْنُ الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْكَنُودِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ خَاتَمِ الذَّهَبِ أَوْ حَلَقَةِ الذَّهَبِ ‏","","",""],[3532,3532,"","আমরা একজন নেতা হওয়ার চেয়ে বরং সিদ্ধান্ত নিয়ে অনেক কথা বলেছি। ঈশ্বর আমাদের ক্ষমতা দিয়েছিলেন যেন সূর্য পূর্ণ না হয়। আগুন।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏مُحَمَّدُ بْنُ طَلْحَةَ ‏ ‏عَنْ ‏ ‏زُبَيْدٍ ‏ ‏عَنْ ‏ ‏مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَبَسُونَا عَنْ صَلَاةِ الْوُسْطَى حَتَّى غَابَتْ الشَّمْسُ مَلَأَ اللَّهُ بُطُونَهُمْ وَقُبُورَهُمْ نَارًا ‏","","",""],[3533,3533,"","আমরা বাবার ছেলেকে তার পথটা দেওয়ার কথা বলেছিলাম, সে তোমাকে ফোন করা বন্ধ করেনি বা বলছে না, সে এটা বলছে না, কিন্তু সে বলছে সে বলছে যে সে আমার বাবার ছেলে। তার হাতে হাত পেতে চেষ্টা করছি, বিস্ফোরণটির কারণ কি।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَمْنَعَنَّ أَحَدَكُمْ أَذَانُ ‏ ‏بِلَالٍ ‏ ‏مِنْ سَحُورِهِ فَإِنَّهُ إِنَّمَا يُنَادِي ‏ ‏أَوْ قَالَ يُؤَذِّنُ ‏ ‏لِيَرْجِعَ قَائِمُكُمْ وَيُنَبِّهَ نَائِمَكُمْ لَيْسَ أَنْ يَقُولَ هَكَذَا وَلَكِنْ حَتَّى يَقُولَ هَكَذَا وَضَمَّ ‏ ‏ابْنُ أَبِي عَدِيٍّ أَبُو عَمْرٍو ‏ ‏أَصَابِعَهُ وَصَوَّبَهَا وَفَتَحَ مَا بَيْنَ أُصْبُعَيْهِ ‏ ‏السَّبَّابَتَيْنِ ‏ ‏يَعْنِي الْفَجْرَ ‏","","",""],[3534,3534,"","আমরা এমন আবেগ নিয়ে কথা বলেছি যা আমার বাবা আর তার প্রভুর অনুভূতি নিয়ে এসেছে। তাকে বলতেই হবে যে, আমার ভালোবাসা সহ কারো সাথে আছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْمَرْءُ مَعَ مَنْ أَحَبَّ ‏","","",""],[3535,3535,"","আমরা আমার বাবাকে ভালবাসি তার সাথে প্রেম করার চেষ্টা করার ব্যাপারে কথা বলেছি। আমি প্রার্থনা করছি আল্লাহ আমাদের কাছে পৌঁছে দিয়েছেন এবং আমাদের কাছে যা বলার আছে তা হচ্ছে আপনার ওজন তার চেয়ে ভালো। আমরা যদি ঈশ্বরের কাছে আসি এবং ক্ষমা চাই, তাহলে আমরা আপনাকে ক্ষমা করে দিবো। কারণ সেই ব্যক্তি যিনি এই প্রেম ক্ষমা করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ مِمَّا يُكْثِرُ أَنْ يَقُولَ سُبْحَانَكَ رَبَّنَا وَبِحَمْدِكَ اللَّهُمَّ اغْفِرْ لِي قَالَ فَلَمَّا نَزَلَتْ ‏ ‏إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ ‏ ‏قَالَ ‏ ‏سُبْحَانَكَ رَبَّنَا وَبِحَمْدِكَ اللَّهُمَّ اغْفِرْ لِي إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ ‏","","",""],[3536,3536,"","আমরা বাবার সাথে কথা বলেছি, আমি শুনেছি বাবা কথা বলে ঈশ্বরের কাছে কথা বলে, আমাদের পতাকা উদ্ধার করতে হবে যেন তার ক্ষমা পাওয়া প্রয়োজন। ঈশ্বর তাকে ভয় দেখান। আমি নিশ্চিত, আমি নিশ্চিত, আমি বাবার সাথে কথা বলেছি, ঈশ্বর আমাদের কথা বলে দিন, আমি যদি আমার কাছে কিছু বলার চেষ্টা করি, আমি আমার বাবার কথা শুনেছি, সে তার বিজয়ের কথা বলছে, সে তার জয়ের জন্য নিরাপদ, হয়তো তোমাকে এমন এক শ্বাস থেকে বের করে দিয়েছে যে তার ভেতর দিয়ে চলে গেছে আর সে অনেক পুরুষ আর মানুষ সম্পর্কে কথা বলছে। বাকিটা তোমার ভালো হবে যে ঈশ্বরকে বলতে গেলে তুমি আর তোমাকে বলতে, তোমার মধ্যে যারা আছে তারা সবাই আর ঈশ্বরের জয় হারবে আর তুমি মনে করো আমার বড় একটা জয় হবে। আমি আমার বাবাকে একটা ভাল খেলা খুঁজে বের করতে যাচ্ছি আর আমার বাবা চেষ্টা করছে তাকে ভালোবাসতে। ঈশ্বর দুটো পরিকল্পনা করেছেন যাতে তার প্রয়োজন হয় এবং তার চাবির পরিকল্পনা করতে পারেন। তার আত্মা.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ عَلَّمَنَا خُطْبَةَ الْحَاجَةِ ‏ ‏الْحَمْدُ لِلَّهِ نَسْتَعِينُهُ وَنَسْتَغْفِرُهُ وَنَعُوذُ بِاللَّهِ مِنْ شُرُورِ أَنْفُسِنَا مَنْ يَهْدِهِ اللَّهُ فَلَا مُضِلَّ لَهُ وَمَنْ يُضْلِلْ فَلَا هَادِيَ لَهُ وَأَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ ثُمَّ يَقْرَأُ ثَلَاثَ آيَاتٍ ‏ { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ وَلَا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ ‏} { ‏يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا ‏ ‏وَبَثَّ ‏ ‏مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَاءً وَاتَّقُوا اللَّهَ الَّذِي ‏ ‏تَسَاءَلُونَ بِهِ وَالْأَرْحَامَ إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا ‏} { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَقُولُوا قَوْلًا سَدِيدًا يُصْلِحْ لَكُمْ أَعْمَالَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَمَنْ يُطِعْ اللَّهَ وَرَسُولَهُ فَقَدْ فَازَ فَوْزًا عَظِيمًا ‏} ‏ثُمَّ تَذْكُرُ حَاجَتَكَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَنْبَأَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏وَأَبِي الْأَحْوَصِ ‏ ‏قَالَ ‏ ‏وَهَذَا حَدِيثُ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏عَلَّمَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُطْبَتَيْنِ خُطْبَةَ الْحَاجَةِ وَخُطْبَةَ الصَّلَاةِ الْحَمْدُ لِلَّهِ أَوْ إِنَّ الْحَمْدَ لِلَّهِ نَسْتَعِينُهُ فَذَكَرَ مَعْنَاهُ ‏","","",""],[3537,3537,"","আমরা আমার বাবা একটি ছেলের উপর জয় চেষ্টা করা কথা বলেছি যে হয়ত বলেছে যে ঈশ্বর তাকে আদেশ করেছেন এবং তার নিজের কবর থেকে একজন মাস্টারকে উদ্ধার করবেন, আমার বাবা এসেছেন ( গীতসংহিতা ৩৪: ৮) তার নিজের পাপের জন্য শাস্তি পেতে হলে ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তাঁর করুণার জন্য তাকে প্রার্থনা করেছেন । শকাকের মৃত্যু বলছে যে সে তাকে হত্যা করতে দেখেছে, সে তাকে রাজকুমারী হতে দেখেছে, অথবা আমার বাবা তাকে ছেড়ে চলে গেছে এবং প্রার্থনা করছে তাকে ফেলে দেওয়া হয়েছে। \"মা\" ছিল এক মরা ছেলে যে মায়ের সন্তান নিয়ে জন্ম নিয়েছিল।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏بَيْنَمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَاجِدٌ وَحَوْلَهُ نَاسٌ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏إِذْ جَاءَ ‏ ‏عُقْبَةُ بْنُ أَبِي مُعَيْطٍ ‏ ‏بِسَلَى ‏ ‏جَزُورٍ ‏ ‏فَقَذَفَهُ عَلَى ظَهْرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يَرْفَعْ رَأْسَهُ فَجَاءَتْ ‏ ‏فَاطِمَةُ ‏ ‏فَأَخَذَتْهُ مِنْ ظَهْرِهِ وَدَعَتْ عَلَى مَنْ صَنَعَ ذَلِكَ قَالَ فَقَالَ ‏ ‏اللَّهُمَّ عَلَيْكَ الْمَلَأَ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏أَبَا جَهْلِ بْنَ هِشَامٍ ‏ ‏وَعُتْبَةَ بْنَ رَبِيعَةَ ‏ ‏وَشَيْبَةَ بْنَ رَبِيعَةَ ‏ ‏وَعُقْبَةَ بْنَ أَبِي مُعَيْطٍ ‏ ‏وَأُمَيَّةَ بْنَ خَلَفٍ ‏ ‏أَوْ ‏ ‏أُبَيَّ بْنَ خَلَفٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏الشَّاكُّ ‏ ‏قَالَ ‏ ‏فَلَقَدْ رَأَيْتُهُمْ قُتِلُوا يَوْمَ ‏ ‏بَدْرٍ ‏ ‏فَأُلْقُوا فِي بِئْرٍ غَيْرَ أَنَّ ‏ ‏أُمَيَّةَ ‏ ‏أَوْ ‏ ‏أُبَيًّا ‏ ‏تَقَطَّعَتْ أَوْصَالُهُ فَلَمْ يُلْقَ فِي الْبِئْرِ ‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏فَذَكَرَ الْحَدِيثَ إِلَّا أَنَّهُ قَالَ ‏ ‏عَمْرَو بْنَ هِشَامٍ ‏ ‏وَأُمَيَّةَ بْنَ خَلَفٍ ‏ ‏وَزَادَ ‏ ‏وَعِمَارَةَ بْنَ الْوَلِيدِ ‏","","",""],[3538,3538,"","আমরা একটা বিশেষ আবেগ তৈরি করেছি যা তোমার জন্য একটা কঠিন কাজ নিয়ে এসেছি, আমি বলছি আমি একজন মানুষ যে কিনা এটা পাঠ করেছে এবং সে এটা জিজ্ঞাসা করেছে ঈশ্বর ঘৃণাকে তাঁর কাছে প্রার্থনা করার মাধ্যমে তাঁর কাছে প্রার্থনা করেছিলেন । আমি তাকে সাহায্য করার চেষ্টা করেছি আর সে ঈশ্বরের কাছে তার কাছে আসার চেষ্টা করছে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ مَيْسَرَةَ ‏ ‏عَنِ ‏ ‏النَّزَّالِ بْنِ سَبْرَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏سَمِعْتُ رَجُلًا يَقْرَأُ آيَةً وَسَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَيْرَهَا فَأَتَيْتُ بِهِ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَغَيَّرَ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ عَرَفْتُ فِي وَجْهِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْكَرَاهِيَةَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كِلَاكُمَا مُحْسِنٌ إِنَّ مَنْ قَبْلَكُمْ اخْتَلَفُوا فِيهِ فَأَهْلَكَهُمْ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَحَدَّثَنِي ‏ ‏مِسْعَرٌ ‏ ‏عَنْهُ وَرَفَعَهُ إِلَى ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَا تَخْتَلِفُوا ‏","","",""],[3539,3539,"","আমরা যুদ্ধের মাধ্যমে তোমার বিষের প্রতি প্রবল আগ্রহ নিয়ে কথা বলেছি... ...কিন্তু আল্লাহ তোমার উপর দয়া করে আছে, আমি খুশি যে তুমি দুজন মেয়েকে একটা গর্তে ফেলে দাওনি আর ঈশ্বর সেটা দিয়েছেন। তার মক্কেল তার বই দেখেছে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَبْدِ اللَّهِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا تَصْلُحُ سَفْقَتَانِ فِي سَفْقَةٍ وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَعَنَ اللَّهُ آكِلَ الرِّبَا ‏ ‏وَمُوكِلَهُ وَشَاهِدَهُ وَكَاتِبَهُ ‏","","",""],[3540,3540,"","আমরা শুনেছি আলতোভাবে শুনেছি যে আমি ঈশ্বরের চেয়ে বেশি শুনেছি, আমি এটা পেতে চেষ্টা করছি, সে হয়ত তার জীবনের জন্য ঈশ্বরকে টাকা দিতে পারে। ভাল, ভালো। তার পাপকে বাড়িয়ে দাও.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَبْدِ اللَّهِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَأَحْسِبُهُ قَدْ رَفَعَهُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلُ الَّذِي يُعِينُ عَشِيرَتَهُ عَلَى غَيْرِ الْحَقِّ مَثَلُ الْبَعِيرِ ‏ ‏رُدِّيَ ‏ ‏فِي بِئْرٍ فَهُوَ ‏ ‏يَمُدُّ ‏ ‏بِذَنَبِهِ ‏","","",""],[3541,3541,"","আমরা আবেগ দ্বারা বাপ্তাইজিত হয়েছি, আমার বাবা এবং ঈশ্বরের এক পরিবারের স্বপ্নের কথা। ঈশ্বর বলেছেন, মানুষ যুদ্ধ না করতে চাইলে তাকে পরাজিত করা হবে এবং তার বন্ধুকে আমরা পরাজিত করব। সত্য না পাওয়া পর্যন্ত স্বাধীন হবে ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَزَالُ الرَّجُلُ يَصْدُقُ ‏ ‏وَيَتَحَرَّى ‏ ‏الصِّدْقَ حَتَّى يُكْتَبَ صِدِّيقًا وَلَا يَزَالُ يَكْذِبُ ‏ ‏وَيَتَحَرَّى ‏ ‏الْكَذِبَ حَتَّى يُكْتَبَ كَذَّابًا ‏","","",""],[3542,3542,"","আমরা একটা ভারী বোঝা নিয়ে কথা বলেছি, আমাকে একটা কুত্তার বাচ্চা দেখাতে হবে। ঈশ্বর তার জন্য প্রার্থনা করেছেন। আর তিনি বললেন, আমি মানুষকে হত্যা করবো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هُنَيِّ بْنِ نُوَيْرَةَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَعَفُّ النَّاسِ قِتْلَةً أَهْلُ الْإِيمَانِ ‏","","",""],[3543,3543,"","আমরা নিশ্চিত হয়েছি যে আমরা একটি ছেলের প্রতি ঈর্ষাপরায়ণ হওয়ার ব্যাপারে কিছু করেছি, ঈশ্বর তাকে জানতেন আর সে বলল যে আমি মানুষকে খুন করি।","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏مُغِيرَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أَعَفَّ النَّاسِ قِتْلَةً أَهْلُ الْإِيمَانِ ‏","","",""],[3544,3544,"","আমরা বেঁচে থাকার জন্য দুই বছরের ঈশ্বরের দর্শন নিয়ে কথা বলেছি, আল্লাহকে এটা উদ্ধার করতে হবে আর সে দুই বার দুইটা মটরশুঁটি স্পর্শ করতে হবে। যে কিনা পারে, সে হয়ত তাকে তা সম্ভব। আমি যা বলেছি, আমরা তাই করেছি। আমরা অতীত কালের একজন পাগলের সাথে আমার দুই স্বপ্নের স্বপ্নের মধ্যে খুঁজছি। ঈশ্বর তার জন্য প্রার্থনা করেন এবং তিনি যেমন বলেছেন, তিনি আত্মসমর্পণ করবেন। কখনোই পাশ হয়নি.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏رِبْعِيٍّ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ نَاجِيَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَدُورُ ‏ ‏رَحَى ‏ ‏الْإِسْلَامِ بِخَمْسٍ وَثَلَاثِينَ أَوْ سِتٍّ وَثَلَاثِينَ أَوْ سَبْعٍ وَثَلَاثِينَ فَإِنْ يَهْلَكُوا فَسَبِيلُ مَنْ قَدْ هَلَكَ وَإِنْ ‏ ‏يَقُمْ ‏ ‏لَهُمْ دِينُهُمْ ‏ ‏يَقُمْ ‏ ‏لَهُمْ سَبْعِينَ عَامًا قَالَ قُلْتُ أَمِمَّا مَضَى أَمْ مِمَّا بَقِيَ قَالَ مِمَّا بَقِيَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏رِبْعِيِّ بْنِ حِرَاشٍ ‏ ‏عَنْ ‏ ‏الْبَرَاءِ بْنِ نَاجِيَةَ الْكَاهِلِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ إِلَّا أَنَّهُ قَالَ فَقَالَ لَهُ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏مَا مَضَى أَمْ مَا بَقِيَ قَالَ مَا بَقِيَ ‏","","",""],[3545,3545,"","আমরা দু'বছরের জন্য ঈশ্বরের সর্বোচ্চ অভিজ্ঞতা নিয়ে কথা বলেছি, তিনি বলেছিলেন তিনি আত্মসমর্পণ করেছেন, আমি আপনাকে তার ভালবাসা বাড়াতে এবং আমাকে শুনতে অনুমোদন করেছি,","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ يَعْنِي ابْنَ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏أَذِنْتُ لَكَ أَنْ تَرْفَعَ الْحِجَابَ وَتَسْمَعَ ‏ ‏سِوَادِي ‏ ‏حَتَّى ‏ ‏أَنْهَاكَ ‏","","",""],[3546,3546,"","বাবা ডর্ডেলস আমাদের সাথে কথা বলেছিলেন, একজন অতিথি যিনি আমাদের সাথে কথা বলেছেন যখন তিনি একটি চাকরি পেতে যাচ্ছেন। আমি ঈশ্বরের ইচ্ছার বিরুদ্ধে যুদ্ধ করতে চাই, ঈশ্বর তার কাছে প্রার্থনা করেছেন। আর তাকে ভূ-শার্টে বিষ দেয়া হতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ عِيَاضٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَحَبَّ ‏ ‏الْعُرَاقِ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الذِّرَاعُ ذِرَاعُ الشَّاةِ وَكَانَ قَدْ سُمَّ فِي الذِّرَاعِ وَكَانَ يَرَى أَنَّ ‏ ‏الْيَهُودَ ‏ ‏هُمْ سَمُّوهُ ‏","","",""],[3547,3547,"","তার কণ্ঠ বলতে গেলে ঈশ্বরকে খুশি করতে পারে বলে ঈশ্বর হয়তো আমাদেরকে ঈশ্বরের কাছে জিজ্ঞেস করতে পারেন । তাড়াতাড়ি চলে যাও, অনুসরণ করো আর আমাদের অনুসরণ করো, যে তার সাথে পরিচয় করিয়ে দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى الْجَابِرُ أَبُو الْحَارِثِ التَّيْمِيُّ ‏ ‏أَنَّ ‏ ‏أَبَا مَاجدٍ ‏ ‏رَجُلٌ مِنْ ‏ ‏بَنِي حَنِيفَةَ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْعُودٍ ‏ ‏سَأَلْنَا نَبِيَّنَا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ السَّيْرِ بِالْجِنَازَةِ فَقَالَ ‏ ‏السَّيْرُ مَا دُونَ ‏ ‏الْخَبَبِ ‏ ‏فَإِنْ يَكُ خَيْرًا تُعْجَلْ إِلَيْهِ ‏ ‏أَوْ قَالَ لِتُعْجَلْ إِلَيْهِ ‏ ‏وَإِنْ يَكُ سِوَى ذَاكَ فَبُعْدًا لِأَهْلِ النَّارِ الْجِنَازَةُ مَتْبُوعَةٌ وَلَا تَتْبَعُ لَيْسَ مِنَّا مَنْ تَقَدَّمَهَا ‏","","",""],[3548,3548,"","আমরা কথা বলেছিলাম বাবা যেন জানতে পারে, সে ঈশ্বরকে বলে যে সে তার জন্য প্রার্থনা করে আর সে এক ঘন্টা কাজ না করে।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْأَقْمَرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْأَحْوَصِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ إِلَّا عَلَى شِرَارِ النَّاسِ ‏","","",""],[3549,3549,"","ঈশ্বর বলেছিলেন যে, আমি তাঁর কাছে প্রার্থনা করি এবং প্রতি চতুর্থাংশ ও সময়ে বৃদ্ধি পাই । ঈশ্বরের সেবা করা, কর।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏وَعَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكَبِّرُ فِي كُلِّ رَفْعٍ وَوَضْعٍ وَقِيَامٍ وَقُعُودٍ وَيُسَلِّمُ عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ حَتَّى أَرَى بَيَاضَ خَدِّهِ وَرَأَيْتُ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏يَفْعَلَانِ ذَاكَ ‏","","",""],[3550,3550,"","আমরা আমাদের ভালো ছেলের জন্য জিজ্ঞাসা করেছি, ঈশ্বরের বার্তাবাহক তাকে আদেশ দিয়েছেন আর তার সব ভগবানকে আত্মসমর্পণ করেছেন তার বই দেখে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏آكِلَ الرِّبَا ‏ ‏وَمُوكِلَهُ وَشَاهِدَيْهِ وَكَاتِبَهُ ‏","","",""],[3551,3551,"","আমরা আমার বাবাকে খুঁজে বের করে ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং আমরা আমাদের কোরআনের বেড়া কিভাবে শিখতে পারি তা জানতে আমাদের শিখাব।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏جَامِعِ بْنِ أَبِي رَاشِدٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعَلِّمُنَا التَّشَهُّدَ كَمَا يُعَلِّمُنَا السُّورَةَ مِنْ الْقُرْآنِ ‏","","",""],[3552,3552,"","আমরা তোমার বাবার বাবার বাবার বাবার জন্য তার বাবার বাবার বাবার ভালবাসার কথা বলেছিলাম, ঈশ্বরের দোহাই দিয়ে প্রার্থনা করলাম, আর সে তার কাছে পৌঁছে দিল যাতে সে ডিমটা ছুঁড়ে ফেলে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏ثُوَيْرِ بْنِ أَبِي فَاخِتَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَبَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى رَمَى ‏ ‏جَمْرَةَ الْعَقَبَةِ ‏","","",""],[3553,3553,"","আমি বাবার সাথে আমার বাবার প্রেমের প্রতি করুণা দেখানোর কথা বলেছিলাম, সে কখনো বলেনি যে প্রভুর প্রভুর কাছে তার সবচেয়ে ভালো মানুষ হবে... আর পরিতৃপ্তির সাথে","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏فِي قَوْلِهِ مَا كَذَبَ الْفُؤَادُ مَا رَأَى قَالَ ‏ ‏رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جِبْرِيلَ ‏ ‏فِي ‏ ‏حُلَّةٍ ‏ ‏مِنْ ‏ ‏رَفْرَفٍ ‏ ‏قَدْ مَلَأَ مَا بَيْنَ السَّمَاءِ وَالْأَرْضِ ‏","","",""],[3554,3554,"","আমরা কথা বলেছিলাম এর চেয়ে ভালো কিছু করার ছিল। সে বলল, ভগবানের কাছে প্রার্থনা করুক, আর সে আমাকে আত্মার শক্তি দেবে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏أَقْرَأَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي أَنَا ‏ { ‏الرَّزَّاقُ ذُو الْقُوَّةِ الْمَتِينُ ‏}","","",""],[3555,3555,"","ঈশ্বর তাকে তাঁর সিংহাসনে বসে থাকতে বলেছিলেন, বলেছিলেন যে, আপনার পাপ প্রকাশ পাবে ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا وَضَعَ جَنْبَهُ عَلَى فِرَاشِهِ قَالَ ‏ ‏قِنِي عَذَابَكَ يَوْمَ تَجْمَعُ عِبَادَكَ ‏","","",""],[3556,3556,"","আমি আমার বাবার সঙ্গে কথা বলেছিলাম, যিনি রাজা হওয়ার চেষ্টা করছেন । অজ্ঞান হয়ে গেল, তাদের মৃত্যু.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ ‏ ‏هَمَمْتُ أَنْ آمُرَ رَجُلًا فَيُصَلِّيَ بِالنَّاسِ ثُمَّ آمُرَ بِأُنَاسٍ لَا يُصَلُّونَ مَعَنَا فَتُحَرَّقَ عَلَيْهِمْ بُيُوتُهُمْ ‏","","",""],[3557,3557,"","বাবা যখন মারা যান, তখন আমি তার কাছে একটা চিঠি পাই ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏وَأَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو أَحْمَدَ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ أَنْ يَدْعُوَ ثَلَاثًا وَيَسْتَغْفِرَ ثَلَاثًا ‏","","",""],[3558,3558,"","আমরা আমার বাবার সঙ্গে তার সর্বোত্তম খেলা করার চেষ্টা করেছিলাম । তুমি আমাকে মাফ করে দিয়েছ যে মারা গেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏مُنْذُ أُنْزِلَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ ‏ ‏كَانَ يُكْثِرُ أَنْ يَقُولَ إِذَا قَرَأَهَا ثُمَّ رَكَعَ بِهَا أَنْ يَقُولَ ‏ ‏سُبْحَانَكَ رَبَّنَا وَبِحَمْدِكَ اللَّهُمَّ اغْفِرْ لِي إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ ثَلَاثًا ‏","","",""],[3559,3559,"","আমরা ঈশ্বরের ছেলের কথা বলেছি, সে সময় আরো অনেক লোক বলে যে আমি কতবার খুন হয়েছি। আমার বাবা তো হলো ঐ কথাটি বলেছে যে, আমার বাবা হলো ঐ দুইজনের মা যখন সে মারা যায় তখন তার মুখ দিয়ে মুখ ঢাকা থাকে। কে তার রক্ত সমাধান করতে পারবে?","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزيِدَ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏دَاوُدُ يَعْنِي ابْنَ الْفُرَاتِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَعْيَنِ الْعَبْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ الْجُشَمِيِّ ‏ ‏قَالَ ‏ ‏بَيْنَمَا ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏يَخْطُبُ ذَاتَ يَوْمٍ فَإِذَا هُوَ بِحَيَّةٍ تَمْشِي عَلَى الْجِدَارِ فَقَطَعَ خُطْبَتَهُ ثُمَّ ضَرَبَهَا بِقَضِيبِهِ ‏ ‏أَوْ بِقَصَبَةٍ ‏ ‏قَالَ ‏ ‏يُونُسُ ‏ ‏بِقَضِيبِهِ ‏ ‏حَتَّى قَتَلَهَا ثُمَّ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ قَتَلَ حَيَّةً فَكَأَنَّمَا قَتَلَ رَجُلًا مُشْرِكًا قَدْ ‏ ‏حَلَّ ‏ ‏دَمُهُ ‏","","",""],[3560,3560,"","আমরা ঈশ্বরের ছেলেকে কথা বলেছিলাম আমার বাবার সাহায্য চেয়ে শক্তিশালী হতে। আমার বাবা আমার শরীর রক্ষা করার চেষ্টা করছেন। ঈশ্বরের দোহাই, লর্ড লর্ড লর্ডের লর্ডের লর্ডের কাছে... ...তিনি আদেশ দিয়েছেন যে, ঈশ্বর কোন ভুল করেননি, কিন্তু এটা একটা মিথ্যা কথা। প্রভুর কাছে গিয়েছে তাদের ব্যবহার করতে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏دَاوُدُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَعْيَنِ الْعَبْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ الْجُشَمِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏سَأَلْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْقِرَدَةِ وَالْخَنَازِيرِ أَهِيَ مِنْ نَسْلِ ‏ ‏الْيَهُودِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ لَمْ يَلْعَنْ قَوْمًا قَطُّ ‏ ‏فَمَسَخَهُمْ ‏ ‏فَكَانَ لَهُمْ نَسْلٌ حِينَ يُهْلِكُهُمْ وَلَكِنْ هَذَا خَلْقٌ كَانَ فَلَمَّا غَضِبَ اللَّهُ عَلَى ‏ ‏الْيَهُودِ ‏ ‏مَسَخَهُمْ فَجَعَلَهُمْ مِثْلَهُمْ ‏","","",""],[3561,3561,"","ঈশ্বরের পথে আমার বাবার ভবিষ্যৎ নিয়ে আমরা কথা বলেছি, তিনি গ্যাব্রিয়েলকে তাঁর ছবিতে তুলে দেবেন এবং তার প্রতিটি ডানার মধ্যে ছয় শত শততম অংশ থাকবে। ( ১ করিন্থীয় ১০: ৩১) গর্ভের মধ্যে, ঈশ্বরের বেঁচে থাকার জ্ঞান রয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جِبْرِيلَ ‏ ‏فِي صُورَتِهِ وَلَهُ سِتُّ مِائَةِ جَنَاحٍ كُلُّ جَنَاحٍ مِنْهَا قَدْ سَدَّ ‏ ‏الْأُفُقَ ‏ ‏يَسْقُطُ مِنْ جَنَاحِهِ مِنْ التَّهَاوِيلِ وَالدُّرِّ وَالْيَاقُوتِ مَا اللَّهُ بِهِ عَلِيمٌ ‏","","",""],[3562,3562,"","তিনি বলেছিলেন যে, কীভাবে তিনি ঈশ্বরের কাছ থেকে কেড়ে নিয়েছিলেন । আত্মসমর্পণ করা হয়েছে","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏فِي قَوْلِهِ ‏ { ‏وَاتَّخَذَ اللَّهُ ‏ ‏إِبْرَاهِيمَ ‏ ‏خَلِيلًا ‏} ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ رِبْعِيٍّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ اللَّهَ اتَّخَذَ صَاحِبَكُمْ ‏ ‏خَلِيلًا ‏ ‏يَعْنِي ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[3563,3563,"","আমি আমার মাস্টারের সাথে সেক্সের কথা বলেছিলাম.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ رِبْعِيٍّ الْأَسَدِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ صَاحِبَكُمْ ‏ ‏خَلِيلُ ‏ ‏اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[3564,3564,"","আমরা বাবার সঙ্গে কথা বলার চেষ্টা করেছিলাম যখন আমরা আমার হয়ে কাজ করার পর আমরা আমার সঙ্গে কথা বলতে গিয়েছিলাম । বাতিল করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ رِبْعِيٍّ الْأَسَدِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ صَاحِبَكُمْ ‏ ‏خَلِيلُ ‏ ‏اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[3565,3565,"","আমরা একটা ভাঙা বিষয় নিয়ে কথা বলেছিলাম যেটা তোমার সাথে কিছু একটা করার জন্য হয়েছিল. সে বলল ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তোমার কমরেডকে সে বলেছে যে তোমার সঙ্গী ঈশ্বরের জীবন ভেঙে দিয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ رِبْعِيٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ صَاحِبَكُمْ ‏ ‏خَلِيلُ ‏ ‏اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[3566,3566,"","আমরা আমার উপহারের কথা বলেছিলাম ঈশ্বরের সাথে কিছু করার জন্য, তোমাদের বন্ধুরা এখন ঈশ্বরের শোকের মাধ্যমে আসছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ رِبْعِيٍّ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏إِنَّ صَاحِبَكُمْ خَلِيلُ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[3567,3567,"","আমরা বাবার ছেলে আসার ব্যাপারে দুজন পুরুষের ব্যাপারে কথা বলেছি, সে লর্ডের কাছে নিজেকে সমর্পণ করেছে, তার শাস্তির চেয়ে কিছু শব্দও বেশি।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الرُّكَيْنِ بْنِ الرَّبِيعِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الرِّبَا وَإِنْ كَثُرَ فَإِنَّ عَاقِبَتَهُ تَصِيرُ إِلَى قُلٍّ ‏","","",""],[3568,3568,"","বাবা আমাদের তর্কের কথা বলেছি, এক যাদুময় ছেলের ছেলেকে জিততে চেষ্টা করার জন্য, ঈশ্বর এটা দিয়েছেন এবং আমরা হয়তো একটি সময় থেকে পবিত্র পিতার স্মরণ করার সুযোগ পেয়েছি আমি ঈশ্বরের কাছে প্রার্থনা করতাম আর শিক্ষককে পাঠিয়ে দিতাম।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏أَقْرَأَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏وَلَقَدْ يَسَّرْنَا الْقُرْآنَ لِلذِّكْرِ فَهَلْ مِنْ ‏ ‏مُدَّكِرٍ ‏ } ‏فَقَالَ رَجُلٌ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏مُدَّكِرٍ ‏ ‏أَوْ مُذَّكِّرٍ قَالَ أَقْرَأَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُدَّكِرٍ ‏","","",""],[3569,3569,"","আমরা জানতে পেরেছি যে, ঈশ্বর কি করতে সক্ষম হতে পারে তা খুঁজে পাওয়া কি উত্তম। প্রভু তার জন্য প্রার্থনা করেছিলেন এবং তিন সেকেন্ড তিনি তার আত্মার অনুগ্রহ জয়ের জন্য আত্মসমর্পণ করবেন। আমি সংযুক্ত আছি। আমি এটা হল আমার কাছে একটি সহজ উপায়। আমি কি জানি? আমি জানি না, আমি এটা আসলে কি করতে পারি? আমি জানি না? আমি যদি আমার মনে হয় যে, আমি এটা একটা জিনিস আছে? আমি জানি, আমি জানি, আমি এটা আমার মনে হয়, আমি এটা আমার কাছে এটা একটা ভাল হবে। আমি যা আছে, আমি কি? আমি জানি না? আমি জানি, আমি যদি আমি এটা আমার বাবা, আমি জানি না, আমি এটা করতে পারি, আমি কি করতে পারি? আমি জানি না? আমি জানি না? আমি জানি, আমি এটা আমার কাছে এটা একটা ভাল উপায় আছে। আমি কি? আমি জানি না। আমি জানি না। আমি যদি আমার বাবা-মাগব, আমি এটা আমার বাবা-মাকে জিজ্ঞেস করি, আমি এটা একটা প্রশ্ন করি, আমি যদি আমি এটা একটা ছোট কাজ করতে পারি। আমি এটা আমার কাছে একটা প্রশ্ন করি। ঈশ্বরের কাজ করার পথে এটা আমার মুখ আর এটা বলা হয়েছে। অথবা ভুলে যাওয়া ভুলেও ভুল নয় যে আমার বাবা একটা মানুষের জন্য খারাপভাবে চলে গেছে। কে লর্ড, কল্পনাটা তিন বার এই ঘটনা উল্লেখ করেছে।","‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏أَنْبَأَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الرُّكَيْنِ بْنِ الرَّبِيعِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ حَسَّانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْخَيْلُ ثَلَاثَةٌ فَفَرَسٌ لِلرَّحْمَنِ وَفَرَسٌ لِلْإِنْسَانِ وَفَرَسٌ لِلشَّيْطَانِ فَأَمَّا فَرَسُ الرَّحْمَنِ فَالَّذِي يُرْبَطُ فِي سَبِيلِ اللَّهِ فَعَلَفُهُ وَرَوْثُهُ وَبَوْلُهُ وَذَكَرَ مَا شَاءَ اللَّهُ وَأَمَّا فَرَسُ الشَّيْطَانِ فَالَّذِي يُقَامَرُ ‏ ‏أَوْ يُرَاهَنُ ‏ ‏عَلَيْهِ وَأَمَّا فَرَسُ الْإِنْسَانِ فَالْفَرَسُ يَرْتَبِطُهَا الْإِنْسَانُ ‏ ‏يَلْتَمِسُ ‏ ‏بَطْنَهَا فَهِيَ تَسْتُرُ مِنْ فَقْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏الرُّكَيْنُ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ الْخَيْلُ ثَلَاثَةٌ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[3570,3570,"","আমরা তর্কের কথা বলেছি, আমার জন্য দুটো জাহাজ তৈরি হয়েছে, যা আমার জন্য ভালোর জন্য হয়েছে। সে ঈশ্বরকে তার সাথে সুখী হতে বলে এবং কয়েক বছর আত্মসমর্পণ করতে বলে। যারা আপনাকে অনুপ্রাণিত করে এবং তারা যা করে তাই করে, হয় তিনি অতীত হয়ে যান অথবা তিনি যা বাকি আছে বলে রাখা হয়।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏رِبْعِيٍّ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ نَاجِيَةَ الْكَاهِلِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏رَحَى ‏ ‏الْإِسْلَامِ سَتَزُولُ بِخَمْسٍ وَثَلَاثِينَ أَوْ سِتٍّ وَثَلَاثِينَ أَوْ سَبْعٍ وَثَلَاثِينَ فَإِنْ يَهْلَكْ فَكَسَبِيلِ مَنْ أُهْلِكَ وَإِنْ ‏ ‏يَقُمْ ‏ ‏لَهُمْ دِينُهُمْ ‏ ‏يَقُمْ ‏ ‏لَهُمْ سَبْعِينَ عَامًا قَالَ قَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ أَبِمَا مَضَى أَمْ بِمَا بَقِيَ قَالَ بَلْ بِمَا بَقِيَ ‏","","",""],[3571,3571,"","আমি আমার ছেলে যে তর্কের কথা শুনেছি, সে আমাকে দেখতে এসেছে। ঈশ্বর হয়তো তার কাছে প্রার্থনা করেছেন, যেন সে আমাকে ভালোবাসে। আমি তোমার কাছে যেতে চাই এবং আমি করব। তাদের মধ্যে একজন বলে, ঈশ্বর আর ঈশ্বর কে বেছে নেয়ার চেষ্টা করুন। তারপর আমি ঈশ্বরের কাছে প্রার্থনা করবো। আর আমি বলবো যে ঈশ্বর এটা বলবেন না যে তুমি বলবে যে আমি গান গাইনা। তোমাকে ছেড়ে দিতে বলা হয়েছে, আমার কষ্ট তোমার চেয়ে বেশি আর তুমি চলে যাচ্ছ।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏إِسْرَائِيلَ بْنَ يُونُسَ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ هِشَامٍ ‏ ‏مَوْلَى ‏ ‏الْهَمْدَانِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ زَائِدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَصْحَابِهِ ‏ ‏لَا يُبَلِّغْنِي أَحَدٌ عَنْ أَحَدٍ مِنْ أَصْحَابِي شَيْئًا فَإِنِّي أُحِبُّ أَنْ أَخْرُجَ إِلَيْكُمْ وَأَنَا سَلِيمُ الصَّدْرِ قَالَ وَأَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَالٌ فَقَسَمَهُ قَالَ فَمَرَرْتُ بِرَجُلَيْنِ وَأَحَدُهُمَا يَقُولُ لِصَاحِبِهِ وَاللَّهِ مَا أَرَادَ ‏ ‏مُحَمَّدٌ ‏ ‏بِقِسْمَتِهِ وَجْهَ اللَّهِ وَلَا الدَّارَ الْآخِرَةَ فَتَثَبَّتُّ حَتَّى سَمِعْتُ مَا قَالَا ثُمَّ أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّكَ قُلْتَ لَنَا لَا يُبَلِّغْنِي أَحَدٌ عَنْ أَحَدٍ مِنْ أَصْحَابِي شَيْئًا وَإِنِّي مَرَرْتُ بِفُلَانٍ وَفُلَانٍ وَهُمَا يَقُولَانِ كَذَا وَكَذَا قَالَ فَاحْمَرَّ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَشَقَّ عَلَيْهِ ثُمَّ قَالَ دَعْنَا مِنْكَ فَقَدْ أُوذِيَ ‏ ‏مُوسَى ‏ ‏أَكْثَرَ مِنْ ذَلِكَ ثُمَّ صَبَرَ ‏","","",""],[3572,3572,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং বাসা ছেড়ে লোকেদের গৌরবের জন্য এগিয়ে যান সূর্যের সবচেয়ে ভালোটা কে বলেছে যে আমি যদি ডাইনি হতে চাই... ...আর তুমি যা করো, তা তাকে ছেড়ে না দেয়া হবে আর ঈশ্বর বিশ্বাস নিয়ে দুনিয়া সম্পর্কে জানে","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏وَحَسَنُ بْنُ مُوسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏أَخَّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الْعِشَاءِ ثُمَّ خَرَجَ إِلَى الْمَسْجِدِ فَإِذَا النَّاسُ يَنْتَظِرُونَ الصَّلَاةَ قَالَ ‏ ‏أَمَا إِنَّهُ لَيْسَ مِنْ أَهْلِ هَذِهِ الْأَدْيَانِ أَحَدٌ يَذْكُرُ اللَّهَ هَذِهِ السَّاعَةَ غَيْرُكُمْ قَالَ وَأَنْزَلَ هَؤُلَاءِ الْآيَاتِ ‏ { ‏لَيْسُوا سَوَاءً مِنْ ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏حَتَّى بَلَغَ ‏ ‏وَمَا تَفْعَلُوا مِنْ خَيْرٍ فَلَنْ تُكْفَرُوهُ وَاللَّهُ عَلِيمٌ بِالْمُتَّقِينَ ‏}","","",""],[3573,3573,"","আমরা বাবার সাহায্য নিয়ে কথা বলেছি, বাতাসের পুত্র প্রভুর কাছে এসে লর্ডের কাছে দোষ দিয়ে এসেছে। আমি বলবো, আল্লাহ বলেছেন আমরা তার জন্য দোষারোপ করবো। আল্লাহ্‌কে হত্যা কর, হত্যা কর, বলছে যে, রসূলকে হত্যা করা হবে না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ أَبِي النَّجُودِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏ابْنُ النَّوَّاحَةِ ‏ ‏وَابْنُ أُثَالٍ ‏ ‏رَسُولَا ‏ ‏مُسَيْلِمَةَ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُمَا ‏ ‏أَتَشْهَدَانِ أَنِّي رَسُولُ اللَّهِ قَالَا نَشْهَدُ أَنَّ ‏ ‏مُسَيْلِمَةَ ‏ ‏رَسُولُ اللَّهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏آمَنْتُ بِاللَّهِ وَرُسُلِهِ لَوْ كُنْتُ قَاتِلًا رَسُولًا لَقَتَلْتُكُمَا ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ ‏ ‏فَمَضَتْ السُّنَّةُ أَنَّ الرُّسُلَ لَا تُقْتَلُ ‏","","",""],[3574,3574,"","আমরা একটি দুর্বল ছেলে সম্পর্কে কথা বলেছি... ...আমাদের দুই বছর হয়েছে... ...আমাদের জানা জানার জন্য যে আমরা ভবিষ্যদ্বাণীর প্রার্থনার কোণগুলো দেখেছি আর তার আশীর্বাদ আর তুমি ভয় হচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا نَرَى الْآيَاتِ فِي زَمَانِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَرَكَاتٍ وَأَنْتُمْ تَرَوْنَهَا تَخْوِيفًا ‏","","",""],[3575,3575,"","ভালর চেয়ে ভালোর চেয়েও ভাল ভাল ভাল আর ভালোর চেয়েও ভাল ভালর সাথে কথা বলেছি। আমি বললাম। ভাববাদীরা তার কাছে প্রার্থনা করেছিল আর হঠাৎ তাকে হত্যা করার জন্য একটা মোটেল দিত, আমি হয় বিছানায় যাচ্ছি আর বলে দেব ঈশ্বর আসবে আর সে এটা করবে। আমি জানি, আমি কি করবো? ভাসমান করে দাও।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏نَزَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْزِلًا فَانْطَلَقَ لِحَاجَتِهِ فَجَاءَ وَقَدْ أَوْقَدَ رَجُلٌ عَلَى قَرْيَةِ نَمْلٍ إِمَّا فِي الْأَرْضِ وَإِمَّا فِي شَجَرَةٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّكُمْ فَعَلَ هَذَا فَقَالَ رَجُلٌ مِنْ الْقَوْمِ أَنَا يَا رَسُولَ اللَّهِ قَالَ اطْفُهَا اطْفُهَا ‏","","",""],[3576,3576,"","আমরা বেনকে আমার কয়েক ছেলের জন্য সাহায্য করতে যাচ্ছি। হয়তো তিনি যদি ঈশ্বরের কাছে প্রার্থনা করেন, তাহলে তিনি তাকে বলতে বলবেন ঈশ্বর ঈশ্বর ঈশ্বর। আল্লাহ তাকে আশীর্বাদ করুন, প্রভু, আমি তাকে মনে রাখব। আমি মনে রাখি, আমি আমার মনে আছে, আমি আমার ছেলেদের মধ্যে, আমি আমার ছেলেদের সাহায্য করতে পারি। আমি যদি তাদের প্রার্থনা করি, আমি কি তাদের প্রার্থনা করি, আমি কি তাদের সাহায্য করব? বোমা হামলার শেষ যাত্রা শেষ পর্যন্ত আমি তোমার কলম নিয়ে গিয়েছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عَمْرِو بْنِ جَعْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ رَجُلًا أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْأَلُهُ عَنْ لَيْلَةِ الْقَدْرِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّكُمْ يَذْكُرُ لَيْلَةَ الصَّهْبَاوَاتِ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَنَا وَاللَّهِ أَذْكُرُهَا يَا رَسُولَ اللَّهِ بِأَبِي أَنْتَ وَأُمِّي وَإِنَّ فِي يَدَيَّ لَتَمَرَاتٍ أَتَسَحَّرُ بِهِنَّ مُسْتَتِرًا ‏ ‏بِمُؤْخِرَةِ رَحْلِي ‏ ‏مِنْ الْفَجْرِ وَذَلِكَ حِينَ طَلَعَ الْقَمَرُ ‏","","",""],[3577,3577,"","আমরা এক বছর আগে কথা বলেছি, আল্লাহ বলেছেন সে কখনই ঈশ্বরের কাছে নয়। ঈশ্বর আমাদের পক্ষ থেকে বিজয় দিয়েছেন এবং আপনি তাদের বলেছেন যে আমি চাই। তুমি জানো, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর আমি বাবার মাধ্যমে এই পথ অতিক্রম করবো, মানুষ অনেক ভালো হবে। তারা বলেছিল আমরা ঈশ্বরের জীবনে ফিরে যাবো।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا قُبِضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏الْأَنْصَارُ ‏ ‏مِنَّا أَمِيرٌ وَمِنْكُمْ أَمِيرٌ قَالَ فَأَتَاهُمْ ‏ ‏عُمَرُ ‏ ‏فَقَالَ يَا مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏أَلَسْتُمْ تَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ ‏ ‏أَبَا بَكْرٍ ‏ ‏أَنْ يَؤُمَّ بِالنَّاسِ فَأَيُّكُمْ تَطِيبُ نَفْسُهُ أَنْ يَتَقَدَّمَ ‏ ‏أَبَا بَكْرٍ ‏ ‏فَقَالُوا نَعُوذُ بِاللَّهِ أَنْ نَتَقَدَّمَ ‏ ‏أَبَا بَكْرٍ ‏","","",""],[3578,3578,"","ঈশ্বরের দয়া পাওয়ার চেয়ে ভালো কথা বলেছি, ঈশ্বর নিজেকে জীবন সমর্পণ করেছেন... ...যদি না আমি বলি যে আমি এর চেয়েও খারাপ কিছু করেছি...","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَطَالَ الْقِيَامَ حَتَّى هَمَمْتُ بِأَمْرِ سُوءٍ قَالَ قُلْنَا وَمَا هُوَ قَالَ هَمَمْتُ أَنْ أَقْعُدَ ‏","","",""],[3579,3579,"","ঈশ্বর আমার মন পরিবর্তন করেছেন বলে আমি আমার মনে মনে মনে মনে করেছিলাম । একটা গর্ভপাতের টুকরা তাকে দিয়ে ওকে সেরাটা করাতে পারবো।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْحُبُلِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَيُّ الظُّلْمِ أَعْظَمُ قَالَ ‏ ‏ذِرَاعٌ مِنْ الْأَرْضِ يَنْتَقِصُهُ مِنْ حَقِّ أَخِيهِ فَلَيْسَتْ حَصَاةٌ مِنْ الْأَرْضِ أَخَذَهَا إِلَّا طُوِّقَهَا يَوْمَ الْقِيَامَةِ إِلَى قَعْرِ الْأَرْضِ وَلَا يَعْلَمُ قَعْرَهَا إِلَّا الَّذِي خَلَقَهَا ‏","","",""],[3580,3580,"","বাবার সাথে কথা বলার সময় বাবার সাথে কথা বলেছিলাম, আমি এক সুখী ছেলের কাছ থেকে আমার শরীর বের করার চেষ্টা করছি যে বলেছিল আমরা ঈশ্বরকে ব্যবহার করতে ইচ্ছুক ঈশ্বর তাঁর লোকেদের জন্য প্রার্থনা করেছেন এবং তিনি তাঁর কাছে প্রার্থনা করেছেন আর তিনি চান যেন তিনি তাদের পরিত্যাগ করেন না কিন্তু তাদের মতো করে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ أَبِي الْفُرَاتِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَعْيَنِ الْعَبْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ الْجُشَمِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏سَأَلْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْقِرَدَةِ وَالْخَنَازِيرِ أَمِنْ نَسْلِ ‏ ‏الْيَهُودِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ لَمْ يَلْعَنْ قَوْمًا قَطُّ ‏ ‏فَمَسَخَهُمْ ‏ ‏وَكَانَ لَهُمْ نَسْلٌ حَتَّى يُهْلِكَهُمْ وَلَكِنَّ اللَّهَ عَزَّ وَجَلَّ غَضِبَ عَلَى ‏ ‏الْيَهُودِ ‏ ‏فَمَسَخَهُمْ ‏ ‏وَجَعَلَهُمْ مِثْلَهُمْ ‏","","",""],[3581,3581,"","আমরা বাবা-এর সাথে কথা বলেছি, আমরা যেভাবে জয়ী হয়েছিলাম, ঈশ্বর তার কাছে প্রার্থনা করেছিলেন আর তিনি তিন ফোন করে না দিয়ে তিন জনের জন্য সুন্দর হবেন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ أَنْ يَدْعُوَ ثَلَاثًا وَيَسْتَغْفِرَ ثَلَاثًا ‏","","",""],[3582,3582,"","আমরা বাবা বাবার সাথে ক্ষমা চাইতে বলেছিলাম কিন্তু তিনি আমাকে কখনো যেতে দিবেন না। ঈশ্বর তাকে বলতে বলেছেন যে তিনি ঈশ্বরের কাছে প্রার্থনা করছেন তাকে উদ্ধার করতে হবে আর তাকে অবশ্যই তিন বার ফোন করতে হবে আর অর্ধেক নয়।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ أَنْ يَدْعُوَ ثَلَاثًا وَيَسْتَغْفِرَ ثَلَاثًا ‏","","",""],[3583,3583,"","বাবা আমার সাথে ক্ষমা চাইতে চায় না, কিন্তু সে কখনো আমাকে তা করতে দেবে না। সে বলল ভগবানের কাছে প্রার্থনা করুক আর সে আমাকে সবচেয়ে ভালো শক্তি দেবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏أَقْرَأَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي أَنَا الرَّزَّاقُ ذُو الْقُوَّةِ الْمَتِينُ ‏","","",""],[3584,3584,"","আমরা আমার বাবার সুখী ছেলের ব্যাপারে কথা বলেছি, তিনি হয়তো একজন দু:খজনক বাবাকে বলেছিলেন যে সে জিতবেন, সে এমন একজন যার জয়ের চেষ্টা করছিল। সে এই সাক্ষ্যটি বলবে যে আমি অনেক বেশি দূরে ছিলাম। তার মেয়ে খুশি.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ أَبِي يَزِيدَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِلَالٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عُبَيْدِ بْنِ رِفَاعَةَ ‏ ‏أَنَّ ‏ ‏أَبَا مُحَمَّدٍ ‏ ‏أَخْبَرَهُ ‏ ‏وَكَانَ مِنْ أَصْحَابِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏حَدَّثَهُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ذَكَرَ عِنْدَهُ الشُّهَدَاءَ فَقَالَ ‏ ‏إِنَّ أَكْثَرَ شُهَدَاءِ أُمَّتِي أَصْحَابُ الْفُرُشِ وَرُبَّ قَتِيلٍ بَيْنَ الصَّفَّيْنِ اللَّهُ أَعْلَمُ ‏ ‏بِنِيَّتِهِ ‏","","",""],[3585,3585,"","ঈশ্বরের কাছে আমার বাবার কথা বলায় আমরা অনেক ভালো করেছি। আমি দুঃখিত, তার ভাইয়ের এই স্বপ্ন তার ভাইয়ের অধিকার নয়, সে তার সবচেয়ে ভালো আত্মার অংশ। ( আদি.","‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْحُبُلِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَيُّ الظُّلْمِ أَظْلَمُ قَالَ ‏ ‏ذِرَاعٌ مِنْ الْأَرْضِ يَنْتَقِصُهَا الْمَرْءُ الْمُسْلِمُ مِنْ حَقِّ أَخِيهِ فَلَيْسَ حَصَاةٌ مِنْ الْأَرْضِ يَأْخُذُهَا أَحَدٌ إِلَّا طُوِّقَهَا يَوْمَ الْقِيَامَةِ إِلَى قَعْرِ الْأَرْضِ وَلَا يَعْلَمُ قَعْرَهَا إِلَّا اللَّهُ عَزَّ وَجَلَّ الَّذِي خَلَقَهَا ‏","","",""],[3586,3586,"","আমরা ঈশ্বরের পুত্রদের কথা বলেছিলাম তারা যেন ঈশ্বরের পবিতশীকে খুঁজে পায়। তিনি তার বন্দি এবং লোকেদেরকে কখনোই পরিবর্তন করেছিলেন । দেখা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏الرُّكَيْنُ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ حَسَّانَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ حَرْمَلَةَ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَكْرَهُ عَشْرَ ‏ ‏خِلَالٍ ‏ ‏الصُّفْرَةُ ‏ ‏وَتَغْيِيرُ الشَّيْبِ وَتَخَتُّمُ الذَّهَبِ وَجَرُّ ‏ ‏الْإِزَارِ ‏ ‏وَالتَّبَرُّجُ بِالزِّينَةِ بِغَيْرِ مَحِلِّهَا وَضَرْبُ الْكِعَابِ ‏ ‏وَعَزْلُ ‏ ‏الْمَاءِ ‏ ‏عَنْ مَحَلِّهِ وَفَسَادُ الصَّبِيِّ غَيْرَ مُحَرِّمِهِ وَعَقْدُ ‏ ‏التَّمَائِمِ ‏ ‏وَالرُّقَى إِلَّا بِالْمُعَوِّذَاتِ ‏","","",""],[3587,3587,"","ঈশ্বর তাকে প্রার্থনা করার কথা বলেছিলেন এবং ঈশ্বর ঈশ্বর তাকে অগ্নিময় আত্মা দেবেন বলে তাকে ডাকা হবে । আমার বাবার এই কামনার প্রতারণার প্রতারণাই তার প্রতারণা, তারা তাদের স্পর্শ পরিবর্তন করেছে আর এটা একটা স্বাধীন দিন।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏اسْتَقْبَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَيْتَ ‏ ‏فَدَعَا عَلَى ‏ ‏نَفَرٍ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏سَبْعَةٍ فِيهِمْ ‏ ‏أَبُو جَهْلٍ ‏ ‏وَأُمَيَّةُ بْنُ خَلَفٍ ‏ ‏وَعُتْبَةُ بْنُ رَبِيعَةَ ‏ ‏وَشَيْبَةُ ‏ ‏وَعُقْبَةُ بْنُ أَبِي مُعَيْطٍ ‏ ‏فَأُقْسِمُ بِاللَّهِ لَقَدْ رَأَيْتُهُمْ ‏ ‏صَرْعَى ‏ ‏عَلَى ‏ ‏بَدْرٍ ‏ ‏وَقَدْ غَيَّرَتْهُمْ الشَّمْسُ وَكَانَ يَوْمًا حَارًّا ‏","","",""],[3588,3588,"","আমরা আমার বাবার সব থেকে ভালো সময় নিয়ে কথা বলেছি, সে বলল আমি ঈশ্বরের কাছে অনেক খুশি যে সে বলেছে সে কখনো ঈশ্বরের অনুগ্রহে ছিল না। এবং আমি আমার আগের চেয়ে দশ বার বেশি সময় ধরে এরকম ছিলাম। এবং আমি আমার বাবার কথা শুনেছি, আমার বাবার কথা কখনো শুনতে পাইনি। আমি মনে হয়, আমি ঈশ্বরের কাছে প্রার্থনা করছি, আমি ঈশ্বরের কাছে ক্ষমা প্রার্থনা করছি। এবং আমি আমার জীবনের সব সময় তোমার কাছে ফিরে এসেছি। এবং তুমি জানো না যে, তুমি জানো, তুমি আমাকে তোমার কাছে আমার বাবার সাথে ছিলে, তুমি জানো, তুমি আমার বাবা, তুমি আমাকে যে তুমি জানো না। তুমি জানো, তুমি জানো, তুমি আমাকে যে তুমি জানো না। তুমি তোমার জন্য না। তোমার জন্য, তুমি আমার বাবা, তুমি আমাকে তোমার কাছে আমার বাবা, তোমার কাছে আমার বাবা, তোমার কাছে আমার বাবা। তোমার কাছে এটা একটা ছোট্ট মেয়ে। আর ১০ বার হবে। আর ১০ বার। আর ১০ বার। আর ১০ বার আসবে। আর আমি তোমার কাছে ফিরেছি। আর ১০ বার তোমার কাছে এটা একটা প্রশ্ন করি। আর ১০ বার। আর ১০ বার। আর ১০ বার। তার সাথে দুই তিন জন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُنْذِرِ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ دِينَارٍ الْخُزَاعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَمْرَو بْنَ الْحَارِثِ الْخُزَاعِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏مَا صُمْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تِسْعًا وَعِشْرِينَ أَكْثَرُ مِمَّا صُمْتُ مَعَهُ ثَلَاثِينَ ‏","","",""],[3589,3589,"","আমি আমার বাবার সাথে অতীত নিয়ে কথা বলেছি, আমি ঈশ্বরের দোহাই নাচতে চাই, সে তাকে শিখিয়েছিলেন এবং সে পৃথিবীকে স্বপ্নে পরিণত করেছে. সেই লোক যে তাকে ডাকে","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعْدِ ‏ ‏أَوْ ‏ ‏سَعِيدِ بْنِ عِيَاضٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَحَبَّ ‏ ‏الْعَرْقِ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذِرَاعُ الشَّاةِ وَكَانَ يَرَى أَنَّهُ سُمَّ فِي ذِرَاعِ الشَّاةِ وَكُنَّا نَرَى أَنَّ ‏ ‏الْيَهُودَ ‏ ‏الَّذِينَ سَمُّوهُ ‏","","",""],[3590,3590,"","আমার ছোট্ট ছেলের কাছ থেকে ফিরে আসার বিষয়ে আমরা কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ عِيَاضٍ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏إِنَّ مِنْ ‏ ‏الْبَيَانِ ‏ ‏سِحْرًا قَالَ وَكُنَّا نَرَى أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُمَّ فِي ذِرَاعِ شَاةٍ سَمَّتْهُ ‏ ‏الْيَهُودُ ‏","","",""],[3591,3591,"","আমরা একটি ছেলে হয়েছে যে আমাকে সাহায্য করার চেষ্টা করছে একটি পৃথিবীর দর্শন দিয়ে, আমি তাকে কোন দেবতা পুত্র দেওয়া হয়েছে এবং আপনি কোন বলেন না তারা বলে, ঈশ্বর যদি আমাকে কিছু মনে না করেন, আমি কখনও ছেড়ে দেব না।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ سَعِيدٍ الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْكُمْ مِنْ أَحَدٍ إِلَّا وَمَعَهُ قَرِينُهُ مِنْ الْمَلَائِكَةِ وَمِنْ الْجِنِّ قَالُوا وَأَنْتَ يَا رَسُولَ اللَّهِ قَالَ وَأَنَا إِلَّا أَنَّ اللَّهَ أَعَانَنِي عَلَيْهِ فَأَسْلَمَ وَلَا يَأْمُرُنِي إِلَّا بِخَيْرٍ ‏","","",""],[3592,3592,"","আমরা আমার ঠোঁটকে মুছে ফেলার চেষ্টা করেছি। আর সে এমন একজন লোক যে আমাকে খুন করেছে, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তার কাছে প্রার্থনা করেছেন। তার শান্তি আর দয়া দেখা।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ الشَّيْبَانِيُّ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏زِرَّ بْنَ حُبَيْشٍ ‏ ‏وَعَلَيَّ دَرْبَانِ فَأُلْقِيَتْ عَلَيَّ مَحَبَّةٌ مِنْهُ وَعِنْدَهُ شَبَابٌ فَقَالُوا لِي سَلْهُ ‏ { ‏فَكَانَ ‏ ‏قَابَ ‏ ‏قَوْسَيْنِ أَوْ ‏ ‏أَدْنَى ‏ } ‏فَسَأَلْتُهُ فَقَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَلَهُ سِتُّ مِائَةِ جَنَاحٍ ‏","","",""],[3593,3593,"","আমরা মোশির কথা বলেছি, আমরা জনতার জন্য ভালো স্বাদ পেয়েছি, ঈশ্বর হয়তো ছেলে, বাবা হতে পারে সেই ব্যক্তি যে হবে সেই হবে সেই ব্যক্তি, যে হবে হবে সেই হবে হবে সেই ব্যক্তি, যে হবে হবে সেই ব্যক্তি যে লোক এই জন ্ য বেঁচে থাকবে সে-ই তবে যে ব ্ যক ্ তি হবে নিরাপদ , সে-ই হবে ক ্ ষমতার লোক , আর সে হবে একজন যে ব ্ যক ্ তি । সে হবে সেই ব্যক্তি যে হবে সেই হবে সেই ব্যক্তি যে রাজা হবে। আমি তোমাকে কত টাকা দিব। আমি ইশ্বরকে যা হারিয়েছি, তার থেকে আমি খুশি হতে চাই। সে বলল আমরা ঈশ্বরের কাছে প্রার্থনা করব এবং আমরা যখন বলেছিলাম আমরা তাকে আত্মসমর্পণ করবো তখন আমরা তাকে আত্মসমর্পণ করব।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْمُجَالِدِ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا عِنْدَ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏وَهُوَ يُقْرِئُنَا الْقُرْآنَ فَقَالَ لَهُ رَجُلٌ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏هَلْ سَأَلْتُمْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَمْ تَمْلِكُ هَذِهِ الْأُمَّةُ مِنْ خَلِيفَةٍ فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْعُودٍ ‏ ‏مَا سَأَلَنِي عَنْهَا أَحَدٌ مُنْذُ قَدِمْتُ ‏ ‏الْعِرَاقَ ‏ ‏قَبْلَكَ ثُمَّ قَالَ نَعَمْ وَلَقَدْ سَأَلْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏اثْنَا عَشَرَ كَعِدَّةِ ‏ ‏نُقَبَاءِ ‏ ‏بَنِي إِسْرَائِيلَ ‏","","",""],[3594,3594,"","আমরা এমন একটা ছেলেকে উদ্ধার করতে চেষ্টা করেছি, যে একটি ছেলে খুঁজে পাওয়ার প্রয়োজনীয়তা নিয়ে মাথা ঘামাচ্ছে। ঈশ্বর আমার অসহায় পুত্র, যে ঈশ্বরের অনুগ্রহে ও ঈশ্বরের ইচ্ছার উপর ভিত্তি করে আছে। ঈশ্বর তাকে আত্মসমর্পণ করতে বলেছেন, প্রভু, আমি আপনাকে একটি কথা দিয়ে পানি দিয়ে বলছি। ঈশ্বর তার জন্য প্রার্থনা করেন এবং তাকে আত্মসমর্পণ করতে বলেন, ঈশ্বর যেন সুখী হয়ে যান।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏حَنَشٍ الصَّنْعَانِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏أَنَّهُ كَانَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةَ الْجِنِّ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَبْدَ اللَّهِ ‏ ‏أَمَعَكَ مَاءٌ قَالَ مَعِي ‏ ‏نَبِيذٌ ‏ ‏فِي ‏ ‏إِدَاوَةٍ ‏ ‏فَقَالَ اصْبُبْ عَلَيَّ فَتَوَضَّأَ قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏شَرَابٌ وَطَهُورٌ ‏","","",""],[3595,3595,"","আমরা সবাই এত আশীর্বাদ লাভ করেছি বলে ঈশ্বরের খুশি যে তিনি ঈশ্বরের উপর পাপ করেছেন। এটা বলার ভাল উপায় বিক্রি করা হচ্ছে যে এটা একটা ছেলে, তাই ছেলেও ছেলে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏وأَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَفْقَتَيْنِ فِي صَفْقَةٍ وَاحِدَةٍ ‏ ‏قَالَ ‏ ‏أَسْوَدُ ‏ ‏قَالَ ‏ ‏شَرِيكٌ ‏ ‏قَالَ ‏ ‏سِمَاكٌ ‏ ‏الرَّجُلُ يَبِيعُ الْبَيْعَ فَيَقُولُ هُوَ ‏ ‏بِنَسَاءٍ ‏ ‏بِكَذَا وَكَذَا وَهُوَ بِنَقْدٍ بِكَذَا وَكَذَا ‏","","",""],[3596,3596,"","বাবার সাম্প্রতিক মেঘ দেখে আমি ঈশ্বরের বাপ্তাইজিত হওয়ার কথা বলেছিলাম। আমার বাবা তার প্রিয় প্রভুর কাছে ঈশ্বরের কাছে ফিরে আসবে। এখান থেকে চলে যাও, .","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏ابْنِ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْإِسْلَامَ بَدَأَ ‏ ‏غَرِيبًا ‏ ‏وَسَيَعُودُ ‏ ‏غَرِيبًا ‏ ‏كَمَا بَدَأَ ‏ ‏فَطُوبَى ‏ ‏لِلْغُرَبَاءِ قِيلَ وَمَنْ الْغُرَبَاءُ قَالَ ‏ ‏النُّزَّاعُ ‏ ‏مِنْ الْقَبَائِلِ ‏","","",""],[3597,3597,"","আমরা আমার ভালোবাসার রাজধানীর জন্য বাপ্তাইজিত হওয়ার কারণ এবং যা আছে তার জন্য ঈশ্বরের এমন একজন মানুষ হতে হবে যে কখনো কারো সাথে কোন কিছু করেনি, আমাকে নিয়ে যাও এবং আগুন জ্বালাও। আমাকে ল্যাডারে ফোন না করা পর্যন্ত তারা আমাকে কসম খেয়ে বলে যে তারা আমাকে একটা উইন্ডশিল্ডের কাছে সতর্ক করে দিয়েছে। বাবা তার বাবার জন্য ভালো মানুষ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَنْبَأَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَجُلًا لَمْ يَعْمَلْ مِنْ الْخَيْرِ شَيْئًا قَطُّ إِلَّا التَّوْحِيدَ فَلَمَّا حَضَرَتْهُ الْوَفَاةُ قَالَ لِأَهْلِهِ إِذَا أَنَا مِتُّ فَخُذُونِي وَاحْرُقُونِي حَتَّى تَدَعُونِي حُمَمَةً ثُمَّ اطْحَنُونِي ثُمَّ ‏ ‏اذْرُونِي ‏ ‏فِي الْبَحْرِ فِي يَوْمٍ ‏ ‏رَاحٍ ‏ ‏قَالَ فَفَعَلُوا بِهِ ذَلِكَ قَالَ فَإِذَا هُوَ فِي قَبْضَةِ اللَّهِ قَالَ فَقَالَ اللَّهُ عَزَّ وَجَلَّ لَهُ ‏ ‏مَا حَمَلَكَ عَلَى مَا صَنَعْتَ قَالَ مَخَافَتُكَ قَالَ فَغَفَرَ اللَّهُ لَهُ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏","","",""],[3598,3598,"","আমরা যা করেছি তার চেয়ে ভাল শিখেছি, তার মহান পুত্র, তিনি আমাদের ঈশ্বরের কাছে আমাদের ছেলেকে নিয়ে এসেছে, ঈশ্বরের কাছে আমাদের মা। বিয়ে আর সে তার মৃত্যুর জন্য দারুণ বিস্ময়কর ছিল, সে বলেছিল যে অতিথিটি রাজার মৃত্যুর মাঝে ছিল। আমরা খুশি এবং গোপন ভাবে তাকে ছেড়ে দিয়েছি। আপনার মা ভন্ডের একজন মানুষ বলেছে... ...আর হঠাৎ করে সে তার মায়ের কথা বলে আর আমরা এর জন্য পড়ে যাই, স্যার. আমি এটা করি না, একজন ডাইনির জিনিয়াসই হবে প্রথম নির্দোষ হওয়া। একটা চিহ্ন বলে ঈশ্বর ইতিমধ্যেই এমন লড়াই করেছেন, যা আমার পক্ষে করা সম্ভব নয় । অথবা হিট, সে একটা স্ক্যাকার ছিল। ভন্ডের কাছে যাওয়া পর্যন্ত সে আমাদের সব কথা শুনেনি। ওর পিছে যেতে হবে আর জেলোর তার প্রতিজ্ঞা দেখতে পায়নি।","‏ ‏حَدَّثَنَا ‏ ‏عَارِمُ بْنُ الْفَضْلِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْحَكَمِ الْبُنَانِيُّ ‏ ‏عَنْ ‏ ‏عُثْمَانَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏وَالْأَسْوَدِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏جَاءَ ابْنَا ‏ ‏مُلَيْكَةَ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَا إِنَّ أُمَّنَا كَانَتْ تُكْرِمُ الزَّوْجَ وَتَعْطِفُ عَلَى الْوَلَدِ قَالَ وَذَكَرَ الضَّيْفَ غَيْرَ أَنَّهَا كَانَتْ وَأَدَتْ فِي الْجَاهِلِيَّةِ قَالَ أُمُّكُمَا فِي النَّارِ فَأَدْبَرَا وَالشَّرُّ يُرَى فِي وُجُوهِهِمَا فَأَمَرَ بِهِمَا فَرُدَّا فَرَجَعَا وَالسُّرُورُ يُرَى فِي وُجُوهِهِمَا رَجِيَا أَنْ يَكُونَ قَدْ حَدَثَ شَيْءٌ فَقَالَ أُمِّي مَعَ أُمِّكُمَا فَقَالَ رَجُلٌ مِنْ الْمُنَافِقِينَ وَمَا يُغْنِي هَذَا عَنْ أُمِّهِ شَيْئًا وَنَحْنُ نَطَأُ ‏ ‏عَقِبَيْهِ ‏ ‏فَقَالَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَلَمْ أَرَ رَجُلًا قَطُّ أَكْثَرَ سُؤَالًا مِنْهُ يَا رَسُولَ اللَّهِ هَلْ وَعَدَكَ رَبُّكَ فِيهَا ‏ ‏أَوْ فِيهِمَا ‏ ‏قَالَ فَظَنَّ أَنَّهُ مِنْ شَيْءٍ قَدْ سَمِعَهُ فَقَالَ ‏ ‏مَا سَأَلْتُهُ رَبِّي وَمَا أَطْمَعَنِي فِيهِ وَإِنِّي لَأَقُومُ الْمَقَامَ الْمَحْمُودَ يَوْمَ الْقِيَامَةِ فَقَالَ الْأَنْصَارِيُّ وَمَا ذَاكَ الْمَقَامُ الْمَحْمُودُ قَالَ ذَاكَ إِذَا جِيءَ بِكُمْ عُرَاةً حُفَاةً ‏ ‏غُرْلًا ‏ ‏فَيَكُونُ أَوَّلَ مَنْ ‏ ‏يُكْسَى ‏ ‏إِبْرَاهِيمُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏يَقُولُ اكْسُوا ‏ ‏خَلِيلِي ‏ ‏فَيُؤْتَى بِرَيْطَتَيْنِ بَيْضَاوَيْنِ فَلَيَلْبِسْهُمَا ثُمَّ يَقْعُدُ فَيَسْتَقْبِلُ الْعَرْشَ ثُمَّ أُوتَى بِكِسْوَتِي فَأَلْبَسُهَا فَأَقُومُ عَنْ يَمِينِهِ مَقَامًا لَا يَقُومُهُ أَحَدٌ ‏ ‏غَيْرِي ‏ ‏يَغْبِطُنِي ‏ ‏بِهِ الْأَوَّلُونَ وَالْآخِرُونَ قَالَ وَيُفْتَحُ نَهَرٌ مِنْ الْكَوْثَرِ إِلَى الْحَوْضِ فَقَالَ الْمُنَافِقُونَ فَإِنَّهُ مَا جَرَى مَاءٌ قَطُّ إِلَّا عَلَى ‏ ‏حَالٍ ‏ ‏أَوْ ‏ ‏رَضْرَاضٍ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ عَلَى ‏ ‏حَالٍ ‏ ‏أَوْ ‏ ‏رَضْرَاضٍ ‏ ‏قَالَ حَالُهُ ‏ ‏الْمِسْكُ ‏ ‏وَرَضْرَاضُهُ ‏ ‏التُّومُ ‏ ‏قَالَ الْمُنَافِقُ لَمْ أَسْمَعْ كَالْيَوْمِ قَلَّمَا جَرَى مَاءٌ قَطُّ عَلَى ‏ ‏حَالٍ ‏ ‏أَوْ ‏ ‏رَضْرَاضٍ ‏ ‏إِلَّا كَانَ لَهُ نَبْتَةٌ فَقَالَ الْأَنْصَارِيُّ يَا رَسُولَ اللَّهِ هَلْ لَهُ نَبْتٌ قَالَ نَعَمْ قُضْبَانُ الذَّهَبِ قَالَ الْمُنَافِقُ لَمْ أَسْمَعْ كَالْيَوْمِ فَإِنَّهُ قَلَّمَا نَبَتَ ‏ ‏قَضِيبٌ ‏ ‏إِلَّا أَوْرَقَ وَإِلَّا كَانَ لَهُ ثَمَرٌ قَالَ الْأَنْصَارِيُّ يَا رَسُولَ اللَّهِ هَلْ مِنْ ثَمَرٍ قَالَ نَعَمْ أَلْوَانُ ‏ ‏الْجَوْهَرِ وَمَاؤُهُ أَشَدُّ بَيَاضًا مِنْ اللَّبَنِ وَأَحْلَى مِنْ الْعَسَلِ إِنَّ مَنْ شَرِبَ مِنْهُ مَشْرَبًا لَمْ يَظْمَأْ بَعْدَهُ وَإِنْ حُرِمَهُ لَمْ يُرْوَ بَعْدَهُ ‏","","",""],[3599,3599,"","আমরা আমার বাবার কথা বলেছিলাম তিনি যা বলেছেন, সেটা ঈশ্বরের দ্বারা করা হয়েছে যে তিনি জয়ী হতে পেরে খুশি। ঈশ্বর তাকে জিজ্ঞেস করেছেন এবং আমরা যা ভেবেছিলাম, তিনি তাই ভেবেছিলেন। তুমি বেরিয়ে গিয়েছিলে, তুমি বলেছিলে আমি চলে যাবো আর বলবো, \"ঈশ্বর এটা পেয়েছেন\" তারপর তিনি বলেছিলেন তারা ছিল ঐ জারজরা, অথবা সে কিভাবে বলেছিল ঈশ্বর তাদের বলেন যে, তারা আমাকে বেছে নেবে বা তারা আমাকে বেছে নেবে । নাহলে আমি তাদের কাছে ক্লান্ত হয়ে পড়ি আর সে বলে যে সে বসে থাকবে বা সে খারাপ হয়ে যাবে। তারপর খোদা তার জন্য প্রার্থনা করবে এবং সে আবার ফিরে আসবে এবং তারপর সে আবার চলে আসবে এবং প্রায় প্রায় প্রায় তৈরি হয়ে যাবে। তারপর সে তার মাথা দুটো ঢুকিয়ে বললো, আবার সে বলেছে, আমি ওদেরকে ঘুরিয়ে দেব অথবা আমি কি করে দেব। আমি কি করে আল্লাহকে স্বপ্নে পরিণত করবো, আমি তা খুঁজে বের করবো। প্রথমে এটা মারার চেষ্টা করে আমি ধ্বংস করবো। অথবা তারা কিভাবে বলেছে, সে নাকি মারা গেছে, তাদের মধ্যে কেউ কেউ মারা যাবে আর আমরা কিভাবে করতে পারি? তুমি বলতে চাচ্ছ তাদের কেউ কেউ আঘাত করছে, কেউ কেউ তাদের নিজের প্রভুর মত... ...সে কোন কোনায় নির্মিত হবে না, না সে তার পিছু নেয়নি বা না নেয় না। তাকে নির্যাতন কর বা না কর, সে চলে গেছে, তার ছেলে আত্মসমর্পণ করে এবং আমি তাকে অনুসরণ করে অপরাধীদের অনুসরণ করি, যে কিনা তাকে নির্যাতন করে না বা কিভাবে করে। ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তারা তাদের সমর্পণ করবেন, ফেরেশতা থেকে আসে বা বলে তারা দেবতা.","‏ ‏حَدَّثَنَا ‏ ‏عَارِمٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏قَالَ قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنِي ‏ ‏أَبُو تَمِيمَةَ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏لَعَلَّهُ أَنْ يَكُونَ قَدْ قَالَ ‏ ‏الْبِكَالِيَّ ‏ ‏يُحَدِّثُهُ ‏ ‏عَمْرٌو ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏إِنَّ ‏ ‏عَبْدَ اللَّهِ ‏ ‏قَالَ ‏ ‏اسْتَبْعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَانْطَلَقْنَا حَتَّى أَتَيْتُ مَكَانَ كَذَا وَكَذَا فَخَطَّ لِي خِطَّةً فَقَالَ لِي كُنْ بَيْنَ ظَهْرَيْ هَذِهِ لَا تَخْرُجْ مِنْهَا فَإِنَّكَ إِنْ خَرَجْتَ هَلَكْتَ قَالَ فَكُنْتُ فِيهَا قَالَ فَمَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَذَفَةً ‏ ‏أَوْ أَبْعَدَ شَيْئًا أَوْ كَمَا قَالَ ‏ ‏ثُمَّ إِنَّهُ ذَكَرَ ‏ ‏هَنِينًا ‏ ‏كَأَنَّهُمْ ‏ ‏الزُّطُّ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏أَوْ كَمَا قَالَ ‏ ‏عَفَّانُ ‏ ‏إِنْ شَاءَ اللَّهُ لَيْسَ عَلَيْهِمْ ثِيَابٌ وَلَا أَرَى سَوْآتِهِمْ طِوَالًا قَلِيلٌ لَحْمُهُمْ قَالَ فَأَتَوْا فَجَعَلُوا يَرْكَبُونَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَجَعَلَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ عَلَيْهِمْ قَالَ وَجَعَلُوا يَأْتُونِي فَيُخَيِّلُونَ ‏ ‏أَوْ يَمِيلُونَ ‏ ‏حَوْلِي وَيَعْتَرِضُونَ لِي قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَأُرْعِبْتُ مِنْهُمْ رُعْبًا شَدِيدًا قَالَ فَجَلَسْتُ ‏ ‏أَوْ كَمَا قَالَ ‏ ‏قَالَ فَلَمَّا ‏ ‏انْشَقَّ ‏ ‏عَمُودُ الصُّبْحِ جَعَلُوا يَذْهَبُونَ ‏ ‏أَوْ كَمَا قَالَ ‏ ‏قَالَ ثُمَّ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَ ثَقِيلًا وَجِعًا ‏ ‏أَوْ يَكَادُ أَنْ يَكُونَ وَجِعًا ‏ ‏مِمَّا رَكِبُوهُ قَالَ إِنِّي لَأَجِدُنِي ثَقِيلًا ‏ ‏أَوْ كَمَا قَالَ ‏ ‏فَوَضَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأْسَهُ فِي حِجْرِي ‏ ‏أَوْ كَمَا قَالَ ‏ ‏قَالَ ثُمَّ إِنَّ ‏ ‏هَنِينًا ‏ ‏أَتَوْا عَلَيْهِمْ ثِيَابٌ بِيضٌ طِوَالٌ ‏ ‏أَوْ كَمَا قَالَ ‏ ‏وَقَدْ أَغْفَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَأُرْعِبْتُ مِنْهُمْ أَشَدَّ مِمَّا ‏ ‏أُرْعِبْتُ ‏ ‏الْمَرَّةَ الْأُولَى ‏ ‏قَالَ ‏ ‏عَارِمٌ ‏ ‏فِي حَدِيثِهِ قَالَ فَقَالَ بَعْضُهُمْ لِبَعْضٍ ‏ ‏لَقَدْ أُعْطِيَ هَذَا الْعَبْدُ خَيْرًا ‏ ‏أَوْ كَمَا قَالُوا ‏ ‏إِنَّ عَيْنَيْهِ نَائِمَتَانِ ‏ ‏أَوْ قَالَ عَيْنَهُ أَوْ كَمَا قَالُوا ‏ ‏وَقَلْبَهُ يَقْظَانُ ثُمَّ قَالَ ‏ ‏قَالَ ‏ ‏عَارِمٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَ بَعْضُهُمْ لِبَعْضٍ هَلُمَّ فَلْنَضْرِبْ لَهُ مَثَلًا ‏ ‏أَوْ كَمَا قَالُوا ‏ ‏قَالَ بَعْضُهُمْ لِبَعْضٍ ‏ ‏اضْرِبُوا لَهُ مَثَلًا وَنُؤَوِّلُ نَحْنُ أَوْ نَضْرِبُ نَحْنُ وَتُؤَوِّلُونَ أَنْتُمْ فَقَالَ بَعْضُهُمْ لِبَعْضٍ مَثَلُهُ كَمَثَلِ سَيِّدٍ ابْتَنَى بُنْيَانًا حَصِينًا ثُمَّ أَرْسَلَ إِلَى النَّاسِ بِطَعَامٍ ‏ ‏أَوْ كَمَا قَالَ ‏ ‏فَمَنْ لَمْ يَأْتِ طَعَامَهُ ‏ ‏أَوْ قَالَ لَمْ يَتْبَعْهُ ‏ ‏عَذَّبَهُ عَذَابًا شَدِيدًا ‏ ‏أَوْ كَمَا قَالُوا ‏ ‏قَالَ الْآخَرُونَ أَمَّا السَّيِّدُ فَهُوَ رَبُّ الْعَالَمِينَ وَأَمَّا الْبُنْيَانُ فَهُوَ الْإِسْلَامُ وَالطَّعَامُ الْجَنَّةُ وَهُوَ الدَّاعِي فَمَنْ اتَّبَعَهُ كَانَ فِي الْجَنَّةِ ‏ ‏قَالَ ‏ ‏عَارِمٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏أَوْ كَمَا قَالُوا ‏ ‏وَمَنْ لَمْ يَتَّبِعْهُ عُذِّبَ ‏ ‏أَوْ كَمَا قَالَ ‏ ‏ثُمَّ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَيْقَظَ فَقَالَ مَا رَأَيْتَ يَا ‏ ‏ابْنَ أُمِّ عَبْدٍ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏رَأَيْتُ كَذَا وَكَذَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا خَفِيَ عَلَيَّ مِمَّا قَالُوا شَيْءٌ قَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُمْ ‏ ‏نَفَرٌ ‏ ‏مِنْ الْمَلَائِكَةِ ‏ ‏أَوْ قَالَ هُمْ مِنْ الْمَلَائِكَةِ أَوْ كَمَا شَاءَ اللَّهُ ‏","","",""],[3600,3600,"","আমরা ঈশ্বরের শোকের কথা বলেছি, কিন্তু আমাদের ভালবাসা, আমরা পৃথিবীকে খুঁজে পেতে চেষ্টা করেছি, সে ঈশ্বরকে বলে যে সে কখনও খেতে দেয় নি। বিশ্বাস করুন কে তার হৃদয়ে ছিল, তার ভালোবাসাকে না বলে আমি আমার পোশাকের পোশাকের প্রতি না বলি এবং চুপচাপ চলে যাই। কিন্তু বড় বড় হবে যে বেঁচে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏عَارِمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ الْقَسْمَلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ جَعْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَدْخُلُ النَّارَ مَنْ كَانَ فِي قَلْبِهِ ‏ ‏مِثْقَالُ ‏ ‏حَبَّةٍ مِنْ إِيمَانٍ وَلَا يَدْخُلُ الْجَنَّةَ مَنْ كَانَ فِي قَلْبِهِ ‏ ‏مِثْقَالُ ‏ ‏حَبَّةٍ مِنْ كِبْرٍ فَقَالَ ‏ ‏رَجُلٌ ‏ ‏يَا رَسُولَ اللَّهِ إِنِّي لَيُعْجِبُنِي أَنْ يَكُونَ ثَوْبِي غَسِيلًا وَرَأْسِي دَهِينًا ‏ ‏وَشِرَاكُ ‏ ‏نَعْلِي جَدِيدًا وَذَكَرَ أَشْيَاءَ حَتَّى ذَكَرَ عِلَاقَةَ سَوْطِهِ أَفَمِنْ الْكِبْرِ ذَاكَ يَا رَسُولَ اللَّهِ قَالَ لَا ذَاكَ الْجَمَالُ إِنَّ اللَّهَ جَمِيلٌ يُحِبُّ الْجَمَالَ وَلَكِنَّ الْكِبْرَ مَنْ سَفِهَ الْحَقَّ وَازْدَرَى النَّاسَ ‏","","",""]];
